const navIcon=(key,active=false)=>{const shapes={overview:active?'<path d="M2 10 12 2l10 8v12h-7v-8H9v8H2Z"/>':'<path d="M3 10 12 3l9 7v11h-7v-7h-4v7H3Z"/>',transactions:active?'<circle cx="12" cy="12" r="10"/><path d="M12 7v10M7 12h10" stroke="var(--on-accent)"/>':'<rect x="3" y="3" width="18" height="18" rx="5"/><path d="M12 7v10M7 12h10"/>',cash:active?'<path d="M3 21V14l6-6 4 4 8-9v18Z"/>':'<path d="M3 18 9 12l4 4 8-12M15 4h6v6M3 22h18"/>',copilot:active?'<path d="M3 3h18v14H9l-6 5Z"/>':'<path d="M3 3h18v14H9l-6 5Z"/><path d="M7 8h10M7 12h6"/>',more:active?'<circle cx="4" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="20" cy="12" r="2"/>':'<circle cx="4" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="20" cy="12" r="1.5"/>'};return `<svg viewBox="0 0 24 24" fill="${active?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[key]}</svg>`;};
