let lang=localStorage.getItem('finora-lang')||'zh',org=localStorage.getItem('finora-org')||'shenzhen',page=location.hash.slice(1)||'overview',period=30,filter='',statusFilter='all',kindFilter='receivable',expenseCategory='all',scenario={days:30,growth:0,delay:0,expense:0,hiring:0,supplierDelay:0,oneOff:0},loanInput={principal:8000000,apr:8,months:12,fee:1},showFinance=false,importPreview=null;
