const labels={overview:['Overview','总览'],cash:['Expected future cash','未来现金预测'],invoices:['Invoices','发票管理'],expenses:['Money spent','支出的钱'],financing:['Financing','融资分析'],risk:['Risk center','风险中心'],reports:['Reports','财务报告'],copilot:['AI copilot','AI助手'],settings:['Settings & data','设置与数据'],revenue:['Money received','收到的钱'],profit:['Money received minus spent','收款减去支出'],ar:['Money owed to you','别人欠你的钱'],ap:['Money you owe','你需要支付的钱'],overdue:['Late customer payments','逾期客户回款'],cashBalance:['Money available now','现在可用的钱'],minimum:['Lowest projected cash','最低预计现金'],need:['Extra cash needed incl. buffer','含备用金所需额外现金'],impact:['Change vs. base case','相对基准变化'],previous:['Previous period','上一期间'],change:['Period change','期间变化'],reserve:['Emergency cash buffer','应急现金备用金'],shortfall:['Cash deficit','现金短缺']};
labels.pdfreceipts=['Upload PDF receipt','上传PDF收据'];labels.rescue=['Cash Rescue Planner','现金纾困规划'];labels.receipts=['Decision receipts','决策凭据'];
labels.actionplan=['Cash action plan','现金行动计划'];labels.quality=['Forecast confidence & evidence','预测依据与证据'];labels.reconcile=['Reconciliation review','对账核查'];
labels.options=['Compare your options','比较解决方案'];labels.transactions=['Money entries','收支记录'];const label=k=>labels[k]?t(...labels[k]):k;
const money=(c,digits=0)=>new Intl.NumberFormat(lang==='zh'?'zh-CN':'en-US',{style:'currency',currency:'CNY',minimumFractionDigits:digits,maximumFractionDigits:digits}).format(c/100);
const date=d=>new Intl.DateTimeFormat(lang==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));
const profile=()=>profiles.find(p=>p.id===org),businessName=()=>data.settings.name===profile().en?profile()[lang==='zh'?'zh':'en']:data.settings.name,party=i=>lang==='zh'&&i.partyZh?i.partyZh:i.party;
function load(){try{const saved=JSON.parse(localStorage.getItem('finora-'+org));return saved?validateData(saved):seed(org);}catch{return seed(org);}}
let data=load(),pending=false,providerMode='demo';function save(){try{if(accountState.user){markSync();return true;}localStorage.setItem('finora-'+org,JSON.stringify(data));markSync();return true;}catch{toast(t('Storage is full or unavailable. Export a backup before closing.','存储空间已满或不可用。关闭前请导出备份。'));return false;}}
function log(action,record){if(['invoice_created','invoice_updated','payment_recorded','import','settings'].includes(action))for(const c of data.chats){delete c.aiExplanation;delete c.live;}data.audit.unshift({date:new Date().toISOString(),action,record});data.audit=data.audit.slice(0,200);}
const btn=(text,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(text,c='')=>`<span class="badge ${c}">${text}</span>`;
function toast(msg){$('#toast').className='toast';$('#toast').textContent=msg;setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},4000);}
function go(p){page=p;filter='';location.hash=p;render();$('.sidebar')?.classList.remove('open');}
function range(){if(period==='custom'){return {start:$('#startdate')?.value||addDays(AS_OF,-29),end:$('#enddate')?.value||AS_OF};}return {start:addDays(AS_OF,-period+1),end:AS_OF};}
let custom={start:addDays(AS_OF,-29),end:AS_OF};function stats(){const r=period==='custom'?custom:range();return summary(data,r.start,r.end);}
function compare(){const s=stats(),n=daysBetween(s.start,s.end)+1;return summary(data,addDays(s.start,-n),addDays(s.start,-1));}
function delta(current,old,cost=false){if(!old)return t('No comparable prior value','无可比前期数值');const pct=(current-old)/old*100;return `<span class="delta ${(cost?pct>0:pct<0)?'negative':''}">${pct>=0?'↗':'↘'} ${Math.abs(pct).toFixed(1)}% <span class="muted">${t('vs. previous period','较上一期间')}</span></span>`;}
function kpi(name,value,foot,action,dark=false){return `<button class="kpi ${dark?'dark':''}" data-action="nav" data-page="${action}"><span class="label">${label(name)}${icon(action)}</span><strong>${money(value)}</strong><span class="foot">${foot}</span></button>`;}
function periodControl(){return `<select id="period" aria-label="${t('Reporting period','报告期间')}">${[7,30,90].map(n=>`<option value="${n}" ${period===n?'selected':''}>${t(`Last ${n} days`,`最近${n}天`)}</option>`).join('')}<option value="custom" ${period==='custom'?'selected':''}>${t('Custom dates','自定义日期')}</option></select>${period==='custom'?`<input id="startdate" aria-label="${t('Start date','开始日期')}" type="date" value="${custom.start}" max="${AS_OF}"><input id="enddate" aria-label="${t('End date','结束日期')}" type="date" value="${custom.end}" max="${AS_OF}">`:''}`;}
function chart(series,h=205){const w=670,pad={l:54,r:12,t:18,b:25};const all=series.flatMap(s=>s.points.map(p=>p.cash));const lower=Math.min(0,...all,data.settings.reserve),upper=Math.max(1,...all,data.settings.reserve);const span=upper-lower||1,lo=lower-span*.1,hi=upper+span*.08;const y=v=>pad.t+(hi-v)/(hi-lo)*(h-pad.t-pad.b);const x=(i,n)=>pad.l+i/(n-1||1)*(w-pad.l-pad.r);
 const grid=[0,.25,.5,.75,1].map(f=>{const value=lo+(hi-lo)*f,yy=y(value);return `<line x1="${pad.l}" x2="${w-pad.r}" y1="${yy}" y2="${yy}" stroke="var(--chart-grid)"/><text x="${pad.l-10}" y="${yy+4}" text-anchor="end">${value<0?'−':''}¥${Math.abs(value/100000).toFixed(0)}k</text>`;}).join('');const dots=series.map((s,j)=>{const points=s.points.map((p,i)=>`${x(i,s.points.length)},${y(p.cash)}`).join(' ');const area=points+` ${w-pad.r},${h-pad.b} ${pad.l},${h-pad.b}`;return `${j===0?`<polygon points="${area}" fill="url(#fade)"/>`:''}<polyline points="${points}" fill="none" stroke="${s.color}" stroke-width="2.4" ${j?'stroke-dasharray="5 4"':''}/>${s.points.map((p,i)=>`<circle tabindex="0" cx="${x(i,s.points.length)}" cy="${y(p.cash)}" r="2.2" fill="${s.color}" aria-label="${esc(s.name+' · '+date(p.date)+' · '+money(p.cash))}"><title>${esc(s.name+' · '+date(p.date)+' · '+money(p.cash))}${p.evidence?.length?' · '+esc(p.evidence.join(', ')):''}</title></circle>`).join('')}`;}).join('');const pts=series[0].points;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${t('Projected cash balance chart. Hover or focus points for values.','预计现金余额图。悬停或聚焦数据点可查看数值。')}"><defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--chart-primary)" stop-opacity=".14"/><stop offset="1" stop-color="var(--chart-primary)" stop-opacity="0"/></linearGradient></defs>${grid}<line x1="${pad.l}" x2="${w-pad.r}" y1="${y(data.settings.reserve)}" y2="${y(data.settings.reserve)}" stroke="var(--buffer-line)" stroke-dasharray="4 4"/><text x="${w-pad.r}" y="${y(data.settings.reserve)-6}" text-anchor="end" fill="var(--status-warning)">${t('Reserve','储备')} ${money(data.settings.reserve)}</text>${dots}${[0,.25,.5,.75,1].map(f=>{const i=Math.round(f*(pts.length-1));return `<text x="${x(i,pts.length)}" y="${h-3}" text-anchor="middle">${date(pts[i].date)}</text>`;}).join('')}</svg>`;}
function trend(){const months=['2026-07','2026-08','2026-09','2026-10'],records=months.map(m=>summary(data,m+'-01',m+'-31')),max=Math.max(...records.flatMap(s=>[s.revenue,s.expenses]),1);return `<svg class="chart" viewBox="0 0 310 143" role="img" aria-label="${t('Monthly recorded revenue and expenses; July and October are partial.','每月已记录收入和支出；7月与10月为不完整期间。')}">${[0,1,2].map(i=>`<line x1="20" x2="302" y1="${20+i*45}" y2="${20+i*45}" stroke="var(--chart-grid)"/>`).join('')}${records.map((s,i)=>`<rect x="${35+i*70}" y="${110-s.revenue/max*90}" width="17" height="${s.revenue/max*90}" rx="3" fill="var(--chart-primary)"><title>${months[i]} ${label('revenue')}: ${money(s.revenue)}</title></rect><rect x="${56+i*70}" y="${110-s.expenses/max*90}" width="17" height="${s.expenses/max*90}" rx="3" fill="var(--chart-secondary)"><title>${months[i]} ${label('expenses')}: ${money(s.expenses)}</title></rect><text x="${54+i*70}" y="133" text-anchor="middle">${t(['Jul*','Aug','Sep','Oct*'][i],['7月*','8月','9月','10月*'][i])}</text>`).join('')}</svg>`;}
const riskText={cash:['Cash needs a closer look','现金流需要重点关注'],overdue:['Bring overdue payments forward','优先跟进逾期回款'],duplicate:['Review a possible duplicate','核查可能重复的支出'],concentration:['Receivables depend on one customer','应收款集中于单一客户']};
const riskDescription=r=>r.id==='cash'?t(`The projected trough is ${date(r.date)}. ${money(r.amount)} would restore your reserve.`,`预计最低点在${date(r.date)}。需要${money(r.amount)}才能恢复储备。`):r.id==='overdue'?t(`${money(r.amount)} is past due. Expected collection is not guaranteed.`,`${money(r.amount)}已逾期。预计回款时间尚未得到保证。`):r.id==='duplicate'?t(`Same vendor, date and amount. ${money(r.amount)} may be duplicated; verify documents first.`,`同一供应商、日期与金额。${money(r.amount)}可能重复；请先核对凭证。`):t(`${money(r.amount)} is concentrated in a single invoice. Delays may affect available cash.`,`${money(r.amount)}集中于一张发票。回款延迟可能影响可用现金。`);
function riskRows(){return risks(data).filter(r=>!data.reviewed.includes(r.id)).slice(0,3).map(r=>`<div class="actionrow"><div class="actionicon">${icon(r.id==='cash'?'cash':r.id==='overdue'?'invoices':'risk')}</div><div><h3>${t(...riskText[r.id])}</h3><p>${riskDescription(r)}</p></div><button class="arrow" data-action="nav" data-page="${r.route}" aria-label="${t('Investigate','查看详情')}">${icon('arrow')}</button></div>`).join('')||`<p class="muted small">${t('All current alerts reviewed. Forecast risks still apply.','当前提醒均已核查。预测风险仍然存在。')}</p>`;}
function invoiceTable(items,compact=false){return items.length?`<div class="tablewrap"><table><thead><tr><th>${t('Invoice / customer','发票 / 客户')}</th><th>${t('Due date','到期日')}</th><th>${t('Status','状态')}</th><th class="money">${t('Outstanding','未结金额')}</th>${compact?'':'<th></th>'}</tr></thead><tbody>${items.map(i=>`<tr><td><button class="textbtn" data-action="invoice" data-id="${esc(i.id)}">${esc(i.id)}</button><div class="small muted">${esc(party(i))}</div></td><td>${date(i.due)}</td><td>${statusBadge(i)}</td><td class="money">${money(outstanding(i),2)}</td>${compact?'':`<td><button class="textbtn" data-action="invoice" data-id="${esc(i.id)}">${t('View','查看')} →</button></td>`}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('invoices')}<h3>${data.invoices.some(i=>i.kind===kindFilter)?t('No matching invoices','没有匹配的发票'):t("You haven't created any invoices yet",'您还没有创建发票')}</h3><p>${t('Invoices track money owed to you and bills you need to pay. Change filters or create your first invoice; cash changes only when payment is recorded.','发票用于跟踪客户欠款及应付账单。可调整筛选或创建首张发票；只有记录实际付款后现金才改变。')}</p>${btn(t('Create your first invoice','创建首张发票'),'newinvoice','primary',accountState.user&&accountState.role==='viewer'?'disabled':'')}<p></p></div>`;}
function statusBadge(i){const s=status(i);return badge(t({paid:'Recorded paid',overdue:'Overdue',partial:'Part paid',pending:'Pending'}[s],{paid:'已记录结清',overdue:'逾期',partial:'部分结清',pending:'待结清'}[s]),s==='overdue'?'amber':s==='paid'?'':s==='partial'?'gray':'gray');}
function dashboard(){const s=stats(),p=compare(),f=forecast(data);return `<div class="headrow"><div><div class="eyebrow muted">${t('Your financial command center','您的财务决策中心')}</div><h1 style="margin-top:6px">${t('A clear view. A smarter next move.','看清财务，迈出明智下一步。')}</h1><p class="subtitle">${t('Smarter cash flow. Stronger businesses.','智慧管现金流，助力企业成长。')}</p></div>${btn(icon('down')+t('Export report','导出报告'),'report')}</div><div class="filters">${periodControl()}<span class="muted small" style="align-self:center">${date(s.start)} — ${date(s.end)} · ${t('Cash basis','现金制')}</span></div>${f.first?`<div class="banner">${icon('risk')}<div><strong>${t(`A cash gap is projected on ${date(f.first.date)}.`,`预计${date(f.first.date)}出现现金缺口。`)}</strong><br><span class="muted">${t('See what is driving it — and compare your next options.','了解原因，并比较下一步方案。')}</span></div>${btn(t('Ask copilot','询问助手')+' →','askcash')}</div>`:''}<div class="kpis">${kpi('cashBalance',s.cash,t('As of 13 Oct · ledger reconciled','截至10月13日 · 已核对账本'),'cash',true)}${kpi('revenue',s.revenue,delta(s.revenue,p.revenue),'reports')}${kpi('expenses',s.expenses,delta(s.expenses,p.expenses,true),'expenses')}${kpi('profit',s.profit,t('Receipts less disbursements · not accrual profit','收入减支出 · 非权责发生制利润'),'reports')}</div><section class="card"><div class="cardhead"><div><h2>${t('Look ahead, stay in control','提前看见，掌控现金流')}</h2><p>${t('Projected closing cash · timing matters','预计日末现金 · 付款时间很重要')}</p></div><div class="pills">${[30,60,90].map(n=>`<button data-action="horizon" data-days="${n}" class="${scenario.days===n?'active':''}">${n}${t('D','天')}</button>`).join('')}</div></div><div class="legend"><span><i class="dot"></i>${t('Base forecast','基准预测')}</span><span><i class="dot navy"></i>${t('15% sales decline','销售下降15%')}</span>${badge(t('Scenario estimate','情景估计'),'gray')}</div>${chart([{name:t('Base','基准'),points:forecast(data,{days:scenario.days}).points,color:'var(--chart-primary)'},{name:t('Stress','压力'),points:forecast(data,{days:scenario.days,growth:-15}).points,color:'var(--chart-secondary)'}])}<div class="chartfoot"><div>${t('30-day low point','30天最低点')}<strong style="color:${f.min.cash<0?'var(--red)':'var(--ink)'}">${money(f.min.cash)} <span class="small muted">${date(f.min.date)}</span></strong></div><div>${t('30-day closing cash','30天期末现金')}<strong>${money(f.closing)}</strong></div><div>${t('Averages + scheduled obligations','日均值 + 已安排款项')}<br><button class="textbtn" data-action="nav" data-page="cash">${t('Explore assumptions','查看假设')} →</button></div></div></section><div class="two"><section class="card"><div class="cardhead"><h2>${t('Your next best actions','优先行动')}</h2>${badge(t(`${risks(data).length} signals`,`${risks(data).length}项信号`),'amber')}</div>${riskRows()}</section><section class="card"><div class="cardhead"><div><h2>${t('Revenue & expenses','收入与支出')}</h2><p>${t('Recorded cash movements · partial months marked *','已记录现金流动 · *表示不完整月份')}</p></div></div>${trend()}<div class="legend"><span><i class="dot"></i>${label('revenue')}</span><span><i class="dot navy"></i>${label('expenses')}</span></div></section></div><section class="card"><div class="cardhead"><div><h2>${t('Money waiting to come in','等待到账的资金')}</h2><p>${t(`${money(s.ar)} receivables · ${money(s.overdue)} overdue`,`${money(s.ar)}应收款 · ${money(s.overdue)}已逾期`)}</p></div><button class="textbtn" data-action="nav" data-page="invoices">${t('All invoices','所有发票')} →</button></div>${invoiceTable(data.invoices.filter(i=>i.kind==='receivable'&&outstanding(i)),true)}</section>`;}
function cashPage(){const base=forecast(data,{days:scenario.days}),f=forecast(data,scenario);return `${pageHead('cash',t('Test a decision before you commit.','做出承诺前，先评估决策。'))}<div class="kpis" id="scenario-kpis">${kpi('cashBalance',summary(data).cash,t('Reconciled ledger','已核对账本'),'cash',true)}${kpi('minimum',f.min.cash,date(f.min.date),'cash')}${kpi('shortfall',f.shortfall,t('Below zero, before reserve','低于零的部分，不含储备'),'financing')}${kpi('need',f.need,t('Includes minimum reserve','包含最低储备'),'financing')}</div><section class="card"><div class="cardhead"><div><h2>${t('Cash-flow scenario studio','现金流情景工作区')}</h2><p>${t('Change an assumption. See the consequence.','更改假设，查看影响。')}</p></div><div class="pills">${[['base',t('Base','基准')],['best',t('Best case','乐观')],['stress',t('Stress','压力')]].map(([id,n])=>`<button data-action="preset" data-preset="${id}">${n}</button>`).join('')}</div></div><div class="controls">${slider('growth',t('New sales growth / decline','新增销售增长 / 下降'),-40,40,'%')}${slider('delay',t('Customer-payment delay','客户付款延迟'),0,30,t(' days','天'))}${slider('expense',t('Operating-cost increase','运营成本增加'),0,40,'%')}${slider('supplierDelay',t('Supplier deferral (requires agreement)','供应商延期（需同意）'),0,30,t(' days','天'))}<div class="field"><label for="hiring">${t('Additional monthly payroll (CNY)','每月新增薪酬（人民币）')}</label><input type="number" id="hiring" min="0" max="1000000" step="100" value="${scenario.hiring/100}"></div><div class="field"><label for="oneOff">${t('One-time cost, tomorrow (CNY)','明日一次性支出（人民币）')}</label><input type="number" id="oneOff" min="0" max="1000000" step="100" value="${scenario.oneOff/100}"></div></div><div class="info">${t('Supplier deferral is a simulation, not an instruction or executed change. Sales adjustments affect new retail sales only; existing invoice amounts stay fixed.','供应商延期是模拟，不代表指令或已执行变更。销售调整仅影响新增零售收入；现有发票金额保持不变。')}</div><div class="legend"><span><i class="dot"></i>${t('Your scenario','您的情景')}</span><span><i class="dot navy"></i>${t('Base forecast','基准预测')}</span><select id="horizon" aria-label="${t('Forecast horizon','预测期间')}">${[30,60,90].map(n=>`<option value="${n}" ${scenario.days===n?'selected':''}>${n}${t(' days','天')}</option>`).join('')}</select></div><div id="scenario-chart">${chart([{name:t('Scenario','情景'),points:f.points,color:'var(--chart-primary)'},{name:t('Base','基准'),points:base.points,color:'var(--chart-secondary)'}],235)}</div><div class="compare" id="scenario-impact"><strong>${t('Impact on the lowest balance:','最低余额变化：')} ${money(f.min.cash-base.min.cash)}</strong><p class="small muted">${f.first?t(`First cash deficit: ${date(f.first.date)}.`,`首次现金赤字：${date(f.first.date)}。`):t('No negative daily balance in this scenario.','该情景没有出现负的日末余额。')} ${t(`Reserve target: ${money(f.reserve)}.`,`储备目标：${money(f.reserve)}。`)}</p></div></section><div class="two"><section class="card"><h2>${t('What goes into this forecast','预测依据')}</h2><ul class="list"><li>${t(`Opening cash ${money(base.points[0].cash)} = opening ledger + posted receipts − posted payments.`,`起始现金${money(base.points[0].cash)} = 期初账本 + 已记录收入 − 已记录支出。`)}</li><li>${t(`Daily new sales: ${money(base.dailySales)}; daily operating costs: ${money(base.dailyOps)}. Average of the last 30 days.`,`每日新增销售：${money(base.dailySales)}；每日运营成本：${money(base.dailyOps)}。采用过去30天平均值。`)}</li><li>${t('Receivables use entered expected dates; bills use due dates. Payroll and rent recur monthly.','应收款使用录入的预计日期；账单使用到期日。工资与租金按月重复。')}</li><li>${t('No probability band, seasonality model, tax forecast or lender approval. Hiring costs begin on day 30.','不包含概率区间、季节模型、税务预测或贷款批准。新增薪酬从第30天开始。')}</li></ul></section><section class="card"><h2>${t('Scheduled cash movements','已安排现金流动')}</h2>${f.events.slice(0,8).map(e=>`<div class="timeline"><span>${date(e.date)}</span><button class="textbtn" data-action="evidence" data-id="${esc(e.id)}">${esc(e.id)}</button><strong style="color:${e.kind==='receivable'?'var(--jade)':'var(--ink)'}">${e.kind==='receivable'?'+':'−'}${money(e.amount)}</strong></div>`).join('')}</section></div>`;}
function slider(id,title,min,max,suffix){return `<div class="field"><label for="${id}">${title}<output id="out-${id}">${scenario[id]}${suffix}</output></label><input id="${id}" type="range" min="${min}" max="${max}" value="${scenario[id]}" data-scenario="${id}"></div>`;}
function pageHead(key,sub,buttons=''){return `<div class="headrow"><div><div class="eyebrow muted">${t('Finora workspace','融财工作区')}</div><h1 data-tour="workspace-${key}" style="margin-top:6px">${label(key)}</h1><p class="subtitle">${sub}</p></div>${buttons}</div>`;}
function invoicesPage(){const s=summary(data),items=data.invoices.filter(i=>i.kind===kindFilter&&(!filter||`${i.id} ${i.party} ${i.partyZh||''}`.toLowerCase().includes(filter.toLowerCase()))&&(statusFilter==='all'||status(i)===statusFilter));return `${pageHead('invoices',t('Keep collections and obligations in view.','清晰掌握回款与付款义务。'),btn(icon('plus')+t('New invoice','新建发票'),'newinvoice','primary'))}<div class="three"><section class="card"><span class="muted small">${label('ar')}</span><div class="metric">${money(s.ar)}</div>${badge(t('Outstanding customer invoices','客户未结发票'))}</section><section class="card"><span class="muted small">${label('overdue')}</span><div class="metric" style="color:var(--amber)">${money(s.overdue)}</div>${badge(t('Follow-up recommended','建议跟进'),'amber')}</section><section class="card"><span class="muted small">${label('ap')}</span><div class="metric">${money(s.ap)}</div>${badge(t('Supplier obligations','供应商付款义务'),'gray')}</section></div><section class="card"><div class="cardhead"><div class="pills"><button class="${kindFilter==='receivable'?'active':''}" data-action="kind" data-kind="receivable">${t('Money owed to you','别人欠你的钱')}</button><button class="${kindFilter==='payable'?'active':''}" data-action="kind" data-kind="payable">${t('Money you owe','你需要支付的钱')}</button></div>${btn(icon('down')+t('Export CSV','导出CSV'),'exportinvoices')}</div><div class="filters"><input id="searchInvoices" placeholder="${t('Search invoice or customer…','搜索发票或客户…')}" value="${esc(filter)}" aria-label="${t('Search invoices','搜索发票')}"><select id="statusFilter">${['all','pending','partial','overdue','paid'].map(k=>`<option value="${k}" ${statusFilter===k?'selected':''}>${t({all:'All statuses',pending:'Pending',partial:'Part paid',overdue:'Overdue',paid:'Recorded paid'}[k],{all:'所有状态',pending:'待结清',partial:'部分结清',overdue:'逾期',paid:'已记录结清'}[k])}</option>`).join('')}</select></div>${invoiceTable(items)}</section><section class="card"><h2>${t('Upcoming obligations','近期付款义务')}</h2>${data.invoices.filter(i=>i.kind==='payable'&&outstanding(i)).sort((a,b)=>a.due.localeCompare(b.due)).map(i=>`<div class="timeline"><span>${date(i.due)}</span><span>${esc(party(i))}<br><small>${esc(i.id)}</small></span><strong>${money(outstanding(i))}</strong></div>`).join('')}</section>`;}
function categories(){const tx=stats().transactions.filter(t=>t.type==='expense');return [...new Set(tx.map(t=>t.category))].map(category=>({category,amount:sum(tx.filter(t=>t.category===category))})).sort((a,b)=>b.amount-a.amount);}
let catLabel=c=>t({sales:'Sales receipts',operations:'Operations',payroll:'Payroll',rent:'Rent',marketing:'Marketing',inventory:'Inventory',settlement:'Invoice settlement',other:'Other'}[c]||c,{sales:'销售回款',operations:'运营成本',payroll:'薪酬',rent:'租金',marketing:'营销',inventory:'库存',settlement:'发票结算',other:'其他'}[c]||c);
function expensesPage(){const s=stats(),p=compare(),cats=categories(),tx=s.transactions.filter(x=>x.type==='expense'&&(expenseCategory==='all'||x.category===expenseCategory)&&(!filter||`${x.id} ${x.party} ${x.description}`.toLowerCase().includes(filter.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)),dup=duplicates(data.transactions.filter(t=>t.type==='expense'));return `${pageHead('expenses',t('Know what changed. Investigate what matters.','了解变化，核查关键支出。'))}<div class="filters">${periodControl()}</div><div class="two"><section class="card"><div class="cardhead"><h2>${t('Spending by category','分类支出')}</h2><strong>${money(s.expenses)}</strong></div>${cats.map(c=>`<div class="barrow"><div class="barlabel"><button class="textbtn" data-action="category" data-category="${esc(c.category)}">${esc(catLabel(c.category))}</button><strong>${money(c.amount)}</strong></div><div class="bar"><i style="width:${c.amount/(s.expenses||1)*100}%"></i></div></div>`).join('')}</section><section class="card"><h2>${t('Period comparison','期间比较')}</h2><div class="metric">${money(s.expenses-p.expenses)}</div>${delta(s.expenses,p.expenses,true)}<div class="info">${t('Cash-basis expense comparison. Payroll and rent are recurring obligations; duplicate-looking records remain included until verified.','采用现金制比较。工资与租金为定期付款；疑似重复记录在核查前仍计入支出。')}</div><h3>${t('Review queue','核查清单')}</h3>${dup.map(g=>`<div class="actionrow"><div class="actionicon">${icon('risk')}</div><div><h3>${t('Possible duplicate','可能重复')} · ${money(g[0].amount)}</h3><p>${esc(g[0].party)} · ${date(g[0].date)}</p><div class="evidence">${g.map(x=>`<button data-action="evidence" data-id="${esc(x.id)}">${esc(x.id)}</button>`).join('')}</div></div></div>`).join('')||`<p class="small muted">${t('No same-date, same-vendor, same-amount matches.','没有同日同供应商同金额匹配。')}</p>`}</section></div><section class="card"><div class="filters"><input id="searchExpenses" value="${esc(filter)}" placeholder="${t('Search records or vendor…','搜索记录或供应商…')}" aria-label="${t('Search expenses','搜索支出')}"><select id="expenseCategory"><option value="all">${t('All categories','全部分类')}</option>${cats.map(c=>`<option value="${esc(c.category)}" ${expenseCategory===c.category?'selected':''}>${esc(catLabel(c.category))}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>${t('Date / record','日期 / 记录')}</th><th>${t('Vendor','供应商')}</th><th>${t('Category','分类')}</th><th class="money">${t('Amount','金额')}</th></tr></thead><tbody>${tx.slice(0,100).map(x=>`<tr><td>${date(x.date)}<br><button class="textbtn" data-action="evidence" data-id="${esc(x.id)}">${esc(x.id)}</button></td><td>${esc(x.party)}</td><td>${esc(catLabel(x.category))}</td><td class="money">${money(x.amount,2)}</td></tr>`).join('')}</tbody></table></div>${!tx.length?`<div class="empty"><h3>${t('No matching expenses.','没有匹配的支出。')}</h3><p>${t('Change the filters, or record an actual payment to track where money went. Planned costs belong in the forecast.','可调整筛选，或记录实际付款以跟踪支出用途。计划成本应在预测中评估。')}</p>${btn(t('Record money spent','记录支出'),'quickexpense','',accountState.user&&accountState.role==='viewer'?'disabled':'')}</div>`:''}<p class="small muted" style="margin-top:12px">${t(`Showing ${Math.min(100,tx.length)} of ${tx.length} records.`,`显示${Math.min(100,tx.length)}条，共${tx.length}条记录。`)}</p></section>`;}
function financingPage(){const f=forecast(data,scenario),l=financing(loanInput.principal,loanInput.apr,loanInput.months,loanInput.fee),withLoan=forecast(data,{...scenario,loan:l.net,repayment:l.schedule.map(x=>x.payment)});return `${pageHead('financing',t('Evaluate the trade-off, not just the headline rate.','评估真实取舍，而非只看名义利率。'))}<div class="banner">${icon('shield')}<div><strong>${t('Illustrative calculator · no lender offers','示例计算器 · 非贷款机构报价')}</strong><br><span class="muted">${t('User-entered assumptions. No approval, eligibility guarantee or bank partnership.','采用用户输入假设。不代表批准、资格保证或银行合作。')}</span></div></div><div class="two"><section class="card funding"><div class="eyebrow muted">${t('Money needed to run the business','经营周转资金需求')}</div><div class="metric">${money(f.need)}</div><p class="small muted">${t(`Lowest projected balance ${money(f.min.cash)} + reserve target ${money(f.reserve)}. Gap = max(0, reserve − lowest cash).`,`最低预计余额${money(f.min.cash)}，目标储备${money(f.reserve)}。缺口 = max(0, 储备 − 最低现金)。`)}</p><div class="info">${t('First consider collecting overdue receivables or agreeing supplier terms. Financing adds a future obligation.','先考虑催收逾期款项或协商供应商付款条件。融资会增加未来付款义务。')}</div>${btn(t('Review cash assumptions','核查现金假设'),'nav','', 'data-page="cash"')}</section><section class="card"><h2>${t('Test your financing terms','测试融资条款')}</h2><div class="controls" style="margin-top:15px">${loanField('principal',t('Principal (CNY)','本金（人民币）'),loanInput.principal/100,1,1000000,100)}${loanField('apr',t('Annual nominal rate (%)','名义年利率（%）'),loanInput.apr,0,100,.1)}${loanField('months',t('Term (months)','期限（月）'),loanInput.months,1,60,1)}${loanField('fee',t('Upfront fee (%)','前期手续费（%）'),loanInput.fee,0,20,.1)}</div><p class="small muted" style="margin-top:14px">${t('Reducing-balance amortization; interest rounded to fen each month. Fee deducted from proceeds. First installment on forecast day 30.','采用余额递减的等额还款；每月利息四舍五入到分。手续费从到账金额扣除。首期还款在预测第30天。')}</p></section></div><div class="three"><section class="card"><span class="small muted">${t('Monthly installment','每月还款')}</span><div class="metric">${money(l.payment,2)}</div><p class="small muted">${t('Final installment adjusted for rounding','末期还款按四舍五入结果调整')}</p></section><section class="card"><span class="small muted">${t('Total installments + fee','还款合计 + 手续费')}</span><div class="metric">${money(l.total+l.fee,2)}</div><p class="small muted">${t(`Financing cost: ${money(l.cost,2)}`,`融资成本：${money(l.cost,2)}`)}</p></section><section class="card"><span class="small muted">${t('Net funds received','净到账资金')}</span><div class="metric">${money(l.net,2)}</div><p class="small muted">${t(`Upfront fee: ${money(l.fee,2)}`,`前期手续费：${money(l.fee,2)}`)}</p></section></div><section class="card"><div class="cardhead"><div><h2>${t('Does borrowing solve the timing problem?','借款能否解决时间错配？')}</h2><p>${t('Scenario assumptions retained · not an application or transaction','保留情景假设 · 非贷款申请或交易')}</p></div>${btn(t('Preview analysis','预览分析'),'financepreview','primary')}</div><div class="legend"><span><i class="dot"></i>${t('With illustrative financing','加入示例融资')}</span><span><i class="dot navy"></i>${t('Without financing','不融资')}</span></div>${chart([{name:t('With financing','融资后'),points:withLoan.points,color:'var(--chart-primary)'},{name:t('Without financing','融资前'),points:f.points,color:'var(--chart-secondary)'}],225)}<div class="chartfoot"><div>${t('Lowest cash, without financing','不融资最低现金')}<strong>${money(f.min.cash)}</strong></div><div>${t('Lowest cash, with financing','融资后最低现金')}<strong>${money(withLoan.min.cash)}</strong></div><div>${t('Remaining reserve gap','剩余储备缺口')}<strong>${money(withLoan.need)}</strong></div></div></section><div class="two"><section class="card"><h2>${t('Readiness checklist','融资准备清单')}</h2><p class="small muted" style="margin:8px 0">${t('Self-assessment only. Requirements vary by lender. No documents are uploaded.','仅供自评。机构要求可能不同。不上传文件。')}</p>${['Business registration','Recent bank statements','Receivables aging report','Tax records','Repayment plan'].map((en,i)=>`<label class="checkbox"><input type="checkbox" data-checklist="${i}" ${data.checklist?.includes(i)?'checked':''}>${t(en,['营业执照','近期银行流水','应收账龄报告','纳税记录','还款计划'][i])}</label>`).join('')}</section><section class="card"><h2>${t('Compare alternatives','比较替代方案')}</h2><ul class="list"><li>${t(`Collections: ${money(summary(data).overdue)} overdue. No interest, but customer payment timing is uncertain.`,`催收：${money(summary(data).overdue)}已逾期。无利息，但客户回款时间不确定。`)}</li><li>${t('Supplier deferral: moves cash outflows later. Requires explicit agreement and may affect terms.','供应商延期：推迟支出。需要明确同意，可能影响付款条件。')}</li><li>${t(`Illustrative borrowing: cost ${money(l.cost,2)} across ${loanInput.months} months. Future installments can create new pressure.`,`示例借款：${loanInput.months}个月成本${money(l.cost,2)}。未来还款可能产生新压力。`)}</li></ul></section></div>`;}
function loanField(id,title,value,min,max,step){return `<div class="field"><label for="loan-${id}">${title}</label><input id="loan-${id}" data-loan="${id}" type="number" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function riskPage(){const items=risks(data);return `${pageHead('risk',t('Evidence first. Review before acting.','以证据为先，核查后再行动。'))}<div class="info">${t('Alerts are rule-based indicators, not fraud findings or credit decisions. Marking reviewed does not resolve the underlying financial risk.','提醒为规则指标，不是欺诈结论或信贷决策。标记已核查不代表财务风险已经消除。')}</div>${items.map(r=>`<section class="card risk ${r.severity}"><div class="cardhead"><h2>${t(...riskText[r.id])}</h2>${badge(t({critical:'Critical',high:'High',medium:'Medium',low:'Low'}[r.severity],{critical:'紧急',high:'高',medium:'中',low:'低'}[r.severity]),r.severity==='critical'?'red':'amber')}</div><p>${riskDescription(r)}</p><p class="small muted" style="margin-top:10px">${t('Evidence','证据')} · ${date(r.date)}</p><div class="evidence">${r.evidence.map(id=>`<button data-action="evidence" data-id="${esc(id)}">${esc(id)}</button>`).join('')}</div><div class="riskfooter">${btn(t('Investigate','查看详情')+' →','nav','',`data-page="${r.route}"`)}${btn(icon('check')+t(data.reviewed.includes(r.id)?'Reopen review':'Mark reviewed',data.reviewed.includes(r.id)?'重新核查':'标记已核查'),'review','',`data-id="${r.id}"`)}${data.reviewed.includes(r.id)?badge(t('Reviewed, risk retained','已核查，保留风险'),'gray'):''}</div></section>`).join('')||`<section class="card empty">${icon('shield')}<h2>${t('No current rule-based alerts','当前没有规则提醒')}</h2><p>${t('This does not establish that the business has no risk.','这不代表企业没有风险。')}</p></section>`}`;}
function reportsPage(){const s=stats(),p=compare(),f=forecast(data);return `${pageHead('reports',t('A transparent record of how the numbers were calculated.','透明呈现每项数字的计算依据。'),btn(icon('down')+t('Export report','导出报告'),'report'))}<div class="filters">${periodControl()}</div><section class="card"><h2>${t('Cash-basis management report','现金制管理报告')}</h2><p class="small muted" style="margin:8px 0">${esc(businessName())} · ${date(s.start)} — ${date(s.end)}</p><table><thead><tr><th>${t('Metric','指标')}</th><th class="money">${t('Selected period','选定期间')}</th><th class="money">${label('previous')}</th></tr></thead><tbody>${[['revenue',s.revenue,p.revenue],['expenses',s.expenses,p.expenses],['profit',s.profit,p.profit]].map(([k,a,b])=>`<tr><td>${label(k)}</td><td class="money">${money(a,2)}</td><td class="money">${money(b,2)}</td></tr>`).join('')}</tbody></table><div class="info">${t('Net cash result is not accrual profit. Unpaid invoices are not booked as revenue or expenses here. Tax is included in cash movements, with no separate tax liability model.','净现金收益不是权责发生制利润。未结发票不在此计入收入或支出。税费包含在现金流动中，不单独建立税务负债模型。')}</div></section><div class="two"><section class="card"><h2>${t('Ledger reconciliation','账本核对')}</h2><table><tbody>${[[t('Opening balance','期初余额'),data.opening],[t('Posted receipts','已记录收入'),sum(data.transactions.filter(x=>!x.voidedAt&&x.type==='income'))],[t('Posted payments','已记录支出'),-sum(data.transactions.filter(x=>!x.voidedAt&&x.type==='expense'))],[t('Closing cash','期末现金'),s.cash]].map(([n,a])=>`<tr><td>${n}</td><td class="money">${money(a,2)}</td></tr>`).join('')}</tbody></table><p class="small muted" style="margin-top:12px">${t(`Opening ledger date: ${data.openingDate}. Transfers excluded from consolidated cash.`,`期初账本日期：${data.openingDate}。内部转账不计入合并现金。`)}</p></section><section class="card"><h2>${t('Receivables aging','应收账龄')}</h2>${[[t('Not overdue','未逾期'),i=>i.due>=AS_OF],[t('1–30 days overdue','逾期1–30天'),i=>daysBetween(i.due,AS_OF)>0&&daysBetween(i.due,AS_OF)<=30],[t('31–60 days overdue','逾期31–60天'),i=>daysBetween(i.due,AS_OF)>30&&daysBetween(i.due,AS_OF)<=60],[t('Over 60 days','逾期超过60天'),i=>daysBetween(i.due,AS_OF)>60]].map(([n,pred])=>`<div class="barlabel" style="padding:10px 0;border-bottom:1px solid var(--line)"><span>${n}</span><strong>${money(sum(data.invoices.filter(i=>i.kind==='receivable'&&pred(i)).map(i=>({amount:outstanding(i)}))))}</strong></div>`).join('')}</section></div><section class="card"><h2>${t('Model boundaries','模型边界')}</h2><ul class="list"><li>${t('Runway is not estimated when historical net cash flow is positive. Future scheduled obligations can still create a cash deficit.','历史净现金流为正时不估算现金可支撑天数。未来付款义务仍可能导致现金短缺。')}</li><li>${t('No cost-of-goods-sold classification, so gross profit is unavailable. No refund, tax filing or currency conversion engine.','没有销售成本分类，因此无法计算毛利。不包含退款、纳税申报或汇率转换引擎。')}</li><li>${t('Payment-delay statistics require completed invoice payment histories; the initial sample is insufficient.','回款延迟统计需要完整发票结算历史；初始样本不足。')}</li><li>${t('This demo stores records in this browser. Public hosting does not provide account storage or device sync.','演示将记录存储在当前浏览器。公开托管不提供账号存储或设备同步。')}</li></ul></section>`;}
function settingsPage(){return `<section class="card appearance-card"><h2>${t('Appearance','外观')}</h2><div class="field"><label for="appearance">${t('Color theme','颜色主题')}</label><select id="appearance">${[['system',t('System','跟随系统')],['light',t('Light','浅色')],['dark',t('Dark','深色')]].map(([v,n])=>`<option value="${v}" ${appearance.preference===v?'selected':''}>${n}</option>`).join('')}</select></div><p class="small muted">${t('Saved on this device. System follows your operating system and updates automatically.','保存在此设备上。“跟随系统”会自动响应操作系统的主题变化。')}</p></section><section class="card">${btn(t('Help · Demo chapters & welcome','帮助 · 演示章节与欢迎画面'),'starttour')}</section>${pageHead('settings',t('A safe place to practice with synthetic business data.','使用模拟企业数据安全演练。'))}<section class="card"><div class="cardhead"><h2>${t('Business & forecast settings','企业与预测设置')}</h2>${badge(t('Browser-local demo','浏览器本地演示'),'gray')}</div><form id="settingsform"><div class="controls"><div class="field"><label for="bizname">${t('Display name','显示名称')}</label><input id="bizname" name="name" required maxlength="80" value="${esc(data.settings.name)}"></div><div class="field"><label for="reserve">${t('Emergency cash buffer (CNY)','应急现金备用金（人民币）')}</label><input id="reserve" name="reserve" type="number" min="0" max="1000000" step=".01" value="${data.settings.reserve/100}" required></div><div class="field"><label>${t('Reporting currency','报告币种')}</label><input value="CNY · ${t('Chinese yuan','人民币')}" readonly></div><div class="field"><label>${t('Reporting date','报告日期')}</label><input value="${AS_OF} · ${t('fixed demo snapshot','固定演示快照')}" readonly></div></div><footer style="margin-top:18px">${btn(t('Save settings','保存设置'),'savesettings','primary','type="submit"')}</footer></form></section><section class="card"><div class="cardhead"><div><h2>${t('Import transactions','导入交易记录')}</h2><p>${t('CSV · up to 1 MB · preview before commit','CSV · 最大1MB · 保存前预览')}</p></div>${btn(t('CSV template','CSV模板'),'template')}</div><p class="small muted">${t('Required columns: id, date, type, category, party, amount. Amounts are positive CNY; type is income or expense. Dates must follow the opening ledger and not exceed the demo date.','必需字段：id、date、type、category、party、amount。金额为正数人民币；type为income或expense。日期必须晚于期初账本且不超过演示日期。')}</p><input id="csvfile" type="file" accept=".csv,text/csv" style="margin-top:15px" aria-label="${t('Choose CSV file','选择CSV文件')}">${importPreview?`<div class="info">${t(`${importPreview.records.length} valid rows · ${importPreview.errors.length} invalid rows · ${importPreview.duplicateCount} duplicate IDs skipped.`,`${importPreview.records.length}条有效记录 · ${importPreview.errors.length}条无效记录 · 跳过${importPreview.duplicateCount}个重复ID。`)}</div>${importPreview.errors.length?`<div class="error">${t('Fix these CSV line numbers and upload again:','请修正以下CSV行并重新上传：')} ${importPreview.errors.join(', ')}</div>`:''}<div class="tablewrap"><table><thead><tr><th>ID</th><th>${t('Date','日期')}</th><th>${t('Counterparty','交易方')}</th><th class="money">${t('Amount','金额')}</th></tr></thead><tbody>${importPreview.records.slice(0,10).map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.date)}</td><td>${esc(x.party)}</td><td class="money">${money(x.amount,2)}</td></tr>`).join('')}</tbody></table></div>${btn(t('Review and import','核对并导入'),'commitimport','primary',importPreview.errors.length||!importPreview.records.length?'disabled':'')}`:''}</section><div class="two"><section class="card"><h2>${t('Control & privacy','控制与隐私')}</h2><ul class="list"><li>${t('Read-only analytics: available to the copilot.','只读分析：可供助手使用。')}</li><li>${t('Drafts: preview locally, then approve saving. No messages sent.','草稿：先本地预览，再确认保存。不发送消息。')}</li><li>${t('Financial record changes: explicit confirmation and audit log.','财务记录变更：明确确认并记录审计日志。')}</li><li>${t('Real payments and loan applications: unavailable.','真实付款与贷款申请：不可用。')}</li><li>${t('No bank passwords or identity documents collected. Analytics requests go to this Site server. With your consent, live AI receives your question, reviewed assumptions and calculated results, not the raw ledger.','不收集银行密码或身份证件。分析请求发送至本站服务器。经您同意，实时AI接收问题、已核对假设与计算结果，不接收原始账本。')}</li></ul>${btn(t('Export backup','导出备份'),'backup')} ${btn(t('Reset this business','重置当前企业'),'reset','danger')}</section><section class="card"><h2>${t('Local audit trail','本地审计记录')}</h2><p class="small muted" style="margin:8px 0">${t('Recorded locally; not tamper-proof. Latest 200 entries retained.','本地记录；不具备防篡改能力。保留最近200条。')}</p>${data.audit.slice(0,8).map(a=>`<div class="audit"><strong>${auditLabel(a.action)}</strong><br><span class="muted">${esc(a.record)} · ${esc(new Date(a.date).toLocaleString(lang==='zh'?'zh-CN':'en-US'))}</span></div>`).join('')||`<p class="small muted">${t('No changes yet.','尚无变更。')}</p>`}</section></div>`;}
function auditLabel(k){return t({invoice_created:'Invoice created',invoice_updated:'Invoice updated',payment_recorded:'Payment recorded in demo',review:'Alert review changed',import:'Transactions imported',quick_entry:'Money entry saved',quick_undo:'Money entry reversed',settings:'Settings changed',draft:'Draft saved locally',financing:'Financing analysis saved'}[k]||k,{invoice_created:'发票已创建',invoice_updated:'发票已更新',payment_recorded:'演示已记录付款',review:'提醒核查状态已变更',import:'交易记录已导入',quick_entry:'收支记录已保存',quick_undo:'收支记录已撤销',settings:'设置已更改',draft:'草稿已本地保存',financing:'融资分析已保存'}[k]||k);}
const questions=()=>[t('Will I have enough cash in the next 30 days?','未来30天，我的现金是否足够？'),t('Which invoices should I follow up on?','我应该优先跟进哪些发票？'),t('What if my revenue drops by 15%?','如果收入下降15%会怎样？'),t('How much working capital do I need?','我需要多少营运资金？'),t('How do I use Finora?','如何使用融财？')];

function copilotPanel(){return `<aside class="copilot"><div class="copilothead" data-tour="assistant"><div class="spark">${icon('copilot')}</div><div><h2>${t('Your finance copilot','您的财务助手')}</h2><div class="statusline"><span class="online"></span><span data-ai-connection>${assistantConnectionText()}</span></div></div><button class="iconbtn mobilecopilot" data-action="closecopilot" aria-label="${t('Close copilot','关闭助手')}" style="margin-left:auto">${icon('close')}</button></div><div class="copilotbody"><div class="context">${icon('shield')}<span>${t('Context','当前企业')}<br><strong style="color:var(--ink)">${esc(businessName())}</strong><br>${t('Synthetic records · 13 Oct 2026','模拟记录 · 2026年10月13日')}</span></div>${!data.chats.length?`<div class="spark">${icon('copilot')}</div><div class="hello">${t('Let’s make your next move a confident one.','让您的下一步更有把握。')}</div><p class="intro">${t('Ask a business question. I’ll show the numbers, the evidence, and what could change.','提出经营问题。我会呈现数字、证据，以及可能变化的因素。')}</p><div class="chips">${questions().map((q,i)=>`<button data-action="question" data-index="${i}">${q}<span>↗</span></button>`).join('')}</div><div style="margin-top:28px;border-top:1px solid var(--line);padding-top:17px"><span class="eyebrow muted">${t('A useful place to start','建议从这里开始')}</span><p class="intro" style="margin-top:9px">${t('A large supplier bill is due soon. Let’s check whether your cash can cover it.','一笔较大的供应商账单即将到期。我们一起检查现金是否足够。')}</p>${btn(t('Check my cash position','检查现金状况'),'askcash','primary')}</div>`:data.chats.map(c=>`<div class="message user">${esc(c.question)}</div><div class="message">${answerHTML({...businessAnalysis(data,c.question,lang,c.context||'',c.reportPeriod||null,c.scenario||null,c.aiTopic||'auto'),proposedScenario:c.aiStamp===financialStamp()?c.proposedScenario:conversationContext(c.question,data.chats.slice(0,data.chats.indexOf(c))).proposed,aiFailure:c.aiFailure,aiExplanation:c.aiVersion===2&&c.aiLang===lang&&c.aiStamp===financialStamp()?c.aiExplanation:undefined,live:c.aiVersion===2&&c.aiLang===lang&&c.aiStamp===financialStamp()?c.live:false})}</div>`).join('')}${pending?`<p class="small muted" role="status">${t('Retrieving records and calculating…','正在检索记录并计算…')}</p>`:''}</div><div class="copilotinput"><section class="ai-activation" aria-label="${t('Gemini activation','Gemini启用设置')}">${assistantLiveControls()}</section><form id="chatform"><div class="inputwrap"><textarea id="chatinput" maxlength="2000" rows="2" placeholder="${t('Ask about your business finances…','询问企业财务状况…')}" aria-label="${t('Ask the copilot','询问助手')}"></textarea><button class="send" type="submit" ${pending?'disabled':''} aria-label="${t('Send question','发送问题')}">${icon('arrow')}</button></div></form><div class="note">${t('Evidence-backed. You stay in control.','以证据为依据，决策由您掌控。')}</div></div></aside>`;}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';if(!labels[page])page='overview';const activeRisks=risks(data).filter(r=>!data.reviewed.includes(r.id)).length;const pages={pdfreceipts:pdfReceiptPage,rescue:rescuePage,receipts:receiptsPage,actionplan:actionPlanPage,quality:qualityPage,reconcile:reconcilePage,ai:aiSetupPage,imports:importPage,collections:collectionsPage,fapiao:fapiaoPage,weekly:weeklyPage,setup:setupPage,account:accountPage,options:optionsPage,transactions:transactionsPage,overview:dashboard,cash:cashPage,invoices:invoicesPage,expenses:expensesPage,financing:financingPage,risk:riskPage,reports:reportsPage,settings:settingsPage,copilot:()=>`${pageHead('copilot',t('Ask, inspect, evaluate. Every answer starts with your records.','提问、核查、评估。每个回答均从企业记录出发。'))}<section class="card"><h2>${t('Choose a decision to explore','选择要探索的决策')}</h2><div class="chips" style="margin-top:20px">${questions().map((q,i)=>`<button data-action="question" data-index="${i}">${q} →</button>`).join('')}</div><div class="info">${t('The persistent copilot uses the selected business only. Questions and history are separated for each business. Supported topics: cash, receivables, expenses, financing and hiring.','常驻助手仅使用当前企业的数据。每个演示企业的问题与本地历史独立存储。支持现金、应收款、支出、融资与招聘话题。')}</div>${btn(t('Open conversation','打开对话'),'opencopilot','primary')} ${btn(t('Clear conversation','清空对话'),'clearchat')}</section>`};const p=profile();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M4 22L14 6h12L16 22H4z" fill="var(--brand-orange)"/><path d="M9 27L19 11h9L18 27H9z" fill="var(--hero-muted)" fill-opacity=".8"/></svg>Finora <span>融财</span></div><div class="navlabel">${t('WORKSPACE','工作区')}</div><nav class="nav">${['overview','transactions','cash','invoices','expenses','options','financing','risk','reports','copilot'].map(k=>`<button data-action="nav" data-page="${k}" class="${page===k?'active':''}">${icon(k)}${label(k)}${k==='risk'&&activeRisks?`<span class="count">${activeRisks}</span>`:''}</button>`).join('')}</nav><div class="sidebarbottom"><div class="sidecard">${icon('shield')}<strong style="display:block;margin:7px 0;font-size:12px">${t('Your decisions. Your control.','您的决策，您来掌控。')}</strong><p style="font-size:10px;color:var(--hero-muted)">${t('AI explains. You approve. Every action leaves a trace.','AI负责解释，您负责确认。每项行动都有记录。')}</p></div><nav class="nav"><button data-action="nav" data-page="settings" class="${page==='settings'?'active':''}">${icon('settings')}${t('Settings & data','设置与数据')}</button></nav><div class="profile"><div class="avatar">LW</div><div><strong style="font-size:11px;color:var(--on-accent)">${t('Li Wei','李伟')}</strong><p style="font-size:10px;color:var(--hero-muted)">${t('Demo owner','演示企业主')}</p></div></div></div></aside><div class="workspace"><header class="topbar"><button class="iconbtn mobilemenu" data-action="menu" aria-label="${t('Open navigation','打开导航')}">${icon('menu')}</button><select class="business" id="business" aria-label="${t('Select demo business','选择演示企业')}">${profiles.map(p=>`<option value="${p.id}" ${p.id===org?'selected':''}>${esc(p.id===org?businessName():p[lang==='zh'?'zh':'en'])}</option>`).join('')}</select><div class="topright">${badge(t('Synthetic demo','模拟演示'),'gray')}<div class="lang" data-tour="language"><button data-action="language" data-lang="en" class="${lang==='en'?'active':''}">EN</button><button data-action="language" data-lang="zh" class="${lang==='zh'?'active':''}">中文</button></div><button class="iconbtn" data-action="nav" data-page="risk" aria-label="${t('Risk notifications','风险通知')}">${icon('bell')}</button><button class="guide-help-button" type="button" data-action="starttour" aria-label="${t('Help and guided demos','帮助与功能演示')}">${t('Demo','演示')}</button><button class="iconbtn mobilecopilot" data-action="opencopilot" aria-label="${t('Open AI copilot','打开AI助手')}">${icon('copilot')}</button></div></header><main class="content">${pages[page]()}<footer class="footer"><span>Finora 融财 · ${t('Smarter cash flow. Stronger businesses.','智慧管现金流，助力企业成长。')}</span><span>${t('Demo snapshot: 13 Oct 2026 · CNY','演示快照：2026年10月13日 · 人民币')}</span></footer></main></div>${copilotPanel()}${mobileNav()}</div>`;if(page==='copilot'&&innerWidth<1000)$('.copilot').classList.add('open');}
function modal(title,body,footer=''){const root=$('#modalroot');root.innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="cardhead"><h2>${title}</h2><button class="iconbtn" data-action="closemodal" aria-label="${t('Close','关闭')}">${icon('close')}</button></div>${body}<footer>${footer||btn(t('Close','关闭'),'closemodal')}</footer></section></div>`;setTimeout(()=>$('.modal button,.modal input')?.focus(),0);}
let confirmCallback=null;function confirm(title,body,fn){confirmCallback=fn;modal(title,body,btn(t('Cancel','取消'),'closemodal')+btn(t('Confirm locally','本地确认'),'confirm','primary'));}
function closeModal({discardMore=false}={}){const root=$('#modalroot'),origin=moreOrigin,saved=moreSuspended,isMore=!!root.querySelector?.('.more-dialog');moreOrigin=null;moreSuspended=null;root.innerHTML='';confirmCallback=null;if(isMore&&saved&&!discardMore&&saved.context===pdfContext()){root.replaceChildren?.(...saved.nodes);confirmCallback=saved.stamp===financialStamp()?saved.confirm:null;if(saved.confirm&&!confirmCallback)toast(t('Records changed. Review the action again before confirming.','记录已变更，请重新核查后再确认。'));}if(origin?.isConnected)origin.focus({preventScroll:true});}
function evidence(id){const i=data.invoices.find(i=>i.id===id&&i.org===org);if(i){invoiceDetail(i);return;}const tx=data.transactions.find(x=>x.id===id&&x.org===org);if(tx){modal(t('Source transaction','来源交易'),`<p class="small muted">${t('Synthetic record','模拟记录')}</p><table><tbody>${[[t('Record ID','记录ID'),tx.id],[t('Date','日期'),tx.date],[t('Counterparty','交易方'),tx.party],[t('Category','分类'),catLabel(tx.category)],[t('Amount','金额'),money(tx.amount,2)],[t('Description','说明'),tx.description||'—']].map(([k,v])=>`<tr><td>${k}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table>`);return;}const r=data.recurring.find(r=>r.id===id);if(r){modal(t('Recurring forecast assumption','定期预测假设'),`<p>${esc(catLabel(r.category))} · ${money(r.amount)}</p><div class="info">${t(`Scheduled on day ${r.day} of every month. Based on the synthetic monthly obligation; this is a forecast assumption, not a posted transaction.`,`安排在每月${r.day}日。根据模拟每月付款义务；这是预测假设，不是已记录交易。`)}</div>`);return;}modal(t('Scenario assumption','情景假设'),`<p>${t('User-entered hiring costs or repayment terms. No external transaction has been executed.','用户输入的招聘成本或还款条款。未执行外部交易。')}</p>`);}
function invoiceDetail(i){const linked=data.transactions.filter(x=>x.invoiceId===i.id&&!x.voidedAt);modal(`${esc(i.id)} · ${esc(party(i))}`,`${statusBadge(i)}<table style="margin-top:15px"><tbody>${[[t('Issue date','开具日期'),i.issued],[t('Due date','到期日'),i.due],[t('Expected collection','预计结算'),i.expected],[t('Subtotal','税前金额'),money(i.subtotal,2)],[t('Tax rate','税率'),i.taxRate+'%'],[t('Total incl. tax','含税总额'),money(i.total,2)],[t('Recorded paid','已记录结清'),money(i.paid,2)],[t('Outstanding','未结金额'),money(outstanding(i),2)]].map(([k,v])=>`<tr><td>${k}</td><td class="money">${esc(v)}</td></tr>`).join('')}</tbody></table>${linked.length?`<p class="small muted" style="margin-top:15px">${t('Linked cash records','关联现金记录')}</p><div class="evidence">${linked.map(x=>`<button data-action="evidence" data-id="${esc(x.id)}">${esc(x.id)}</button>`).join('')}</div>`:''}<div class="info">${t('Recorded settlements change the synthetic ledger. They do not send or verify real money.','记录结算仅更改模拟账本，不发送或验证真实资金。')}</div>`,btn(t('Edit','编辑'),'editinvoice','',`data-id="${esc(i.id)}"`)+(outstanding(i)?btn(t('Record settlement','记录结算'),'settlement','primary',`data-id="${esc(i.id)}"`):'')+(i.kind==='receivable'&&outstanding(i)?btn(t('Draft reminder','起草提醒'),'reminder','',`data-id="${esc(i.id)}"`):''));}
let editing=null;function invoiceForm(i=null){editing=i?.id||null;modal(t(i?'Edit invoice':'New invoice',i?'编辑发票':'新建发票'),`<form id="invoiceform"><div class="controls"><div class="field"><label for="iid">${t('Invoice number','发票编号')}</label><input id="iid" name="id" required maxlength="40" pattern="[A-Za-z0-9_-]+" value="${esc(i?.id||'INV-'+Date.now().toString().slice(-6))}" ${i?'readonly':''}></div><div class="field"><label for="ikind">${t('Type','类型')}</label><select id="ikind" name="kind" ${i?.paid?'disabled':''}><option value="receivable" ${i?.kind==='receivable'?'selected':''}>${t('Money owed to you','别人欠你的钱')}</option><option value="payable" ${i?.kind==='payable'?'selected':''}>${t('Money you owe','你需要支付的钱')}</option></select></div><div class="field"><label for="iparty">${t('Customer / supplier','客户 / 供应商')}</label><input id="iparty" name="party" required maxlength="100" value="${esc(i?.party||'')}"></div><div class="field"><label for="izh">${t('Chinese name (optional)','中文名称（可选）')}</label><input id="izh" name="partyZh" maxlength="100" value="${esc(i?.partyZh||'')}"></div><div class="field"><label for="issued">${t('Issue date','开具日期')}</label><input id="issued" name="issued" type="date" required max="${AS_OF}" value="${i?.issued||AS_OF}"></div><div class="field"><label for="due">${t('Due date','到期日')}</label><input id="due" name="due" type="date" required value="${i?.due||addDays(AS_OF,30)}"></div><div class="field"><label for="expected">${t('Expected settlement date','预计结算日期')}</label><input id="expected" name="expected" type="date" required value="${i?.expected||addDays(AS_OF,30)}"></div><div class="field"><label for="subtotal">${t('Subtotal (CNY)','税前金额（人民币）')}</label><input id="subtotal" name="subtotal" type="number" required min=".01" max="1000000" step=".01" value="${i?i.subtotal/100:''}"></div><div class="field"><label for="taxRate">${t('Tax rate (%)','税率（%）')}</label><input id="taxRate" name="taxRate" type="number" required min="0" max="100" step=".01" value="${i?.taxRate||0}"></div><div class="field"><label>${t('Total incl. tax','含税总额')}</label><strong id="itotal">${money(i?.total||0,2)}</strong></div></div><div id="formerror"></div><div class="info">${t('Tax rate is supplied by you, not tax advice. The invoice is a demo record, not an official Chinese fapiao.','税率由您提供，不构成税务建议。此发票为演示记录，不是中国正式税务发票。')}</div><footer>${btn(t('Cancel','取消'),'closemodal','', 'type="button"')}<button class="btn primary" type="submit">${t('Review changes','核对变更')}</button></footer></form>`,' ');}
async function ask(question){if(pending||!question.trim())return;pending=true;const requestOrg=org,requestLive=liveRequested;const requestStamp=financialStamp(),requestLang=lang,previous=data.chats.at(-1),context=previous?.aiTopic|| (previous?analyze(data,previous.question,lang).kind:'');const reviewed=useReviewedScenario?{...scenario}:null;data.chats.push({question:question.trim().slice(0,2000),context,reportPeriod:{start:stats().start,end:stats().end},scenario:reviewed});data.chats=data.chats.slice(-20);save();render();$('.copilot').classList.add('open');const body=$('.copilotbody');body.scrollTop=body.scrollHeight;
 try{if(location.protocol==='file:'||globalThis.FINORA_OFFLINE)return;const res=await fetch('/api/analyze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({data:{...data,chats:[],documents:[],audit:[],collectionNotes:{}},question,lang:requestLang,context,history:data.chats.slice(0,-1).slice(-4).map(c=>({question:c.question,scenario:c.scenario||null})),scenario:reviewed,live:requestLive,consent:requestLive,reportPeriod:{start:stats().start,end:stats().end}})});if(!res.ok)throw Error('service');const result=await res.json();if(org!==requestOrg||requestStamp!==financialStamp())return;providerMode=result.mode==='live'?'live':'demo';if(result.liveBlocked==='sign_in_required'){aiStatus.authenticated=false;liveRequested=false;}if(result.liveBlocked||result.providerUnavailable)toast(result.providerReason==='provider_busy'?t('Gemini is busy. Showing verified calculations; please try again later.','Gemini繁忙。显示已核算结果，请稍后重试。'):result.providerReason==='provider_quota'?t('Provider quota reached. Showing verified calculations.','服务额度已用完。显示已核算结果。'):t('Live AI unavailable. Showing verified engine results; check AI setup.','实时AI不可用。显示已核算结果，请查看AI设置。'));const latest=data.chats.at(-1);latest.aiFailure=result.liveBlocked||result.providerReason||null;latest.aiTopic=result.trace?.tool==='simulate_cash_flow'?'cash':result.trace?.tool||'auto';if(result.kind==='help'||result.kind==='clarify')latest.scenario=null;if(result.aiExplanation){latest.aiVersion=2;latest.aiFailure=null;latest.proposedScenario=result.proposedScenario;latest.aiExplanation=result.aiExplanation;latest.live=true;latest.aiLang=requestLang;latest.aiStamp=requestStamp;save();}}
 catch{if(requestLive&&org===requestOrg&&requestStamp===financialStamp()){const latest=data.chats.at(-1);if(latest&&latest.question===question.trim().slice(0,2000))latest.aiFailure='provider_error';}toast(t('Server unavailable. Using the same verified local demo engine.','服务器不可用，使用相同的已验证本地演示引擎。'));}finally{pending=false;render();$('.copilot').classList.add('open');$('.copilotbody').scrollTop=$('.copilotbody').scrollHeight;}}
function download(filename,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csvCell=x=>{const s=String(x??'');return '"'+(/^[=+\-@\t\r]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"';};
function report(){const s=stats(),f=forecast(data);download('Finora-report-'+org+'.txt',`${profile()[lang==='zh'?'zh':'en']} · ${t('Synthetic demonstration report','模拟演示报告')}\n${s.start} — ${s.end}\n\n${[['revenue',s.revenue],['expenses',s.expenses],['profit',s.profit],['cashBalance',s.cash],['ar',s.ar],['ap',s.ap],['minimum',f.min.cash],['need',f.need]].map(([k,v])=>label(k)+': '+money(v,2)).join('\n')}\n\n${t('Cash-basis metrics. Unpaid invoices excluded from income and expenses. Forecast: last 30-day averages plus scheduled invoices, rent and payroll. Expected collections are uncertain. Financing is illustrative. This is not an audited statement.','采用现金制指标。未结发票不计入收入与支出。预测：最近30天平均值加已安排发票、租金及工资。预计回款具有不确定性。融资为示例。这不是经审计的报表。')}`);toast(t('Report exported.','报告已导出。'));}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='nav'){go(el.dataset.page);return;}if(a==='language'){lang=el.dataset.lang;localStorage.setItem('finora-lang',lang);closeModal();render();return;}if(a==='menu'){$('.sidebar').classList.toggle('open');return;}if(a==='opencopilot'){$('.copilot').classList.add('open');return;}if(a==='closecopilot'){$('.copilot').classList.remove('open');return;}if(a==='closemodal'){closeModal();return;}if(a==='confirm'){const fn=confirmCallback;closeModal();fn?.();return;}if(a==='question'){ask(questions()[+el.dataset.index]);return;}if(a==='askcash'){ask(questions()[0]);return;}if(a==='horizon'){scenario.days=+el.dataset.days;render();return;}if(a==='preset'){scenario={days:scenario.days,growth:el.dataset.preset==='base'?0:el.dataset.preset==='best'?15:el.dataset.preset==='stress'?-15:0,delay:el.dataset.preset==='stress'?7:0,expense:el.dataset.preset==='stress'?10:0,hiring:0,supplierDelay:0,oneOff:0};render();return;}if(a==='kind'){kindFilter=el.dataset.kind;render();return;}if(a==='category'){expenseCategory=el.dataset.category;render();return;}if(a==='invoice'){invoiceDetail(data.invoices.find(i=>i.id===id));return;}if(a==='evidence'){evidence(id);return;}if(a==='newinvoice'){invoiceForm();return;}if(a==='editinvoice'){invoiceForm(data.invoices.find(i=>i.id===id));return;}
 if(a==='settlement'){const i=data.invoices.find(i=>i.id===id);modal(t('Record a demo settlement','记录演示结算'),`<form id="settlementform" data-id="${esc(id)}"><p class="small muted">${esc(id)} · ${t('Outstanding','未结金额')} ${money(outstanding(i),2)}</p><div class="field" style="margin-top:15px"><label for="settleamount">${t('Amount received / paid (CNY)','已收到 / 已付金额（人民币）')}</label><input id="settleamount" name="amount" type="number" step=".01" min=".01" max="${outstanding(i)/100}" required value="${outstanding(i)/100}"></div><div class="info">${t('This records a synthetic cash movement dated 13 Oct 2026. It does not initiate or confirm a real payment.','此操作记录一笔日期为2026年10月13日的模拟现金流动，不发起或确认真实付款。')}</div><button type="submit" class="btn primary">${t('Preview settlement','预览结算')}</button></form>`,' ');return;}
 if(a==='reminder'){const i=data.invoices.find(i=>i.id===id),text=t(`Hello ${party(i)},\n\nOur records show ${money(outstanding(i),2)} outstanding on invoice ${i.id}, due ${i.due}. Could you confirm your expected payment date? Please let us know if anything needs clarification.\n\nThank you.`,`您好，${party(i)}：\n\n根据我们的记录，发票${i.id}仍有${money(outstanding(i),2)}未结清，到期日为${i.due}。请问预计何时付款？如有疑问，请随时告知。\n\n谢谢。`);confirm(t('Preview reminder draft','预览催款草稿'),`<pre>${esc(text)}</pre><p class="small muted">${t('Save as a local draft only. No email or message will be sent.','仅保存本地草稿。不发送邮件或消息。')}</p>`,()=>{data.drafts=[...(data.drafts||[]),{id,text,date:new Date().toISOString()}];log('draft',id);save();download(id+'-reminder.txt',text);toast(t('Draft saved and downloaded. Nothing sent.','草稿已保存并下载。未发送消息。'));render();});return;}
 if(a==='review'){const r=risks(data).find(r=>r.id===id);confirm(t('Confirm review state','确认核查状态'),`<p>${t(...riskText[id])}</p><div class="info">${t('This changes the review marker only. The underlying record and forecast remain intact.','仅更改核查标记。原始记录与预测仍保留。')}</div>`,()=>{data.reviewed=data.reviewed.includes(id)?data.reviewed.filter(x=>x!==id):[...data.reviewed,id];log('review',id);save();render();toast(t('Review state updated.','核查状态已更新。'));});return;}
 if(a==='report'){report();return;}if(a==='exportinvoices'){download('Finora-invoices-'+org+'.csv','\uFEFF'+[['id','kind','party','issued','due','expected','total_CNY','paid_CNY','outstanding_CNY','status'],...data.invoices.map(i=>[i.id,i.kind,party(i),i.issued,i.due,i.expected,(i.total/100).toFixed(2),(i.paid/100).toFixed(2),(outstanding(i)/100).toFixed(2),status(i)])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');return;}if(a==='backup'){download('Finora-backup-'+org+'.json',JSON.stringify(data,null,2),'application/json');return;}if(a==='template'){download('Finora-transactions-template.csv','id,date,type,category,party,amount,description\nIMPORT-001,2026-10-12,expense,other,Sample supplier,125.50,Example record\n','text/csv');return;}
 if(a==='commitimport'){if(!importPreview||importPreview.errors.length)return;const records=importPreview.records;confirm(t('Confirm transaction import','确认导入交易记录'),`<p>${t(`Add ${records.length} records to ${profile().en}? Dashboard balances and forecasts will change.`,`向${profile().zh}添加${records.length}条记录？仪表盘余额与预测将改变。`)}</p><div class="info">${t('Review the source file; financial records cannot be verified against a bank in this demo.','请核对来源文件；此演示无法与银行核实财务记录。')}</div>`,()=>{try{const next={...data,transactions:[...data.transactions,...records]};validateData(next);data=next;log('import',records.map(r=>r.id).join(', ').slice(0,250));importPreview=null;save();render();toast(t('Records imported.','记录已导入。'));}catch{toast(t('Import failed validation. No records changed.','导入未通过验证。未更改记录。'));}});return;}
 if(a==='reset'){confirm(t('Reset this demo business?','重置当前演示企业？'),`<p>${t('This replaces local changes, conversations and drafts with the initial synthetic dataset. Export a backup first if needed.','这将把本地变更、对话与草稿替换为初始模拟数据。如有需要，请先导出备份。')}</p>`,()=>{data=seed(org);save();scenario={days:30,growth:0,delay:0,expense:0,hiring:0,supplierDelay:0,oneOff:0};render();toast(t('Demo restored.','演示已恢复。'));});return;}
 if(a==='clearchat'){data.chats=[];save();render();return;}if(a==='financepreview'){const l=financing(loanInput.principal,loanInput.apr,loanInput.months,loanInput.fee);confirm(t('Review financing analysis','核对融资分析'),`<p>${t(`Net proceeds ${money(l.net,2)}; monthly installment ${money(l.payment,2)}; total cost ${money(l.cost,2)}.`,`净到账${money(l.net,2)}；每月还款${money(l.payment,2)}；总成本${money(l.cost,2)}。`)}</p><div class="info">${t('Save this hypothetical analysis locally. No application is submitted, no lender is contacted, and the ledger is not changed.','本地保存假设分析。不提交申请、不联系贷款机构、不更改账本。')}</div>`,()=>{data.financingAnalysis={...loanInput,...l,date:AS_OF};log('financing','hypothetical');save();render();toast(t('Illustrative analysis saved locally.','示例分析已本地保存。'));});return;}
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='chatform'){const q=$('#chatinput').value;ask(q);return;}
 if(form.id==='invoiceform'){const v=Object.fromEntries(new FormData(form)),existing=data.invoices.find(i=>i.id===editing),subtotal=Math.round(+v.subtotal*100),taxRate=+v.taxRate,total=subtotal+Math.round(subtotal*taxRate/100);const i={id:v.id.trim(),org,kind:existing?.paid?existing.kind:v.kind,party:v.party.trim(),partyZh:v.partyZh.trim(),issued:v.issued,due:v.due,expected:v.expected,subtotal,taxRate,total,paid:existing?.paid||0};try{if(!i.party||i.issued>AS_OF||(!editing&&data.invoices.some(x=>x.id===i.id)))throw Error('invoice');validateData({...data,invoices:[...data.invoices.filter(x=>x.id!==editing),i]});}catch{$('#formerror').innerHTML=`<div class="error">${t('Check dates, unique invoice number and amounts. Total cannot be less than recorded payments.','请检查日期、唯一发票编号与金额。总额不能低于已记录结算金额。')}</div>`;return;}const wasEditing=editing;confirm(t('Confirm invoice changes','确认发票变更'),`<p>${esc(i.id)} · ${esc(party(i))}</p><div class="metric">${money(i.total,2)}</div><p class="small muted">${t('This changes outstanding balances and expected cash timing. No cash movement is recorded until a settlement is entered.','这会改变未结金额与预计现金时间。在录入结算前，不会记录现金流动。')}</p>`,()=>{data.invoices=[...data.invoices.filter(x=>x.id!==wasEditing),i];log(wasEditing?'invoice_updated':'invoice_created',i.id);save();render();toast(t('Invoice saved.','发票已保存。'));});return;}
 if(form.id==='settlementform'){const id=form.dataset.id,i=data.invoices.find(i=>i.id===id),amount=Math.round(+new FormData(form).get('amount')*100);if(!Number.isSafeInteger(amount)||amount<=0||amount>outstanding(i))return;confirm(t('Confirm demo settlement','确认演示结算'),`<p>${esc(id)} · ${money(amount,2)}</p><div class="info">${t('This adds one linked cash transaction and reduces the outstanding invoice balance by the same amount. No real payment is made.','此操作新增一笔关联现金交易，并按相同金额减少未结发票余额。不进行真实付款。')}</div>`,()=>{const tx={id:`${org}-SET-${Date.now()}`,org,date:AS_OF,type:i.kind==='receivable'?'income':'expense',category:'settlement',party:i.party,description:'Demo settlement '+id,invoiceId:id,amount};const next={...data,invoices:data.invoices.map(x=>x.id===id?{...x,paid:x.paid+amount}:x),transactions:[...data.transactions,tx]};try{validateData(next);data=next;log('payment_recorded',id);save();render();toast(t('Demo settlement recorded. No real payment sent.','演示结算已记录。未发送真实付款。'));}catch{toast(t('Validation failed. No changes saved.','验证失败。未保存变更。'));}});return;}
 if(form.id==='settingsform'){const v=Object.fromEntries(new FormData(form)),reserve=Math.round(+v.reserve*100);if(!v.name.trim()||!Number.isSafeInteger(reserve)||reserve<0)return;data.settings={...data.settings,name:v.name.trim(),reserve};log('settings',org);save();render();toast(t('Settings saved.','设置已保存。'));return;}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='subtotal'||el.id==='taxRate'){const s=Math.round(+$('#subtotal').value*100),r=+$('#taxRate').value;$('#itotal').textContent=money(s+Math.round(s*r/100),2);return;}
 if(el.dataset.scenario){scenario[el.dataset.scenario]=+el.value;$('#out-'+el.dataset.scenario).textContent=el.value+(el.dataset.scenario==='growth'||el.dataset.scenario==='expense'?'%':t(' days','天'));updateScenario();return;}
});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='appearance'){appearance.set(el.value);return;}if(el.id==='business'){pdfDraft=null;pdfEpoch++;collectionSearch='';if(accountState.user){switchBusiness(el.value);return;}org=el.value;localStorage.setItem('finora-org',org);data=load();scenario={days:30,growth:0,delay:0,expense:0,hiring:0,supplierDelay:0,oneOff:0};importPreview=null;statementPreview=null;invoiceDraft=null;rescueResult=null;filter='';closeModal();render();return;}
 if(el.id==='period'){period=el.value==='custom'?'custom':+el.value;render();return;}if(el.id==='startdate'||el.id==='enddate'){const start=$('#startdate').value,end=$('#enddate').value;if(!start||!end||start>end||end>AS_OF||start<=data.openingDate){toast(t('Choose valid dates within available records.','请在现有记录范围内选择有效日期。'));render();return;}custom={start,end};render();return;}
 if(el.id==='searchInvoices'||el.id==='searchExpenses'){filter=el.value;render();return;}if(el.id==='statusFilter'){statusFilter=el.value;render();return;}if(el.id==='expenseCategory'){expenseCategory=el.value;render();return;}
 if(el.dataset.scenario||['hiring','oneOff','horizon'].includes(el.id)){if(el.id==='horizon')scenario.days=+el.value;else if(el.id==='hiring'||el.id==='oneOff')scenario[el.id]=Math.round(Math.max(0,Math.min(1000000,+el.value))*100);else scenario[el.dataset.scenario]=+el.value;render();return;}
 if(el.dataset.loan){const key=el.dataset.loan,old=loanInput[key];loanInput[key]=key==='principal'?Math.round(+el.value*100):+el.value;try{financing(loanInput.principal,loanInput.apr,loanInput.months,loanInput.fee);render();}catch{loanInput[key]=old;toast(t('Enter valid financing terms.','请输入有效融资条款。'));render();}return;}
 if(el.dataset.checklist){const i=+el.dataset.checklist;data.checklist=el.checked?[...new Set([...(data.checklist||[]),i])]:(data.checklist||[]).filter(x=>x!==i);save();return;}
 if(el.id==='csvfile'){const file=el.files[0];if(!file)return;try{if(file.size>1000000||!file.name.toLowerCase().endsWith('.csv'))throw Error('file');const importOrg=org,content=await file.text();if(org!==importOrg)return;const parsed=parseCSV(content,org),seen=new Set(data.transactions.map(t=>t.id));let duplicateCount=0;const records=parsed.records.filter(r=>{if(r.date<=data.openingDate){parsed.errors.push(r.sourceLine);return false;}if(seen.has(r.id)){duplicateCount++;return false;}seen.add(r.id);return true;});importPreview={...parsed,records,duplicateCount};render();}catch{toast(t('Invalid CSV. Use the template and keep the file under 1 MB.','无效CSV。请使用模板并确保文件小于1MB。'));}return;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');$('.copilot')?.classList.remove('open');}if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='chatinput'){e.preventDefault();ask(e.target.value);}if(e.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,[tabindex="0"]')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus();}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==page){page=p;render();}});

const initialAccountReady=location.protocol!=='file:'&&!globalThis.FINORA_OFFLINE?fetch('/api/status').then(r=>r.ok?r.json():null).then(async s=>{if(s){aiStatus=s;await loadCloudIdentity();providerMode=s.mode==='configured'?'configured':'demo';if(!pending)render();}}).catch(()=>{}):Promise.resolve();

function updateScenario(){if(page!=='cash')return;const base=forecast(data,{days:scenario.days}),f=forecast(data,scenario);$('#scenario-chart').innerHTML=chart([{name:t('Scenario','情景'),points:f.points,color:'var(--chart-primary)'},{name:t('Base','基准'),points:base.points,color:'var(--chart-secondary)'}],235);$('#scenario-kpis').innerHTML=kpi('cashBalance',summary(data).cash,t('Reconciled ledger','已核对账本'),'cash',true)+kpi('minimum',f.min.cash,date(f.min.date),'cash')+kpi('shortfall',f.shortfall,t('Below zero, before reserve','低于零的部分，不含储备'),'financing')+kpi('need',f.need,t('Includes minimum reserve','包含最低储备'),'financing');$('#scenario-impact').innerHTML='<strong>'+t('Impact on the lowest balance:','最低余额变化：')+' '+money(f.min.cash-base.min.cash)+'</strong><p class="small muted">'+(f.first?t('First cash deficit: '+date(f.first.date)+'.','首次现金赤字：'+date(f.first.date)+'。'):t('No negative daily balance in this scenario.','该情景没有出现负的日末余额。'))+'</p>'; }

const previousKpi=kpi;
kpi=function(name,value,foot,action,dark=false){return `<article class="kpi ${dark?'dark':''}"><button class="kpilink" data-action="nav" data-page="${action}"><span class="label">${label(name)}${icon(action)}</span><strong>${money(value)}</strong><span class="foot">${foot}</span></button><button class="metrichelp" data-action="meaning" data-metric="${name}">${t('What does this mean?','这是什么意思？')}</button></article>`;};
const previousDashboard=dashboard;
dashboard=function(){
 const today=summary(data,AS_OF,AS_OF),f=forecast(data),undo=data.transactions.find(x=>x.id===data.lastQuickEntry&&!x.voidedAt);
 let old=previousDashboard().replace(t('A clear view. A smarter next move.','看清财务，迈出明智下一步。'),t("Today's financial status",'今日财务状况')).replace(t('Your next best actions','优先行动'),t('What should I do next?','接下来该做什么？'));
 const position=old.indexOf('<div class="filters">');
 const statusBlock=`<section class="ownerstatus ${f.first?'pressure':''}"><div class="cardhead"><div><h2>${f.first?t('Cash is available now, but a bill needs a plan.','目前有现金，但有一笔账单需要安排。'):t('Your base forecast has no cash deficit.','基准预测没有现金赤字。')}</h2><p class="muted small" style="margin-top:6px">${t(`Synthetic snapshot · ${AS_OF} · not today's live bank balance`,`模拟快照 · ${AS_OF} · 非今日实时银行余额`)}</p></div>${badge(f.first?t('Needs attention','需要关注'):t('Base case stable','基准情况稳定'),f.first?'amber':'')}</div><p>${f.first?t(`${money(today.cash)} available. A deficit of ${money(f.shortfall)} is projected by ${date(f.first.date)}. Compare collection and payment timing before borrowing.`,`目前可用${money(today.cash)}。预计${date(f.first.date)}出现${money(f.shortfall)}缺口。借款前请比较回款与付款时间。`):t(`You have ${money(today.cash)} available. Check late customer payments and your ${money(f.reserve)} emergency buffer before new spending.`,`目前可用${money(today.cash)}。新增支出前，请核查逾期客户回款与${money(f.reserve)}应急备用金。`)}</p><div class="todaygrid"><div><span>${t('Money received on snapshot date','快照当日收到的钱')}</span><strong>${money(today.revenue)}</strong></div><div><span>${t('Money spent on snapshot date','快照当日支出的钱')}</span><strong>${money(today.expenses)}</strong></div><div><span>${label('ar')}</span><strong>${money(today.ar)}</strong></div><div><span>${label('ap')}</span><strong>${money(today.ap)}</strong></div></div>${!today.transactions.length?`<p class="small muted">${t('No money entries on this reporting date.','此报告日期没有收支记录。')}</p>`:''}<div class="quickactions">${btn('+ '+t('Money received','记录收款'),'quickincome','primary')}${btn('− '+t('Money spent','记录支出'),'quickexpense')}${btn(t('What should I do next?','接下来该做什么？'),'nextactions')}${btn(t('Compare your options','比较解决方案')+' →','nav','', 'data-page="options"')}</div></section>${undo?`<div class="undoentry"><span>${t('Last quick entry saved','最近快捷记录已保存')}: ${money(undo.amount,2)} · ${esc(undo.party)}</span>${btn(t('Undo','撤销'),'quickundo','',`data-id="${esc(undo.id)}"`)}</div>`:''}`;
 old=old.slice(0,position)+statusBlock+`<section class="card"><div class="cardhead"><h2>${t('What should I do next?','接下来该做什么？')}</h2>${btn(t('Compare options','比较方案'),'nav','', 'data-page="options"')}</div>${riskRows()}</section><details class="financialdetail"><summary>${t('View period report, charts and invoice summary','查看期间报告、图表与发票汇总')}</summary>`+old.slice(position)+'</details>';
 return old;
};
function meaning(key){
 const descriptions={cashBalance:[['Money available now is the opening ledger plus recorded receipts minus recorded payments.','现在可用的钱等于期初账本加已记录收款减已记录支出。'],['Example: ¥1,000 + ¥500 − ¥200 = ¥1,300.','例如：¥1,000 + ¥500 − ¥200 = ¥1,300。'],['This is recorded cash, not a verified bank balance.','这是已记录现金，不是经银行核实的余额。']],revenue:[['Money received is the cash recorded as coming in during the selected period.','收到的钱是选定期间已记录的流入现金。'],['An unpaid ¥1,000 invoice is not a receipt until you record its payment.','未结清的¥1,000发票在记录收款前不计入收款。'],['Cash receipts are not necessarily accrual accounting revenue.','现金收款不一定等于权责发生制收入。']],expenses:[['Money spent is cash recorded as going out during the selected period.','支出的钱是选定期间已记录的流出现金。'],['Rent and inventory purchases reduce cash when recorded.','记录租金与采购付款后，现金减少。'],['Inventory purchases are cash spending, not necessarily the cost of goods sold.','库存采购是现金支出，不一定等于销售成本。']],profit:[['Subtract period money spent from money received.','用本期间收款减去支出。'],['¥5,000 received − ¥6,000 spent = −¥1,000.','收到¥5,000减支出¥6,000等于−¥1,000。'],['This cash result is not net profit or the money remaining in your bank.','此现金结果不是净利润，也不是银行剩余余额。']],ar:[['Customers still owe you this amount on recorded invoices.','根据已记录发票，客户仍欠您此金额。'],['A ¥1,000 invoice with ¥300 paid leaves ¥700 owed.','¥1,000发票已付¥300，还欠¥700。'],['Money owed is not money already available.','别人欠您的钱不等于现在可用的钱。']],ap:[['This is the outstanding amount you owe suppliers.','这是您尚未付给供应商的金额。'],['A ¥2,000 bill with ¥500 paid leaves ¥1,500 to pay.','¥2,000账单已付¥500，还需付¥1,500。'],['Check due dates to know when cash is needed.','请核查到期日，了解何时需要现金。']],minimum:[['The smallest projected daily balance in this scenario.','此情景中最低的预计日末余额。'],['Month-end cash can be positive even if a mid-month bill causes a deficit.','月末现金为正，月中的账单仍可能导致赤字。'],['Forecasts depend on assumptions and are not guaranteed.','预测依赖假设，不保证发生。']],shortfall:[['How far the lowest forecast cash falls below zero.','最低预测现金低于零的部分。'],['A lowest balance of −¥1,000 means a ¥1,000 deficit.','最低余额−¥1,000代表¥1,000赤字。'],['This does not include your emergency buffer.','这不包含应急备用金。']],need:[['Extra cash needed to preserve your emergency buffer at the lowest point.','在最低点保留应急备用金所需的额外现金。'],['A −¥1,000 low point and ¥2,000 buffer imply ¥3,000 needed.','最低−¥1,000与¥2,000备用金意味着需要¥3,000。'],['This is a scenario gap, not a recommended or approved loan amount.','这是情景缺口，不是推荐或获批贷款金额。']]};
 const info=descriptions[key]||descriptions.minimum;modal(label(key),`<p>${t(...info[0])}</p><div class="info">${t(...info[1])}</div><p class="small muted">${t(...info[2])}</p>`);
}
function quickForm(type){
 const rows=data.invoices.filter(i=>i.kind===(type==='income'?'receivable':'payable')&&outstanding(i));
 modal(type==='income'?t('Record money received','记录收款'):t('Record money spent','记录支出'),`<form id="quickform" class="quickform" data-type="${type}"><p class="entrynote">${t(`Add a synthetic record to ${businessName()}. No money is sent or verified.`,`向${businessName()}添加模拟记录。不发送或核实真实资金。`)}</p><div class="controls"><div class="field"><label for="quickamount">${t('Amount (CNY)','金额（人民币）')}</label><input id="quickamount" name="amount" required type="number" inputmode="decimal" step=".01" min=".01" max="1000000" placeholder="0.00"></div><div class="field"><label for="quickparty">${type==='income'?t('Customer or source','客户或来源'):t('Supplier or recipient','供应商或收款方')}</label><input id="quickparty" name="party" required maxlength="100" placeholder="${t('Who was it from / for?','来自谁 / 支付给谁？')}"></div><div class="field"><label for="quickdate">${t('Record date','记录日期')}</label><input id="quickdate" name="date" type="date" required min="${addDays(data.openingDate,1)}" max="${AS_OF}" value="${AS_OF}"></div><div class="field"><label for="quickcategory">${t('Category','分类')}</label><select id="quickcategory" name="category">${(type==='income'?['sales','other']:['other','operations','rent','payroll','inventory','marketing']).map(c=>`<option value="${c}">${catLabel(c)}</option>`).join('')}</select></div></div><details><summary>${t('More details (optional)','更多信息（可选）')}</summary><div class="controls"><div class="field"><label for="quickinvoice">${t('Link an invoice / bill','关联发票 / 账单')}</label><select name="invoiceId" id="quickinvoice"><option value="">${t('No linked invoice','不关联发票')}</option>${rows.map(i=>`<option value="${esc(i.id)}">${esc(i.id)} · ${esc(party(i))} · ${money(outstanding(i),2)}</option>`).join('')}</select></div><div class="field"><label for="quickmethod">${t('Payment method (record only)','付款方式（仅记录）')}</label><select id="quickmethod" name="method">${[['unspecified',t('Not specified','未指定')],['cash',t('Cash','现金')],['bank',t('Bank transfer','银行转账')],['other',t('Other','其他')]].map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></div></div><div class="field" style="margin-top:12px"><label for="quicknote">${t('Note','备注')}</label><textarea name="note" id="quicknote" maxlength="300" rows="2"></textarea></div></details><div id="quickerror" role="alert" aria-live="polite"></div><p class="small muted">${t('The reporting date stays fixed at 13 Oct 2026. Linking a record reduces that invoice’s outstanding balance exactly once.','报告日期固定为2026年10月13日。关联记录仅按一次结算减少未结金额。')}</p><footer>${btn(t('Cancel','取消'),'closemodal','', 'type="button"')}<button type="submit" class="btn primary">${t('Review and save','核对并保存')}</button></footer></form>`,' ');
}
function commitQuick(next){
 try{validateData(next);if(!accountState.user)localStorage.setItem('finora-'+org,JSON.stringify(next));data=next;markSync();render();return true;}catch{toast(t('Could not save. No balances changed. Free browser storage or export a backup.','无法保存，余额未更改。请清理浏览器存储或导出备份。'));return false;}
}
function transactionsPage(){const rows=data.transactions.filter(x=>x.createdVia==='quick').slice().reverse();return `${pageHead('transactions',t('Add a record. Check it. Reverse mistakes safely.','添加记录、核查信息、安全撤销错误。'))}<div class="quickactions">${btn('+ '+t('Money received','记录收款'),'quickincome','primary')}${btn('− '+t('Money spent','记录支出'),'quickexpense')}</div><section class="card"><h2>${t('Quick-entry history','快捷收支记录')}</h2><p class="small muted" style="margin:8px 0">${t('Entries are synthetic and stored in this browser. Undo preserves the original record and audit history.','记录为模拟数据，存储于当前浏览器。撤销保留原始记录与审计历史。')}</p>${rows.length?`<div class="tablewrap"><table><thead><tr><th>${t('Date / person','日期 / 交易方')}</th><th>${t('Type','类型')}</th><th class="money">${t('Amount','金额')}</th><th>${t('Action','操作')}</th></tr></thead><tbody>${rows.map(x=>`<tr class="${x.voidedAt?'reversed':''}"><td>${date(x.date)}<br>${esc(x.party)}<br><button class="textbtn" data-action="evidence" data-id="${esc(x.id)}">${esc(x.id)}</button></td><td>${x.voidedAt?badge(t('Reversed','已撤销'),'gray'):badge(x.type==='income'?t('Money received','收款'):t('Money spent','支出'),x.type==='income'?'':'amber')}</td><td class="money">${money(x.amount,2)}</td><td>${x.voidedAt?'—':btn(t('Undo','撤销'),'quickundo','',`data-id="${esc(x.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>${t('No quick entries yet','尚无快捷记录')}</h3><p>${t('Use the buttons above. Existing imported and invoice records are preserved in their workspaces.','请使用上方按钮。现有导入与发票记录仍保留在各自工作区。')}</p></div>`}</section>`;}
let comparisonInput={invoiceId:'INV-1042',percent:100,collectionDays:1,collectionCost:0,billId:'BILL-0201',deferralDays:14};
function optionsPage(){const invoiceRows=data.invoices.filter(i=>i.kind==='receivable'&&outstanding(i)),billRows=data.invoices.filter(i=>i.kind==='payable'&&outstanding(i));if(!invoiceRows.some(i=>i.id===comparisonInput.invoiceId))comparisonInput.invoiceId=invoiceRows[0]?.id||'';if(!billRows.some(i=>i.id===comparisonInput.billId))comparisonInput.billId=billRows[0]?.id||'';
 const c=compareActions(data,{...comparisonInput,loanTerms:loanInput},scenario),input=(key,title,value,min,max,step=1)=>`<div class="field"><label for="compare-${key}">${title}</label><input id="compare-${key}" data-compare="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
 return `${pageHead('options',t('Compare timing, cost and uncertainty before acting.','行动前，比较时间、成本与不确定性。'))}<div class="info">${t('Simulated — not executed. All options start from the same cash and existing cash-flow assumptions. Collections move money from its original expected date; they do not count an invoice twice.','模拟 — 未执行。所有方案使用相同起始现金与现有现金流假设。催收仅移动原预计日期的回款，不会重复计算发票。')}</div><section class="card"><div class="cardhead"><h2>${t('Baseline: keep current assumptions','基准：保留当前假设')}</h2>${btn(t('Review assumptions','核查假设'),'nav','', 'data-page="cash"')}</div>${optionFacts(c.base,c.base)}<p class="small muted">${t('The reporting date is 13 Oct 2026. Figures at 7, 30 and 90 days are scenario estimates.','报告日期为2026年10月13日。7、30与90天数值均为情景估计。')}</p></section><div class="options-grid"><section class="optioncard"><h2>1. ${t('Collect customer payments','收回客户欠款')}</h2><div class="field"><label for="compare-invoiceId">${t('Select an outstanding invoice','选择未结发票')}</label><select id="compare-invoiceId" data-compare="invoiceId">${invoiceRows.length?invoiceRows.map(i=>`<option value="${esc(i.id)}" ${i.id===comparisonInput.invoiceId?'selected':''}>${esc(i.id)} · ${money(outstanding(i))}</option>`).join(''):`<option value="">${t('No outstanding invoice','没有未结发票')}</option>`}</select></div>${input('percent',t('Percentage to collect (%)','拟收回比例（%）'),comparisonInput.percent,0,100)}${input('collectionDays',t('Expected receipt in days','预计几天后收到'),comparisonInput.collectionDays,1,90)}${input('collectionCost',t('Collection cost (CNY)','催收成本（人民币）'),comparisonInput.collectionCost/100,0,1000000,.01)}${c.collect?optionFacts(c.collect,c.base):missingOption(t('An outstanding customer invoice is required.','需要未结客户发票。'))}<p class="small muted">${t('Added financing debt: none. Cost:','新增融资债务：无。成本：')} ${money(comparisonInput.collectionCost,2)}</p><p class="optionrisk">${t('Customer agreement and payment are uncertain. This changes the forecast only; it does not mark the invoice paid.','客户同意与回款时间不确定。仅改变预测，不标记发票已结清。')}</p>${btn(t('View selected invoice','查看所选发票'),'evidence','',`data-id="${esc(comparisonInput.invoiceId)}" ${!c.collect?'disabled':''}`)}</section><section class="optioncard"><h2>2. ${t('Renegotiate supplier timing','协商供应商付款时间')}</h2><div class="field"><label for="compare-billId">${t('Select a supplier bill','选择供应商账单')}</label><select id="compare-billId" data-compare="billId">${billRows.length?billRows.map(i=>`<option value="${esc(i.id)}" ${i.id===comparisonInput.billId?'selected':''}>${esc(i.id)} · ${money(outstanding(i))}</option>`).join(''):`<option value="">${t('No unpaid bill','没有未付账单')}</option>`}</select></div>${input('deferralDays',t('Proposed extra days','拟延后天数'),comparisonInput.deferralDays,0,60)}<div class="info">${c.defer?t(`Assumed new date: ${c.defer.events.find(e=>e.id===comparisonInput.billId)?.date||'Beyond horizon'}`,`假设新日期：${c.defer.events.find(e=>e.id===comparisonInput.billId)?.date||'预测期之外'}`):t('No supplier obligation available.','没有可用供应商付款义务。')}</div>${c.defer?optionFacts(c.defer,c.base):missingOption(t('An unpaid supplier bill is required.','需要未付供应商账单。'))}<p class="small muted">${t('Late fees are unknown and excluded, not assumed to be free.','滞纳金未知，未计入；不代表没有费用。')}</p><p class="optionrisk">${t('Requires supplier agreement. Delay may cause fees, breach terms or harm the relationship. The actual bill date stays unchanged.','需要供应商同意。延期可能产生费用、违反条款或影响关系。实际账单日期不变。')}</p>${btn(t('Review supplier bill','核查供应商账单'),'evidence','',`data-id="${esc(comparisonInput.billId)}" ${!c.defer?'disabled':''}`)}</section><section class="optioncard"><h2>3. ${t('Test a business loan','测试企业借款')}</h2>${badge(t('Hypothetical terms','假设条款'),'amber')}<div class="controls" style="margin-top:12px">${loanField('principal',t('Principal (CNY)','本金（人民币）'),loanInput.principal/100,1,1000000,100)}${loanField('apr',t('Annual rate (%)','年利率（%）'),loanInput.apr,0,100,.1)}${loanField('months',t('Months','月数'),loanInput.months,1,60,1)}${loanField('fee',t('Upfront fee (%)','前期费用（%）'),loanInput.fee,0,20,.1)}</div>${optionFacts(c.borrow,c.base)}<div class="optionfacts"><div><span>${t('Monthly installment','每月还款')}</span><strong>${money(c.loan.payment,2)}</strong></div><div><span>${t('Full-term cost incl. fee','全期限成本含手续费')}</span><strong>${money(c.loan.cost,2)}</strong></div><div><span>${t('Total installments + fee','还款合计加费用')}</span><strong>${money(c.loan.total+c.loan.fee,2)}</strong></div><div><span>${t('Debt remaining at day 90','第90天剩余本金')}</span><strong>${money(c.loan.schedule[Math.min(3,loanInput.months)-1].balance,2)}</strong></div></div><p class="optionrisk">${t('Proceeds tomorrow, after fees; first repayment on day 30. No lender offer or approval. Debt remains an obligation after the chart ends.','假设明日到账并扣费，第30天首次还款。非机构报价或批准。图表结束后仍可能有债务义务。')}</p>${btn(t('Detailed loan analysis','详细借款分析'),'nav','', 'data-page="financing"')}</section></div><section class="card" style="margin-top:18px"><h2>${t('Combine the three assumptions','组合三项假设')}</h2>${optionFacts(c.combined,c.base)}<p class="optionrisk">${t('Combining options does not guarantee agreement or payment. Compare the cash benefit against collection costs, unknown late fees and debt repayment. No option is universally best.','组合方案不保证达成协议或回款。请将现金改善与催收成本、未知滞纳金、债务还款比较。没有适合所有企业的最佳方案。')}</p></section>`;
}
function missingOption(text){return `<div class="empty"><p>${text}</p></div>`;}
function optionFacts(f,base){return `<div class="optionfacts">${[[t('Change in cash tomorrow','明日现金变化'),f.changeTomorrow],[t('Cash after 7 days','7天后现金'),f.cash7],[t('Cash after 30 days','30天后现金'),f.cash30],[t('Cash after 90 days','90天后现金'),f.cash90],[t('Lowest projected cash','最低预计现金'),f.min.cash],[t('Change in lowest cash vs. base','最低现金较基准变化'),f.min.cash-base.min.cash]].map(([n,a])=>`<div><span>${n}</span><strong>${money(a,2)}</strong></div>`).join('')}<div><span>${t('First cash deficit','首次现金赤字')}</span><strong>${f.firstDate?date(f.firstDate):t('None projected','未预计出现')}</strong></div></div>`;}
function mobileNav(inMore=false){return `<nav class="bottomnav" aria-label="${t('Mobile navigation','移动导航')}">${[['overview',t('Home','首页')],['transactions',t('Record','记录')],['cash',t('Forecast','预测')],['copilot',t('Assistant','助手')]].map(([p,n])=>`<button data-action="nav" data-page="${p}" class="${!inMore&&page===p?'active':''}" ${!inMore&&page===p?'aria-current="page"':''}>${navIcon(p,!inMore&&page===p)}<span>${n}</span></button>`).join('')}<button data-action="more" class="${(inMore||!['overview','transactions','cash','copilot'].includes(page))?'active':''}" ${(inMore||!['overview','transactions','cash','copilot'].includes(page))?'aria-current="page"':''}>${navIcon('more',(inMore||!['overview','transactions','cash','copilot'].includes(page)))}<span>${t('More','更多')}</span></button></nav>`;}

function answerHTML(a){const reason=a.figures.length?a.figures.slice(0,3).map(([k,v])=>`${label(k)}: ${money(v,2)}`).join(' · '):t('The information needed is not yet available.','所需信息尚不可用。');const next={help:t('Open Business setup, then add a receipt or expense from Home.','打开企业设置，然后在首页添加收款或支出。'),cash:t('Review the next large bill and compare collection timing.','核查下一笔大额账单并比较回款时间。'),invoices:t('Open the overdue invoice and prepare a reminder draft.','打开逾期发票并准备提醒草稿。'),expenses:t('Check source records before treating the expense as a duplicate.','判断重复支出前先核对原始记录。'),scenario:t('Open the scenario workspace and test your assumptions.','打开情景工作区并测试假设。'),financing:t('Compare collections and supplier timing with borrowing costs.','比较回款、供应商付款时间与借款成本。'),options:t('Choose an invoice, supplier bill and financing terms in the comparison.','在比较页面选择发票、账单与融资条款。'),hiring:t('Enter total additional monthly payroll, including employer costs.','输入包含雇主成本的每月新增薪酬。'),clarify:t('Tell me the decision and period you want to evaluate.','请告诉我需要评估的决策与期间。'),comparison:t('Choose complete comparable reporting periods.','请选择完整且可比的报告期间。')};
 return `<div class="answer"><div class="answertop">${icon('copilot')}<strong>${a.live?t('Live explanation · engine figures','实时解释 · 引擎数值'):t('Simulated assistant · calculated results','模拟助手 · 已计算结果')}</strong></div>${a.aiExplanation?`<div class="ai-narrative" style="margin:12px 0"><h3>${t('Assistant answer','助手回答')}</h3><p style="white-space:pre-line;line-height:1.65;margin-top:8px">${esc(a.aiExplanation.replace(/^#{1,6}\s+/gm,''))}</p></div>`:''}${a.aiFailure?`<div class="info">${esc(aiFailureText(a.aiFailure))}</div>`:''}<div class="answer-short"><div><h3>${a.kind==='help'?t('How to use Finora','如何使用融财'):t('Engine finding','引擎结论')}</h3><p>${esc(a.summary)}</p></div>${a.figures.length?`<div><h3>${t('Verified figures','已核算数值')}</h3><p>${esc(reason)}</p></div>`:''}<div><h3>${t('Next step','下一步')}</h3><p>${next[a.kind]||next.cash}</p></div></div><details class="evidence-details"><summary>${t('View evidence & calculations','查看证据与计算')}</summary><div class="numbers">${a.figures.map(([k,v])=>`<div><span>${label(k)}</span><strong>${money(v,2)}</strong></div>`).join('')}</div><div class="evidence">${a.evidence.map(id=>`<button data-action="evidence" data-id="${esc(id)}">${esc(id)}</button>`).join('')}</div><details><summary>${t('Calculation & assumptions','计算与假设')}</summary>${a.assumptions.map(x=>`<p>${esc(x)}</p>`).join('')}</details><p>${esc(a.uncertainty)}</p></details><p class="small muted" style="margin:8px 0">${a.kind==='help'?t('This guide applies to the current demo. No actual money is sent.','此指南适用于当前演示，不发送真实资金。'):t('Forecast timing is uncertain. Review evidence before acting.','预测时间具有不确定性。行动前请核查证据。')}</p>${a.proposedScenario?`<div class="info"><p>${t('Review proposed scenario inputs before calculating','计算前请核对提议情景参数')}</p><pre style="white-space:pre-wrap">${esc(JSON.stringify({...a.proposedScenario,hiringCNY:(a.proposedScenario.hiring||0)/100,oneOffCNY:(a.proposedScenario.oneOff||0)/100,hiring:undefined,oneOff:undefined},null,2))}</pre>${btn(t('Review inputs','核对参数'),'reviewaiscenario','',`data-scenario="${esc(JSON.stringify(a.proposedScenario))}"`)}</div>`:''}${btn(a.kind==='help'?t('Set up my business','设置我的企业'):t('Evaluate next action','评估下一步')+' →','nav','',`data-page="${a.action}"`)}</div>`;
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;
 if(el.dataset.action==='meaning')meaning(el.dataset.metric);
 if(el.dataset.action==='quickincome')quickForm('income');
 if(el.dataset.action==='quickexpense')quickForm('expense');
 if(el.dataset.action==='quickundo'){const id=el.dataset.id;confirm(t('Undo this money entry?','撤销此收支记录？'),`<p>${t('The original record is kept with a reversal marker. Any linked invoice settlement and cash effect are reversed together.','原始记录保留并标记撤销。关联发票结算与现金影响一起恢复。')}</p>`,()=>{try{const next=undoQuickEntry(data,id);if(commitQuick(next))toast(t('Entry reversed. Balances restored; history retained.','记录已撤销，余额已恢复，历史保留。'));}catch{toast(t('Undo is unavailable for this entry. Review the record before correcting it.','此记录不可撤销。更正前请核查记录。'));}});}
 if(el.dataset.action==='nextactions'){modal(t('What should I do next?','接下来该做什么？'),`<p class="entrynote">${t('Up to three priorities from the current business records.','根据当前企业记录列出最多三项优先事项。')}</p>${riskRows()}<div class="quickactions">${btn(t('Compare your options','比较解决方案'),'nav','', 'data-page="options"')}${btn(t('Ask assistant','询问助手'),'askcash')}</div>`);}
 if(el.dataset.action==='more')openMore();
 if(el.dataset.action==='nav'&&$('#modalroot').innerHTML)closeModal({discardMore:true});
});
document.addEventListener('submit',e=>{if(e.target.id!=='quickform')return;e.preventDefault();const form=e.target,v=Object.fromEntries(new FormData(form));const input={...v,note:v.note||'',type:form.dataset.type,id:`${org}-QUICK-${crypto.randomUUID()}`};let next;try{next=recordQuickEntry(data,input);}catch{$('#quickerror').innerHTML=`<div class="error">${t('Check the amount, date and linked invoice. Amounts must be positive with at most two decimals and cannot exceed the unpaid invoice balance.','请核查金额、日期与关联发票。金额须为正数且最多两位小数，不得超过未结发票余额。')}</div>`;return;}confirm(t('Confirm this money record','确认此收支记录'),`<p>${esc(v.party)} · ${money(moneyInput(v.amount),2)} · ${esc(v.date)}</p><div class="info">${t('Save a synthetic entry locally. No actual money moves. Undo remains available for this quick entry.','本地保存模拟记录。不发生实际资金转移。此快捷记录可撤销。')}</div>`,()=>{if(next.org!==org){toast(t('Business changed; reopen the entry form.','企业已变更；请重新打开录入表单。'));return;}if(commitQuick(next))toast(t('Saved. Use Undo on the dashboard or Money entries.','已保存。可在总览或收支记录页面撤销。'));});});
document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.compare)return;const key=el.dataset.compare,old=comparisonInput[key];comparisonInput[key]=['invoiceId','billId'].includes(key)?el.value:key==='collectionCost'?Math.round(+el.value*100):+el.value;try{compareActions(data,{...comparisonInput,loanTerms:loanInput},scenario);render();}catch{comparisonInput[key]=old;toast(t('Enter valid dates, percentages and costs.','请输入有效天数、比例与成本。'));render();}});

labels.ai=['AI business workspace','AI业务工作区'];labels.imports=['Import statements','导入账单'];labels.collections=['Collect payments','催收回款'];labels.fapiao=['Invoice documents','发票文件'];labels.weekly=['Weekly action plan','每周行动'];labels.setup=['Business setup','企业设置'];labels.account=['Account & access','账号与权限'];
let importSource='wechat',statementPreview=null,invoiceDraft=null,accountState={user:null,csrf:null,businesses:[],activeOwner:null,revision:null,role:'owner',sync:'offline'},syncTimer=null;
const sector=()=>data.settings.sector||(org==='guangzhou'?'trading':org==='chengdu'?'services':'retail');
const sectorName=()=>sectorTemplates[sector()]?.[lang==='zh'?'zh':'en']||sectorTemplates.retail[lang==='zh'?'zh':'en'];
const enhancedCat=catLabel;catLabel=function(c){return t({fees:'Payment fees',ingredients:'Ingredients',delivery:'Delivery',logistics:'Logistics',software:'Software'}[c],{fees:'支付手续费',ingredients:'食材',delivery:'配送',logistics:'物流',software:'软件订阅'}[c])||enhancedCat(c);};
const mobilePreviousDashboard=dashboard;
dashboard=function(){const s=summary(data),today=summary(data,AS_OF,AS_OF),safe=safeToSpend(data,30),f=forecast(data),alerts=weeklyActions(data),last=data.transactions.find(t=>t.id===data.lastQuickEntry&&!t.voidedAt);return `<div class="appgreeting" data-tour="home-intro"><div><div class="eyebrow muted">Finora 融财 · ${sectorName()}</div><h1 style="margin-top:5px">${t('Your money, clearer.','经营的钱，一目了然。')}</h1><p>${t('Know your next move before you commit.','先看清，再决定下一步。')}</p></div><button class="avatar" data-action="nav" data-page="account" style="border:0" aria-label="${t('Account','账号')}">${accountState.user?'✓':'LW'}</button></div><section class="mobilehero"><div class="hero-label">${t('Money available now','现在可用的钱')}</div><div class="hero-money" data-tour="recorded-cash">${money(s.cash)}</div><div class="hero-date">${t(`Synthetic data · ${AS_OF} · CNY`,`模拟数据 · ${AS_OF} · 人民币`)}</div></section>${safeGaugePanel(safe)}<div class="quickactions receipt-entry">${btn(textPdfIcon()+t('Upload PDF receipt','上传PDF收据'),'nav','','data-page="pdfreceipts"')} ${btn(t('Demo / Guided tour','演示 / 功能导览'),'starttour')}</div><div class="homequick"><button data-action="quickincome"><span class="quickicon">${icon('plus')}</span>${t('Add receipt','记录收款')}</button><button data-action="quickexpense"><span class="quickicon">${icon('expenses')}</span>${t('Add expense','记录支出')}</button><button data-action="nav" data-page="imports"><span class="quickicon">${icon('down')}</span>${t('Import statement','导入账单')}</button></div>${last?`<div class="undoentry"><span>${t('Last quick entry saved','最近快捷记录已保存')} · ${money(last.amount,2)}</span>${btn(t('Undo','撤销'),'quickundo','',`data-id="${esc(last.id)}"`)}</div>`:''}<div class="sectionline"><h2>${t("Today's financial status",'今日财务状况')}</h2><button data-action="nav" data-page="reports">${t('Details','详情')} →</button></div><div class="glancegrid"><button class="glance" data-action="nav" data-page="collections"><span>${t('Money owed to you','别人欠你的钱')}</span><strong>${money(s.ar)}</strong></button><button class="glance" data-action="nav" data-page="invoices"><span>${t('Money you owe','你需要支付的钱')}</span><strong>${money(s.ap)}</strong></button><button class="glance" data-action="nav" data-page="transactions"><span>${t('Received on reporting day','报告当日收到')}</span><strong>${money(today.revenue)}</strong></button><button class="glance" data-action="nav" data-page="expenses"><span>${t('Spent on reporting day','报告当日支出')}</span><strong>${money(today.expenses)}</strong></button></div><div class="sectionline"><h2>${t('What should I do next?','接下来该做什么？')}</h2><button data-action="nav" data-page="weekly">${t('Weekly plan','每周计划')} →</button></div>${alerts.length?alerts.map(r=>`<div class="homeaction"><div class="actionicon">${icon(r.route==='cash'?'cash':r.route==='invoices'?'invoices':'risk')}</div><div><h3>${t(...riskText[r.id])}</h3><p>${riskDescription(r)}</p><button data-action="nav" data-page="${r.id==='overdue'?'collections':r.route}">${t('Review next step','核查下一步')} →</button></div></div>`).join(''):`<section class="card"><h3>${t('No unreviewed alerts','没有未核查提醒')}</h3><p class="small muted">${t('Review scheduled bills before new spending.','新增支出前请核查已安排账单。')}</p></section>`}<div class="homeassistant"><div class="spark">${icon('copilot')}</div><div><h3>${t('Ask your finance assistant','问问财务助手')}</h3><p>${t('Short answers. Numbers you can check.','简洁回答，数字可核查。')}</p></div><button data-action="askcash" aria-label="${t('Ask about cash','询问现金状况')}">↗</button></div><div class="sectionline"><h2>${t('Explore your options','比较解决方案')}</h2><button data-action="nav" data-page="options">${t('Compare','比较')} →</button></div><section class="card"><p class="small muted">${t('Compare collections, agreed supplier timing and hypothetical financing from the same starting cash.','用相同起始现金比较回款、协商供应商时间与假设融资。')}</p>${btn(t('Compare three actions','比较三项行动'),'nav','primary','data-page="options"')}</section>${!data.settings.onboarded?`<section class="card"><h3>${t('Make Finora fit your business','让融财更适合您的业务')}</h3><p class="small muted" style="margin:7px 0">${t('Choose your industry and emergency buffer. Your records stay intact.','选择行业与应急备用金，现有记录保持不变。')}</p>${btn(t('Complete setup','完成设置'),'nav','', 'data-page="setup"')}</section>`:''}<details class="financialdetail"><summary>${t('Forecast chart & detailed overview','预测图表与详细总览')}</summary>${mobilePreviousDashboard()}</details><footer class="privacy-footer">${btn(icon('shield')+t('Security & Privacy','安全与隐私'),'privacy')}</footer>`;};
function importPage(){return `<section class="card">${btn(textPdfIcon()+t('Upload PDF receipt','上传PDF收据'),'nav','primary','data-page="pdfreceipts"')}</section>${pageHead('imports',t('Upload, review, then save. No payment account password needed.','上传、核查、再保存。不需要支付账号密码。'))}<section class="card"><h2>${t('Where is this statement from?','账单来自哪里？')}</h2><div class="sourcechoices">${[['wechat','WeChat Pay / 微信支付'],['alipay','Alipay / 支付宝'],['bank',t('Bank statement','银行流水')],['generic',t('Finora CSV','融财CSV')]].map(([key,n])=>`<button data-action="importsource" data-source="${key}" class="${importSource===key?'active':''}">${n}</button>`).join('')}</div><p class="small muted">${t('Export a merchant statement, then upload CSV. Supported headers include common Chinese transaction, amount, date and counterparty fields. XLSX must be saved as CSV first.','先导出商户账单，再上传CSV。支持常见中文交易号、金额、日期与交易方字段。XLSX需先另存为CSV。')}</p><div class="field" style="margin:14px 0"><label for="statementfile">${t('Choose CSV · up to 1 MB','选择CSV · 最大1MB')}</label><input type="file" id="statementfile" accept=".csv,text/csv"></div>${btn(t('Download source template','下载来源模板'),'statementtemplate')}<div class="info">${t('Refunds, transfers and unclear directions are held for manual review. They are not silently treated as new sales. Merchant WeChat gross receipts may include a separate fee row; net statements need manual reconciliation.','退款、转账与方向不明的记录留待人工核查，不会默认为新增销售。微信商户总收款可单独计入手续费；净额账单需人工核对。')}</div></section>${statementPreview?`<section class="card"><h2>${t('Review before importing','导入前核查')}</h2><div class="info">${t(`${statementPreview.records.length} entries · ${statementPreview.duplicates.length} duplicate rows · ${statementPreview.errors.length} errors · ${statementPreview.skipped.length} held for review`,`${statementPreview.records.length}条记录 · ${statementPreview.duplicates.length}条重复 · ${statementPreview.errors.length}条错误 · ${statementPreview.skipped.length}条待核查`)}</div><div class="tablewrap"><table><thead><tr><th>${t('Date / party','日期 / 交易方')}</th><th>${t('Category','分类')}</th><th class="money">${t('Amount','金额')}</th></tr></thead><tbody>${statementPreview.records.slice(0,15).map(x=>`<tr><td>${esc(x.date)}<br>${esc(x.party)}</td><td>${catLabel(x.category)}</td><td class="money">${x.type==='income'?'+':'−'}${money(x.amount,2)}</td></tr>`).join('')}</tbody></table></div>${statementPreview.errors.length?`<div class="error">${t('Fix lines:','请修正行：')} ${statementPreview.errors.map(x=>x.line).join(', ')}</div>`:''}${statementPreview.skipped.length?`<details><summary>${t('Rows needing manual review','需要人工核查的行')}</summary>${statementPreview.skipped.map(x=>`<p class="small muted">${t('Line','行')} ${x.line} · ${importReason(x.reason)}</p>`).join('')}</details>`:''}${btn(t('Confirm reviewed entries','确认已核查记录'),'savestatement','primary',statementPreview.errors.length||!(statementPreview.records.length||statementPreview.review?.length)?'disabled':'')}<p class="small muted" style="margin-top:9px">${t('Only validated entries are imported. Held rows remain excluded; your report will be incomplete until you resolve them.','仅导入验证通过的记录。待核查行仍不计入；解决前报表不完整。')}</p></section>`:''}`;}
function importReason(reason){return t({refund_requires_review:'Refund: review separately',direction_requires_review:'Unclear direction or transfer',not_completed:'Not completed',invalid_amount_date_or_id:'Invalid amount, date or identifier'}[reason]||reason,{refund_requires_review:'退款：单独核查',direction_requires_review:'方向不明或转账',not_completed:'未完成',invalid_amount_date_or_id:'金额、日期或编号无效'}[reason]||reason);}
function collectionsPage(){return `${workflowHead('collections',t('Review and follow up on money owed.','核查并跟进客户欠款。'),1)}<div class="workflow-search">${icon('search')}<label class="visually-hidden" for="collectionsearch">${t('Search invoices','搜索发票')}</label><input id="collectionsearch" type="search" value="${esc(collectionSearch)}" placeholder="${t('Search invoices','搜索发票')}"></div><div class="sectionline"><h2>${t('Outstanding customer invoices','未结客户发票')}</h2><span class="small muted">${t('Reporting snapshot','报告快照')} · ${date(AS_OF)}</span></div><div id="collection-results">${collectionRows()}</div><details class="saved-drafts"><summary>${t('Saved reminder drafts','已保存催款草稿')} · ${(data.drafts||[]).length}</summary>${(data.drafts||[]).slice(-10).reverse().map((d,i)=>`<button class="tool-row" data-action="viewcollectiondraft" data-index="${(data.drafts||[]).length-1-i}"><span class="workspace-symbol">${workspaceIcon('draft')}</span><span class="tool-copy"><strong>${esc(d.id)}</strong><small>${t('Saved draft · nothing sent','已保存草稿 · 未发送')}</small></span>${chevron()}</button>`).join('')||`<p class="small muted">${t('Prepare and review a reminder from an invoice above. Saving a draft never sends it or records payment.','请从上方发票准备并核对催款信息。保存草稿不会发送消息或记录付款。')}</p>`}</details>`;}
function collectionRows(){const q=collectionSearch.normalize('NFKC').trim().toLowerCase(),rows=collectionQueue(data).filter(i=>!q||[i.id,i.party,i.partyZh].some(v=>String(v||'').normalize('NFKC').toLowerCase().includes(q)));return rows.length?rows.map(i=>`<section class="collectioncard collection-list-item"><button class="tool-row" data-action="collectiondetail" data-id="${esc(i.id)}"><span class="workspace-symbol">${workspaceIcon('invoice')}</span><span class="tool-copy"><strong>${esc(i.id)}</strong><span>${esc(party(i))}</span><small><b>${money(i.balance,2)}</b> · ${i.lateDays?'⚠ '+t('Overdue','已逾期'):t('Due','到期')+' '+date(i.due)}</small></span>${chevron()}</button></section>`).join(''):`<section class="empty"><h2>${q?t('No matching invoices','没有匹配的发票'):t('No outstanding customer payments','没有未结客户回款')}</h2><p>${t('Change your search, or create an invoice to track expected collections. Creating an invoice does not record cash.','可调整搜索，或创建发票以跟踪预计回款。创建发票不会记录现金到账。')}</p>${btn(t('View invoices','查看发票'),'nav','','data-page="invoices"')}</section>`;}

function reminderText(i){return t(`Hello ${party(i)}, our invoice ${i.id} has ${money(outstanding(i),2)} unpaid, due ${i.due}. Could you confirm a payment date? Thank you.`,`您好，${party(i)}，发票${i.id}仍有${money(outstanding(i),2)}未结清，到期日${i.due}。烦请确认预计付款日期，谢谢。`);}
function fapiaoPage(){const docs=data.documents||[];return `<section class="card">${btn(textPdfIcon()+t('Upload PDF receipt','上传PDF收据'),'nav','primary','data-page="pdfreceipts"')}<p>${t('Structured text PDFs: extract, review and confirm a paid transaction.','结构化文本PDF：提取、核对并确认已付款交易。')}</p></section>${pageHead('fapiao',t('Keep invoice evidence beside the payment it supports.','把发票凭证与对应付款放在一起。'))}<section class="card"><h2>${t('Add an invoice document','添加发票文件')}</h2><p class="small muted" style="margin:9px 0">${t('PDF, JPG, PNG or text · up to 2 MB. Text extraction is available offline for .txt; This hosted version supports text extraction and manual document fields. PDF/image OCR and original-file storage require the included local account server. Always review extracted fields.','PDF、JPG、PNG或文本，最大2MB。离线可读取TXT文本；此托管版本支持文本提取及手动字段；PDF/图片OCR及原件存储需使用附带本地账号服务器。请始终核对提取字段。')}</p><div class="field"><label for="invoicefile">${t('Choose a document','选择文件')}</label><input id="invoicefile" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt"></div><div class="quickactions">${btn(t('Enter details manually','手动填写信息'),'manualdocument')}</div></section>${invoiceDraft?documentDraftForm():''}<section class="card"><h2>${t('Saved invoice evidence','已保存发票凭证')}</h2>${docs.length?docs.map(d=>`<div class="documentrow"><strong>${esc(d.number||d.name)}</strong><br><span class="muted">${esc(d.seller||'—')} · ${esc(d.date||'—')} · ${d.amount?money(Math.round(Number(d.amount)*100),2):t('Amount missing','金额缺失')}</span><br>${badge(t('Not officially verified','未经官方查验'),'amber')}<p class="small muted" style="margin:5px 0">${t('Linked record','关联记录')}: ${esc(d.linkedId||t('No match','未匹配'))}</p><div class="quickactions">${d.serverId?btn(t('Download original','下载原件'),'downloaddocument','',`data-id="${esc(d.serverId)}"`):''}${btn(t('Match payment / invoice','匹配付款 / 发票'),'matchdocument','',`data-id="${esc(d.id)}"`)}</div></div>`).join(''):`<div class="empty"><p>${t('No invoice documents saved yet. Add a document above and review its fields to keep supporting evidence; adding evidence alone never changes cash.','尚未保存发票文件。请在上方添加文件并核对字段以保留支持凭证；仅添加凭证不会改变现金。')}</p></div>`}<div class="info">${t('Extraction is not official tax verification. Missing or unmatched documents remain visible. Finora does not issue official fapiao.','信息提取不代表税务官方查验。缺失或未匹配文件保持可见。融财不开具官方税务发票。')}</div><a class="btn" href="https://inv-veri.chinatax.gov.cn/" target="_blank" rel="noopener noreferrer">${t('Open official invoice verification','打开官方发票查验')} ↗</a></section>`;}
function documentDraftForm(){return `<section class="card"><h2>${t('Review extracted or entered fields','核对提取或填写的信息')}</h2>${invoiceDraft.warning?`<div class="error">${esc(invoiceDraft.warning)}</div>`:''}<form id="documentform"><div class="controls">${[['number',t('Invoice number','发票号码')],['date',t('Issue date','开票日期')],['amount',t('Total incl. tax (CNY)','价税合计（人民币）')],['seller',t('Seller','销售方')],['buyer',t('Buyer','购买方')],['taxId',t('Tax identifier','纳税识别号')]].map(([k,n])=>`<div class="field"><label for="doc-${k}">${n}</label><input name="${k}" id="doc-${k}" value="${esc(invoiceDraft[k]||'')}" maxlength="120" ${k==='date'?'type="date"':k==='amount'?'type="number" step=".01" min=".01"':''}></div>`).join('')}</div><div class="info">${t('Unknown fields may be left blank and are shown as missing. Saving does not create an income or expense.','未知字段可以留空并标为缺失。保存不会创建收入或支出。')}</div><button type="submit" class="btn primary">${t('Save reviewed fields','保存已核对信息')}</button></form></section>`;}
function weeklyPage(){const actions=weeklyActions(data),sectorTask=sectorTemplates[sector()].tasks;return `${pageHead('weekly',t('Three clear priorities, with the records behind them.','三项清晰优先事项，附相关记录。'))}<div class="info">${t(`Planning snapshot ${AS_OF}; this is a to-do plan, not automatic execution.`,`规划快照${AS_OF}；这是待办计划，不是自动执行。`)}</div><section class="card">${actions.length?actions.map(r=>`<div class="weeklycheck"><input type="checkbox" data-weekly="${r.id}" aria-label="${t('Mark task done','标记任务完成')}" ${data.weeklyDone?.includes(r.id)?'checked':''}><div><h3>${t(...riskText[r.id])}</h3><p>${riskDescription(r)}</p><p>${t('Relevant date','相关日期')}: ${date(r.date)} · ${money(r.amount)}</p><div class="evidence">${r.evidence.map(id=>`<button data-action="evidence" data-id="${esc(id)}">${esc(id)}</button>`).join('')}</div>${btn(t('Open action','打开行动'),'nav','',`data-page="${r.id==='overdue'?'collections':r.route}"`)}</div></div>`).join(''):`<div class="empty">${t('No unreviewed financial alerts. Check the suggestions below.','没有未核查财务提醒。请查看下方建议。')}</div>`}<p class="small muted" style="margin-top:14px">${t('Checking a task does not settle a bill or remove an underlying risk.','勾选任务不会结清账单或消除原有风险。')}</p></section><section class="card"><h2>${t('Your business routine','适合您的日常检查')}</h2><p class="small muted" style="margin-top:9px">${sectorName()}</p><ul class="list">${sectorTask.map((task,i)=>`<li>${lang==='zh'?({retail:['核查支付手续费与退款','跟进库存供应商账单'],restaurant:['核查食材采购','为工资与租金预留现金'],trading:['跟进客户承诺日期','核查供应商付款时间'],services:['跟进项目发票','招聘前核查薪酬预算']}[sector()][i]):task}</li>`).join('')}</ul>${btn(t('Export weekly plan','导出每周计划'),'exportweekly')}</section>`;}
function setupPage(){return `${pageHead('setup',t('A useful start in three small steps.','用三个小步骤开始。'))}<form id="sectorform"><section class="card"><h2><span class="setup-step">${t('Step 1/3','第1/3步')}</span> ${t('Choose your business type','选择业务类型')}</h2><div class="sectorgrid" style="margin-top:13px">${Object.entries(sectorTemplates).map(([k,v])=>`<label><input type="radio" name="sector" value="${k}" ${sector()===k?'checked':''}>${v[lang==='zh'?'zh':'en']}</label>`).join('')}</div></section><section class="card"><h2><span class="setup-step">${t('Step 2/3','第2/3步')}</span> ${t('Set your cash buffer','设置现金备用金')}</h2><div class="field" style="margin-top:13px"><label for="setupreserve">${t('Emergency cash buffer (CNY)','应急备用金（人民币）')}</label><input type="number" id="setupreserve" name="reserve" min="0" max="1000000" step=".01" required value="${data.settings.reserve/100}"></div></section><section class="card"><h2><span class="setup-step">${t('Step 3/3','第3/3步')}</span> ${t('Choose how to add records','选择添加记录的方式')}</h2><p class="small muted" style="margin:10px 0">${t('Your existing data stays intact. Start with a quick entry or upload a statement after saving.','现有数据保持不变。保存后可快捷录入或上传账单。')}</p><button type="submit" class="btn primary">${t('Save setup','保存设置')}</button></section></form>`;}
function legacyAccountPage(){const offline=globalThis.FINORA_OFFLINE||location.protocol==='file:';if(offline||aiStatus.accounts!==true)return `${pageHead('account',t('Secure accounts require the included server mode.','安全账号需要附带的服务器模式。'))}<section class="card"><h2>${t('You are in offline demo mode','您正在使用离线演示')}</h2><p class="small muted" style="margin:12px 0">${t('Your records stay in this browser. Open the ZIP instructions to run the account server with SQLite persistence, password hashing, owner/accountant/viewer roles and device sync. The HTML file does not pretend to authenticate users.','记录保留在当前浏览器。请按ZIP说明运行账号服务器，启用SQLite持久存储、密码哈希、企业主/会计/只读权限与设备同步。HTML文件不模拟真实认证。')}</p>${btn(t('Export a backup','导出备份'),'backup')}</section>`;
 if(!accountState.user)return `${pageHead('account',t('Sign in to save and sync across your devices.','登录后保存并在设备间同步。'))}<section class="card"><form id="authform"><div class="field"><label for="authemail">${t('Email','邮箱')}</label><input type="email" name="email" id="authemail" required autocomplete="username"></div><div class="field" style="margin-top:12px"><label for="authpassword">${t('Password · at least 12 characters','密码 · 至少12个字符')}</label><input type="password" name="password" id="authpassword" required minlength="12" maxlength="128" autocomplete="current-password"></div><div class="field" style="margin-top:12px"><label for="authmode">${t('Action','操作')}</label><select id="authmode" name="mode"><option value="login">${t('Sign in','登录')}</option><option value="register">${t('Create account','创建账号')}</option></select></div><div class="info">${t('New accounts receive their own isolated synthetic demo businesses. To access someone else’s business, the owner must explicitly grant access.','新账号拥有独立隔离的模拟企业。访问他人企业需要企业主明确授权。')}</div><button class="btn primary" type="submit">${t('Continue','继续')}</button></form>${aiStatus.identityMode==='supabase'?`<p style="margin-top:16px"><a class="btn" href="/reset-password?lang=${lang==='zh'?'zh':'en'}">${t('Forgot password?','忘记密码？')}</a></p>`:''}</section>`;
 return `${pageHead('account',t('Your records. Your permissions.','您的记录，您的权限。'))}<div class="accountstate">${esc(accountState.user.email)} · ${roleName(accountState.role)}<br>${syncLabel()}</div><section class="card"><h2>${t('Available businesses','可访问企业')}</h2><div class="chips" style="margin-top:12px">${accountState.businesses.map(b=>`<button data-action="switchworkspace" data-owner="${esc(b.owner)}" data-key="${esc(b.key)}">${profiles.find(p=>p.id===b.key)?.[lang==='zh'?'zh':'en']||b.key}<br>${esc(b.owner_email)} · ${roleName(b.role)}</button>`).join('')}</div><div class="quickactions">${btn(t('Sync now','立即同步'),'syncnow')}${btn(t('Load server copy','加载服务器版本'),'loadserver')}${btn(t('Sign out','退出登录'),'signout')}</div><p class="small muted">${t('Conflicts never silently overwrite another device. Export your local backup before replacing an unsynced copy.','冲突不会静默覆盖另一设备。替换未同步版本前，请导出本地备份。')}</p></section><section class="card"><h2>${t('Accountant & viewer access','会计与只读访问')}</h2><p class="small muted" style="margin:10px 0">${t('Grant access by the verified sign-in email. No invitation email is sent. Accountant can edit this business; viewer can read only.','对方先创建自己的账号。不发送邀请邮件。会计可编辑当前企业；只读用户只能查看。')}</p>${accountState.role==='owner'?`<form id="memberform"><div class="field"><label for="memberemail">${t('Existing account email','现有账号邮箱')}</label><input id="memberemail" name="email" type="email" required></div><div class="field" style="margin:12px 0"><label for="memberrole">${t('Permission','权限')}</label><select id="memberrole" name="role"><option value="viewer">${t('Viewer · read only','只读用户')}</option><option value="accountant">${t('Accountant · may edit','会计 · 可编辑')}</option></select></div><button type="submit" class="btn primary">${t('Review access grant','核对授权')}</button></form><div class="quickactions">${btn(t('View current members','查看当前成员'),'showmembers')}</div>`:`<p class="small muted">${t('Only the owner can change permissions.','只有企业主可以更改权限。')}</p>`}</section>`;}
const roleName=r=>t({owner:'Owner',accountant:'Accountant',viewer:'Viewer'}[r]||r,{owner:'企业主',accountant:'会计',viewer:'只读用户'}[r]||r);
function syncLabel(){return t({offline:'Offline demo',pending:'Local changes waiting to sync',syncing:'Syncing…',synced:'Saved to server',error:'Sync failed: local copy retained',conflict:'Conflict: local copy retained; review server data'}[accountState.sync],{offline:'离线演示',pending:'本地变更等待同步',syncing:'正在同步…',synced:'已保存至服务器',error:'同步失败：保留本地版本',conflict:'冲突：保留本地版本，请核查服务器数据'}[accountState.sync]);}
function apiPath(route){return route+'?owner='+encodeURIComponent(accountState.activeOwner||accountState.user?.id||'')+'&key='+encodeURIComponent(org);}
async function accountAPI(route,method='GET',body=null){const response=await fetch(route,{method,credentials:'same-origin',headers:{'content-type':'application/json',...(method!=='GET'?{'x-csrf-token':accountState.csrf||cloudIdentity?.csrf||''}:{})},...(body?{body:JSON.stringify(body)}:{})});const payload=await response.json();if(!response.ok){const error=Error(payload.error||'Request failed');error.status=response.status;throw error;}return payload;}
function markSync(){if(!accountState.user||accountState.role==='viewer')return;accountState.sync='pending';clearTimeout(syncTimer);syncTimer=setTimeout(syncData,250);}
let syncBusy=false,syncWaiters=[];
async function syncData(){if(!accountState.user||accountState.role==='viewer')return;if(syncBusy)return new Promise(resolve=>syncWaiters.push(resolve));syncBusy=true;const owner=accountState.activeOwner,key=org,snapshot=structuredClone(data),revision=accountState.revision;try{localStorage.setItem('finora-cloud-recovery-'+accountState.user.id+'-'+owner+'-'+key,JSON.stringify(snapshot));}catch{}accountState.sync='syncing';try{const result=await accountAPI(apiPath('/api/business'),'PUT',{data:snapshot,revision});if(owner===accountState.activeOwner&&key===org){accountState.revision=result.revision;accountState.sync=JSON.stringify(data)===JSON.stringify(snapshot)?'synced':'pending';}}catch(e){accountState.sync=e.status===409?'conflict':'error';toast(t('Sync did not save. Your local data is retained; open Account to resolve it.','同步未保存。本地数据已保留；请打开账号页面处理。'));}finally{syncBusy=false;for(const resolve of syncWaiters)resolve();syncWaiters=[];if(accountState.sync==='pending')markSync();if(page==='account')render();}}
async function switchBusiness(key,owner=accountState.activeOwner,force=false){pdfDraft=null;pdfEpoch++;collectionSearch='';if(!force&&accountState.user){for(let n=0;n<3&&['pending','syncing'].includes(accountState.sync);n++)await syncData();if(['pending','syncing','error','conflict'].includes(accountState.sync)){toast(t('Resolve unsynced changes or export a backup before switching businesses.','切换企业前，请处理未同步变更或导出备份。'));return;}}try{const result=await accountAPI('/api/business?owner='+encodeURIComponent(owner)+'&key='+encodeURIComponent(key));validateData(result.data);org=key;data=result.data;statementPreview=null;importPreview=null;invoiceDraft=null;rescueResult=null;accountState.activeOwner=owner;accountState.revision=result.revision;accountState.role=result.role;accountState.sync='synced';localStorage.setItem('finora-org',org);closeModal();render();}catch{toast(t('Unable to load this business. Your current records remain visible.','无法加载该企业。当前记录仍可查看。'));}}
const originalMobileRender=render;
render=function(){originalMobileRender();if(accountState.user){const select=$('#business');if(select)select.innerHTML=accountState.businesses.filter(b=>b.owner===accountState.activeOwner).map(b=>`<option value="${esc(b.key)}" ${b.key===org?'selected':''}>${esc(profiles.find(p=>p.id===b.key)?.[lang==='zh'?'zh':'en']||b.key)}</option>`).join('');}};
function guardWrites(e){if(!accountState.user||accountState.role!=='viewer')return;const action=e.target.closest?.('[data-action]')?.dataset.action;if(e.type==='submit'&&!['chatform','authform','rescueform'].includes(e.target.id)||['editbuffer','pdfpost','quickincome','quickexpense','quickundo','newinvoice','editinvoice','settlement','review','reset','commitimport','savestatement','manualdocument','collectionnote','collectiondraftsave','matchdocument','confirm','saveplan','planstatus','reviewrow','restorebackup','cloudinitialize','cloudlocal','saverescue'].includes(action)||e.type==='change'&&(e.target.id==='invoicefile'||e.target.id==='restorebackup'||e.target.dataset.weekly||e.target.dataset.checklist)){e.preventDefault();e.stopImmediatePropagation();toast(t('This account has read-only access. Ask the owner for accountant permissions.','此账号为只读权限。请向企业主申请会计权限。'));}}
document.addEventListener('click',guardWrites,true);document.addEventListener('submit',guardWrites,true);document.addEventListener('change',guardWrites,true);
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='safedetail'){showSafeDetails();}
 if(action==='importsource'){importSource=el.dataset.source;statementPreview=null;render();}
 if(action==='statementtemplate'){const templates={wechat:'交易时间,微信订单号,商品名称,交易状态,总金额,手续费\n2026-10-12 10:00:00,WX-1001,门店销售,SUCCESS,200.00,1.20\n',alipay:'交易时间,交易号,交易对方,收/支,金额,交易状态\n2026-10-12 10:00:00,ALI-1001,客户A,收入,200.00,交易成功\n',bank:'日期,流水号,对方户名,收入金额,支出金额\n2026-10-12,BANK-1001,客户A,200.00,0\n',generic:'id,date,type,category,party,amount\nCSV-1001,2026-10-12,income,sales,Customer,200.00\n'};download('Finora-'+importSource+'-template.csv','\uFEFF'+templates[importSource],'text/csv');}
 if(action==='savestatement'&&statementPreview){const preview=statementPreview;confirm(t('Save this reconciliation batch?','保存此对账批次？'),`<p>${t('Accepted entries change cash. Pending rows remain in a persistent review queue. No bank verification is claimed.','已接受记录改变现金。待核查行保留在对账队列，不代表银行验证。')}</p>`,()=>{try{if(commitQuick(commitReconciliation(data,preview))){statementPreview=null;go('reconcile');}}catch{toast(t('Import failed. Preview the statement again.','导入失败，请重新预览。'));}});return;}
 if(action==='collectionnote'){const i=data.invoices.find(i=>i.id===el.dataset.id);modal(t('Record customer follow-up','记录客户跟进'),`<form id="collectionform" data-id="${esc(i.id)}"><p>${esc(party(i))} · ${money(outstanding(i),2)}</p><div class="field" style="margin-top:15px"><label for="promiseddate">${t('Promised payment date','承诺付款日期')}</label><input id="promiseddate" name="promisedDate" type="date" required value="${data.collectionNotes?.[i.id]?.promisedDate||i.expected}"></div><div class="field" style="margin-top:12px"><label for="collectionnote">${t('Follow-up note','跟进备注')}</label><textarea id="collectionnote" name="note" maxlength="300">${esc(data.collectionNotes?.[i.id]?.note||'')}</textarea></div><div class="info">${t('A promised date updates the forecast, not the paid amount.','承诺日期更新预测，不更改已付金额。')}</div><button type="submit" class="btn primary">${t('Review update','核对更新')}</button></form>`,' ');}
 if(action==='copyreminder'){const i=data.invoices.find(i=>i.id===el.dataset.id&&i.kind==='receivable');if(i)showCollectionReminder(i);}
 if(action==='copydraft'){try{await navigator.clipboard.writeText($('#remindercopy').value);toast(t('Draft copied. Nothing sent.','草稿已复制，未发送。'));}catch{$('#remindercopy').select();toast(t('Select and copy the draft manually.','请选中并手动复制草稿。'));}}
 if(action==='manualdocument'){invoiceDraft={name:t('Manual invoice details','手动发票信息'),verified:false};render();}
 if(action==='matchdocument'){const d=(data.documents||[]).find(x=>x.id===el.dataset.id);modal(t('Match supporting record','匹配支持记录'),`<form id="matchform" data-id="${esc(d.id)}"><div class="field"><label for="matchedrecord">${t('Invoice or cash transaction','发票或现金记录')}</label><select name="linkedId" id="matchedrecord"><option value="">${t('No match','未匹配')}</option>${data.invoices.map(i=>`<option value="${esc(i.id)}">${esc(i.id)} · ${money(i.total)}</option>`).join('')}${data.transactions.filter(t=>!t.voidedAt).slice(-100).map(x=>`<option value="${esc(x.id)}">${esc(x.id)} · ${money(x.amount)}</option>`).join('')}</select></div><button class="btn primary" type="submit" style="margin-top:15px">${t('Save match','保存匹配')}</button></form>`,' ');}
 if(action==='downloaddocument'){const url=apiPath('/api/document/'+encodeURIComponent(el.dataset.id));const a=document.createElement('a');a.href=url;a.download='invoice-document';a.click();}
 if(action==='exportweekly'){download('Finora-weekly-plan.txt',`${businessName()} · ${AS_OF}\n\n`+weeklyActions(data).map(r=>t(...riskText[r.id])+'\n'+riskDescription(r)+'\n'+r.evidence.join(', ')).join('\n\n'));}
 if(action==='syncnow')await syncData();
 if(action==='loadserver'){confirm(t('Load server records?','加载服务器记录？'),`<p>${t('This replaces the visible local copy. Export a backup first if you have unsynced changes.','这将替换可见的本地版本。如有未同步变更，请先导出备份。')}</p>`,()=>switchBusiness(org,accountState.activeOwner,true));}
 if(action==='switchworkspace')await switchBusiness(el.dataset.key,el.dataset.owner);
 if(action==='signout'){const keepGuestRecords=!accountState.user;for(let n=0;n<3&&['pending','syncing'].includes(accountState.sync);n++)await syncData();if(['pending','syncing','error','conflict'].includes(accountState.sync)){toast(t('Unsynced changes remain. Export a backup and resolve the conflict before signing out.','仍有未同步变更。退出前请导出备份并处理冲突。'));return;}if(aiStatus.identityMode==='chatgpt'){location.href='/signout-with-chatgpt?return_to=%2F';return;}try{await accountAPI('/api/logout','POST');cloudIdentity=null;aiStatus.authenticated=false;liveRequested=false;accountState={user:null,csrf:null,businesses:[],activeOwner:null,revision:null,role:'owner',sync:'offline'};if(!keepGuestRecords){org='shenzhen';data=seed(org);}render();}catch{toast(t('Unable to sign out; try again.','无法退出，请重试。'));}}
 if(action==='showmembers'){try{const result=await accountAPI(apiPath('/api/members'));modal(t('Business access','企业访问权限'),result.members.map(m=>`<div class="documentrow">${esc(m.email)} · ${roleName(m.role)} ${m.role==='owner'?'':btn(t('Remove access','移除访问'),'revokemember','danger',`data-email="${esc(m.email)}"`)}</div>`).join(''));}catch{toast(t('Unable to load members.','无法加载成员。'));}}
 if(action==='revokemember'){const email=el.dataset.email;confirm(t('Remove this account’s access?','移除此账号的访问？'),`<p>${esc(email)}</p>`,async()=>{try{await accountAPI(apiPath('/api/members'),'DELETE',{email});toast(t('Access removed.','访问已移除。'));}catch{toast(t('Unable to remove access.','无法移除访问。'));}});}
});
document.addEventListener('change',async e=>{const el=e.target;
 if(el.id==='statementfile'){const file=el.files[0];if(!file)return;try{if(file.size>1000000||!file.name.toLowerCase().endsWith('.csv'))throw Error('file');const targetOrg=org,bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);if(text.includes('�'))text=new TextDecoder('gb18030').decode(bytes);if(org!==targetOrg)return;statementPreview=reconcileStatement(text,data,importSource);statementPreview.skipped=statementPreview.review;for(const r of statementPreview.records)if(r.date<=data.openingDate)statementPreview.errors.push({line:r.sourceRow,reason:'before_opening'});render();}catch{toast(t('Unsupported CSV format. Use the source template and check the file size.','不支持的CSV格式。请使用来源模板并核查文件大小。'));}}
 if(el.id==='invoicefile'){const file=el.files[0];if(!file)return;try{if(file.size>2000000)throw Error('limit');if(file.name.toLowerCase().endsWith('.txt')){const text=await file.text();invoiceDraft={...parseInvoiceText(text),name:file.name};}else if(accountState.user&&aiStatus.identityMode==='password'){toast(t('Extracting document; review all fields afterwards.','正在提取文件，完成后请核对所有字段。'));const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);const result=await accountAPI(apiPath('/api/documents/extract'),'POST',{name:file.name,mime:file.type,base64:btoa(binary)});invoiceDraft={...result.fields,name:result.name,serverId:result.id,warning:result.warning?t('Extraction incomplete. Review manually; Chinese OCR needs installed language data.','提取不完整，请手动核对；中文OCR需要安装语言数据。'):null};}else{invoiceDraft={name:file.name,warning:t('This deployment cannot extract or store this PDF/image. Enter its fields below; the original is not uploaded.','此部署无法提取或保存PDF/图片。请手动填写字段，原件不会上传。')};}render();}catch{toast(t('Document unavailable. Check type, size or account connection; manual entry is available.','文件不可用。请核查类型、大小或账号连接，也可手动录入。'));}}
 if(el.dataset.weekly){const id=el.dataset.weekly;data.weeklyDone=el.checked?[...new Set([...(data.weeklyDone||[]),id])]:(data.weeklyDone||[]).filter(x=>x!==id);save();}
});
document.addEventListener('submit',async e=>{const form=e.target;
 if(form.id==='collectionform'){e.preventDefault();const v=Object.fromEntries(new FormData(form)),id=form.dataset.id;try{const next=saveCollectionNote(data,id,v.note,v.promisedDate);confirm(t('Update expected collection date?','更新预计回款日期？'),`<p>${esc(id)} · ${esc(v.promisedDate)}</p>`,()=>{if(commitQuick(next))toast(t('Follow-up saved; forecast updated.','跟进已保存，预测已更新。'));});}catch{toast(t('Check the promised date and note.','请核查承诺日期与备注。'));}}
 if(form.id==='documentform'){e.preventDefault();const v=Object.fromEntries(new FormData(form));try{if(v.amount)moneyInput(v.amount);if(v.date&&(!Number.isFinite(Date.parse(v.date))||new Date(v.date).toISOString().slice(0,10)!==v.date))throw Error('date');const next=structuredClone(data);next.documents=[...(next.documents||[]),{...invoiceDraft,...v,id:crypto.randomUUID(),verified:false,linkedId:''}];next.audit.unshift({date:new Date().toISOString(),action:'document_saved',record:v.number||invoiceDraft.name});if(commitQuick(next)){invoiceDraft=null;render();toast(t('Reviewed fields saved; not officially verified.','核对字段已保存，尚未官方查验。'));}}catch{toast(t('Enter a valid date and positive amount, or leave unknown fields blank.','请输入有效日期与正金额，未知字段可留空。'));}}
 if(form.id==='matchform'){e.preventDefault();const id=form.dataset.id,linkedId=new FormData(form).get('linkedId');if(linkedId&&!data.invoices.some(i=>i.id===linkedId)&&!data.transactions.some(t=>t.id===linkedId))return;const next=structuredClone(data);next.documents.find(d=>d.id===id).linkedId=linkedId;next.audit.unshift({date:new Date().toISOString(),action:'document_matched',record:id});if(commitQuick(next)){closeModal();toast(t('Document linked. No cash entry created.','文件已关联，未创建现金记录。'));}}
 if(form.id==='sectorform'){e.preventDefault();const v=Object.fromEntries(new FormData(form));if(!sectorTemplates[v.sector]||!Number.isFinite(+v.reserve)||+v.reserve<0)return;const next=structuredClone(data);next.settings={...next.settings,sector:v.sector,reserve:Math.round(+v.reserve*100),onboarded:true};next.audit.unshift({date:new Date().toISOString(),action:'sector_setup',record:v.sector});if(commitQuick(next)){go('overview');toast(t('Business setup saved.','企业设置已保存。'));}}
 if(form.id==='authform'){e.preventDefault();const v=Object.fromEntries(new FormData(form));try{const result=await accountAPI('/api/'+v.mode,'POST',{email:v.email,password:v.password});if(result.confirmationRequired){toast(t('Check your email and confirm your address, then sign in.','请查收邮件并确认邮箱，然后登录。'));return;}if(aiStatus.identityMode==='supabase'){cloudIdentity=result;aiStatus.authenticated=true;render();toast(t('Signed in. Export a browser backup before opening cloud workspaces.','已登录。打开云工作区前，请先导出浏览器备份。'));return;}accountState={...accountState,user:result.user,csrf:result.csrf,businesses:result.businesses,activeOwner:result.user.id};await switchBusiness('shenzhen',result.user.id);toast(t('Signed in. Server records loaded.','已登录，服务器记录已加载。'));}catch{toast(t('Sign-in failed. Check account details, server mode and password length.','登录失败。请核查账号信息、服务器模式与密码长度。'));}}
 if(form.id==='memberform'){e.preventDefault();const v=Object.fromEntries(new FormData(form));confirm(t('Grant access to this business?','授权访问当前企业？'),`<p>${esc(v.email)} · ${roleName(v.role)}</p><div class="info">${t('This person can read financial records. Accountant access also allows editing. No invitation message will be sent.','此人可以读取财务记录。会计权限还可编辑。不发送邀请消息。')}</div>`,async()=>{try{await accountAPI(apiPath('/api/members'),'POST',v);toast(t('Permission saved.','权限已保存。'));}catch{toast(t('Unable to grant access. The person must register first.','无法授权，对方需先注册。'));}});}
});
const sectorQuickForm=quickForm;
quickForm=function(type){sectorQuickForm(type);const field=$('#quickcategory');const categories=type==='income'?['sales','other']:[...new Set(['other',...sectorTemplates[sector()].categories.filter(c=>c!=='sales'),'operations'])];if(field)field.innerHTML=categories.map(c=>`<option value="${c}">${catLabel(c)}</option>`).join('');};
const touchChart=chart;
chart=function(...args){return touchChart(...args)+`<p class="small muted">${t('Tap a chart point to read its date and amount.','轻点图表数据点，查看日期与金额。')}</p>`;};
document.addEventListener('click',e=>{const point=e.target.closest?.('circle[aria-label]');if(point)toast(point.getAttribute('aria-label'));});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches?.('circle[aria-label]'))toast(e.target.getAttribute('aria-label'));});
render();

function aiSetupPage(){return `${pageHead('ai',t('Business questions, verified calculations, clear decisions.','经营问题、可靠计算、清晰决策。'))}<section class="card"><h2>${t('Connection status','连接状态')}</h2><div class="info">${aiStatus.mode==='configured'?t('Provider configured. A successful response is required to verify live AI.','已配置服务。成功返回后才能确认实时AI。'):t('Live LLM is not configured. Calculated business analysis works now.','尚未配置实时大模型。当前可使用计算型业务分析。')}</div>${aiHealth?`<div class="info" role="status">${aiHealth.ok?t('Verified: Gemini completed tool selection and explanation.','已验证：Gemini完成工具选择与解释。'):esc(aiFailureText(aiHealth.reason))}</div>`:''}<p class="small muted">${t('Guest records stay in this browser. Signed-in cloud workspaces sync to protected storage. Live AI requires separate consent.','访客记录保留在浏览器；登录后的云工作区同步到受保护存储。实时AI需要另行授权。')}</p><div class="quickactions">${btn(t('Check configuration','检查配置'),'checkai')}${btn(t('Test live answer','测试实时回答'),'testai','',!liveRequested||!aiStatus.authenticated?'disabled':'')}${btn(t('Open assistant','打开助手'),'opencopilot','primary')}</div>${aiStatus.mode==='configured'&&!aiStatus.authenticated?`<a class="btn" href="${aiStatus.identityMode==='supabase'?'/#account':'/signin-with-chatgpt?return_to=%2F%23ai'}" ${aiStatus.identityMode==='supabase'?'data-action="nav" data-page="account"':''} target="_top">${aiStatus.identityMode==='supabase'?t('Sign in for live AI','登录以使用实时AI'):t('Sign in with ChatGPT for live AI','使用ChatGPT登录以使用实时AI')}</a>`:''}<label class="checkbox"><input id="liveconsent" type="checkbox" ${liveRequested?'checked':''} ${aiStatus.mode!=='configured'||!aiStatus.authenticated?'disabled':''}>${t('Use live LLM: send my question, up to four previous questions, reviewed assumptions and calculated results to the configured provider. Do not include private names in questions.','使用实时大模型：向已配置服务发送当前问题、最多四条历史问题、已核对假设与计算结果。问题中请勿包含隐私姓名。')}</label><p class="small muted">${t('Live calls require sign-in. Test live answer uses a synthetic business example and two Gemini calls. Normal questions have a best-effort limit of ten per hour; connection tests allow five. Failures are shown with a reason.','实时请求需要登录。每位登录访客每小时最多十次（尽力限制）。服务失败时明确回退至计算引擎。')}</p></section><section class="card"><h2>${t('Review a what-if scenario','核对模拟情景')}</h2><p class="small muted" style="margin:10px 0">${t('These values come from Cash. Edit the scenario there, then explicitly include it with your next question. No ledger changes.','这些数值来自现金页面。在那里修改情景，然后明确加入下一次问题。不修改账本。')}</p><div class="numbers">${[['days',t('Days','天数'),''],['growth',t('New sales change','新增销售变化'),'%'],['delay',t('Collection delay','回款延迟'),t(' days','天')],['expense',t('Operating cost increase','运营成本增加'),'%'],['supplierDelay',t('Supplier delay','供应商延期'),t(' days','天')]].map(([k,n,u])=>`<div><span>${n}</span><strong>${scenario[k]}${u}</strong></div>`).join('')}<div><span>${t('Additional monthly payroll','每月新增薪酬')}</span><strong>${money(scenario.hiring)}</strong></div><div><span>${t('One-time cost','一次性支出')}</span><strong>${money(scenario.oneOff)}</strong></div></div><label class="checkbox"><input id="reviewedscenario" type="checkbox" ${useReviewedScenario?'checked':''}>${t('Include these reviewed assumptions with my questions','提问时加入这些已核对假设')}</label>${btn(t('Edit cash scenario','修改现金情景'),'nav','', 'data-page="cash"')}</section><section class="card"><h2>${t('Try a business decision','尝试经营决策')}</h2><div class="chips" style="margin-top:12px">${[t('Compare collections, supplier timing and loan options','比较催收、供应商时间与贷款方案'),t('Investigate expenses','核查支出'),t('How much working capital do I need?','我需要多少营运资金？'),t('Will I have enough cash?','我的现金足够吗？')].map(q=>btn(q,'businessquestion','',`data-question="${esc(q)}"`)).join('')}</div><ol class="list"><li>${t('Ask a question and review missing inputs.','提出问题并核查缺失信息。')}</li><li>${t('The LLM selects an allowed read-only financial tool.','大模型选择允许的只读财务工具。')}</li><li>${t('The engine validates records and calculates exact values in fen.','引擎核查记录并以分计算金额。')}</li><li>${t('Check evidence, assumptions and uncertainty before evaluating an action.','评估行动前检查证据、假设与不确定性。')}</li></ol></section><section class="card"><h2>${t('Owner activation checklist','企业主启用清单')}</h2><p style="margin:10px 0">${t('The owner must configure a provider account with API billing, a tool-calling model and server-only credentials. This page cannot collect or reveal API keys.','企业主需配置有API计费的服务账号、支持工具调用的模型与仅服务器可用的凭证。本页不收集或显示API密钥。')}</p><p class="small muted">${t('Deployment variables: LLM_API_KEY (secret), LLM_ENDPOINT (HTTPS Chat Completions URL), LLM_MODEL. Configured credentials stay on the server. Use Test live answer to verify the full connection.','部署变量：LLM_API_KEY（密钥）、LLM_ENDPOINT（HTTPS Chat Completions地址）、LLM_MODEL。已配置凭证保留在服务器，请测试实时回答以验证完整连接。')}</p><div class="info">${t('No automatic payments, invoice edits, loan applications or message sending. A proposed action always opens a review workspace.','不自动付款、修改发票、申请贷款或发送消息。建议行动始终打开核查工作区。')}</div></section>`;}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='reviewaiscenario'){try{const proposed=JSON.parse(el.dataset.scenario);forecast(data,proposed);scenario={days:30,growth:0,delay:0,expense:0,hiring:0,supplierDelay:0,oneOff:0,...proposed};useReviewedScenario=false;go('ai');toast(t('Review these values and tick Include before asking again.','请核对数值，勾选加入假设后再提问。'));}catch{toast(t('Invalid proposed scenario.','提议情景无效。'));}}if(el.dataset.action==='businessquestion'){go('copilot');ask(el.dataset.question);}if(el.dataset.action==='testai'){if(!liveRequested||!aiStatus.authenticated)return;el.disabled=true;el.textContent=t('Testing Gemini…','正在测试Gemini…');try{const r=await fetch('/api/check-ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({consent:true,lang})});if(!r.ok)throw Error();aiHealth=await r.json();}catch{aiHealth={ok:false,reason:'provider_error'};}render();}if(el.dataset.action==='checkai'){try{const r=await fetch('/api/status');if(!r.ok)throw Error();aiStatus=await r.json();providerMode=aiStatus.mode==='configured'?'configured':'demo';render();toast(t('Connection status updated.','连接状态已更新。'));}catch{toast(t('Status unavailable. Engine analysis remains available.','状态不可用，计算分析仍可用。'));}}});
document.addEventListener('change',e=>{if(e.target.id==='liveconsent'){liveRequested=!!(e.target.checked&&aiStatus.mode==='configured'&&aiStatus.authenticated);refreshAIControls();}if(e.target.id==='reviewedscenario')useReviewedScenario=e.target.checked;});

function aiFailureText(reason){return t({provider_busy:'Gemini is temporarily busy. Your calculations are available; retry later.',provider_quota:'Gemini quota or billing limit reached. Check the provider account.',provider_auth:'Gemini rejected the server API credential.',provider_model_not_found:'The configured Gemini model is unavailable.',provider_request_invalid:'Gemini rejected the API request format. The connection needs repair.',sign_in_required:'Sign in with ChatGPT before using live AI.',hourly_limit:'Live-AI request limit reached. Try again next hour.',not_configured:'The server provider configuration is incomplete.',tool:'Gemini did not return the required financial tool call.',arguments:'Gemini returned invalid tool inputs; no action was performed.','unverified prose':'Gemini output failed financial verification. Showing calculated results.',model_output_invalid:'Gemini returned an incomplete answer.',provider_error:'Gemini could not complete this request. Use Test live answer to check the connection.'}[reason]||'Live AI is unavailable.',{provider_busy:'Gemini暂时繁忙，请稍后重试。计算结果仍可查看。',provider_quota:'Gemini额度或计费限制，请核查服务账号。',provider_auth:'Gemini拒绝服务器API凭证。',provider_model_not_found:'配置的Gemini模型不可用。',provider_request_invalid:'Gemini拒绝API请求格式，需要修复连接。',sign_in_required:'使用实时AI前请登录ChatGPT。',hourly_limit:'实时AI请求已达上限，请下一小时重试。',not_configured:'服务器模型配置不完整。',tool:'Gemini未返回所需财务工具调用。',arguments:'Gemini工具输入无效，未执行行动。','unverified prose':'Gemini输出未通过财务核查，显示计算结果。',model_output_invalid:'Gemini返回不完整回答。',provider_error:'Gemini未完成请求，请使用测试实时回答检查连接。'}[reason]||'实时AI不可用。');}

// Topic E: review → decide → confirm. A plan status never posts a cash transaction.


const readinessReason=r=>t({own_transfer:'Transfer between your own accounts: exclude from consolidated income',refund:'Refund: confirm direction before posting',possible_duplicate:'Same date, party, direction and amount: check both sources',unclear:'Unclear direction: inspect the source statement'}[r]||r,{own_transfer:'本人账户间转账：不计入合并收入',refund:'退款：入账前确认方向',possible_duplicate:'日期、交易方、方向与金额相同：核查来源',unclear:'收支方向不明：核查原始账单'}[r]||r);
function reconcilePage(){const batches=data.importBatches||[];return `${pageHead('reconcile',t('Resolve exceptions without counting money twice.','核查异常，避免重复计算。'))}<section class="card"><p>${t('Own-account transfers should be excluded only when both accounts are included in this combined ledger. Refunds affect Money received or Money spent, but do not enter the new-sales forecast. Unresolved rows make reports incomplete.','仅当两个账户均包含在合并账本时，才排除内部转账。退款影响收款或支出，但不计入新销售预测。待核查行会导致报表不完整。')}</p>${btn(t('Import another statement','导入其他账单'),'nav','primary','data-page="imports"')}</section>${batches.map(b=>`<section class="card"><h2>${esc(b.source)} · ${esc(b.createdAt.slice(0,10))}</h2><p class="small muted">${b.accepted} ${t('accepted','已接受')} · ${b.duplicates} ${t('duplicate IDs skipped','重复ID已跳过')} · ${b.review.filter(r=>r.state==='pending').length} ${t('pending','待核查')}</p>${b.review.map(r=>`<div class="documentrow"><strong>${esc(r.party)} · ${money(r.amount,2)}</strong><p>${esc(r.date)} · ${esc(r.sourceTransactionId)}</p><p>${esc(readinessReason(r.reason))}</p><p class="small muted">${esc(r.description||'')}</p>${r.state==='pending'?btn(t('Review decision','核查处理'),'reviewrow','',`data-batch="${esc(b.id)}" data-id="${esc(r.id)}"`):badge(esc(r.state),'gray')}</div>`).join('')||`<p>${t('No review exceptions.','无待核查异常。')}</p>`}</section>`).join('')||`<section class="card">${t('No statement batches yet. Import a CSV to begin.','尚无对账批次，请导入CSV。')}</section>`}`;}
function actionPlanPage(){const tasks=data.actionPlan||[],proposed=suggestPlan(data);return `${pageHead('actionplan',t('Agree a next step, track it, then record settlement separately.','制定下一步并跟踪，结算需单独记录。'))}<div class="info">${t('Topic E · SME Finance Copilot. Task status never changes cash, invoices or expected dates. Promised dates must be recorded in Collections.','赛题E · 中小企业财务助手。任务状态不会改变现金、发票或预计日期；承诺日期请在催收页面记录。')}</div><section class="card"><h2>${t('Suggested priorities','建议优先事项')}</h2>${proposed.map(x=>`<div class="documentrow"><h3>${t(x.title,x.titleZh)}</h3><p>${esc(x.source)} · ${money(x.amount,2)} · ${date(x.due)}</p><p class="small muted">${t('Potential amount affected; not guaranteed cash received.','可能涉及金额，不保证实际到账。')}</p>${btn(t('Save to plan','加入计划'),'saveplan','',`data-id="${esc(x.source)}" data-kind="${x.kind}"`)} ${btn(t('Evidence','查看凭证'),'evidence','',`data-id="${esc(x.source)}"`)}</div>`).join('')}</section><section class="card"><h2>${t('Saved plan','已保存计划')}</h2>${tasks.map(x=>`<div class="documentrow"><h3>${t(x.title,x.titleZh)}</h3><p>${esc(x.source)} · ${money(x.amount,2)} · ${esc(x.owner)} · ${date(x.due)}</p><p>${esc(x.note)}</p>${badge(t(({planned:'Planned',contacted:'Contacted',agreed:'Agreed',cancelled:'Cancelled'})[x.status],({planned:'计划中',contacted:'已联系',agreed:'已达成约定',cancelled:'已取消'})[x.status]),'gray')}<div class="quickactions">${btn(t('Update task','更新任务'),'planstatus','',`data-id="${esc(x.id)}"`)}${btn(t('Open record','打开记录'),'evidence','',`data-id="${esc(x.source)}"`)}</div></div>`).join('')||`<p>${t('Save a priority above.','请添加上方建议。')}</p>`}${btn(t('Export plan & evidence','导出计划与证据'),'exportplan')} ${btn(t('Compare financial impact','比较财务影响'),'nav','','data-page="options"')}</section>`;}
function qualityPage(){const q=forecastQuality(data);return `${pageHead('quality',t('Understand what supports the forecast, and what could change.','了解预测依据，以及可能的变化。'))}<section class="card"><h2>${t('Data coverage','数据覆盖')}</h2><div class="numbers"><div>${t('Snapshot','快照')}: ${q.snapshot}</div><div>${t('History coverage (calendar days, not completeness)','历史跨度（日历天，不代表完整性）')}: ${q.historyDays}</div><div>${t('Posted records','已记录交易')}: ${q.recordCount}</div><div>${t('Unresolved statement rows','待核查账单行')}: ${q.unresolved}</div><div>${t('Outstanding customer payments, timing unverified','待收客户款项，时间未经核实')}: ${q.unconfirmedCollections}</div><div>${t('Latest import','最近导入')}: ${q.lastImport?esc(q.lastImport.slice(0,10)):t('None','无')}</div></div><p class="small muted">${t('This is a synthetic fixed-date snapshot. No calibrated probability or prediction-accuracy percentage is claimed. Customer promises can fail.','这是固定日期模拟快照，不提供未经校准的概率或准确率。客户可能无法兑现承诺。')}</p>${btn(t('Resolve import exceptions','处理导入异常'),'nav','','data-page="reconcile"')}</section><section class="card"><h2>${t('Same records, different assumptions','相同记录，不同假设')}</h2>${q.scenarios.map(x=>`<div class="documentrow"><strong>${t({expected:'Expected collections',delayed:'Collections seven days late',lower_sales:'New sales fifteen percent lower'}[x.key],{expected:'按预计回款',delayed:'回款延迟七天',lower_sales:'新销售下降百分之十五'}[x.key])}</strong><p>${t('Lowest balance','最低余额')}: ${money(x.min.cash,2)} · ${date(x.min.date)}</p><p>${t('Gap including buffer','含备用金缺口')}: ${money(x.need,2)}</p></div>`).join('')}<p class="small muted">${t('Scenarios are separate stress tests, not probabilities. Existing invoice amounts stay unchanged.','情景是独立压力测试，不代表概率。现有发票金额保持不变。')}</p></section><section class="card"><h2>${t('Document checks','凭证核查')}</h2>${(data.documents||[]).map(d=>{const m=matchEvidence(data,d);return `<div class="documentrow"><strong>${esc(d.number||d.name)}</strong><p>${esc(m.status)}</p>${m.reasons.map(r=>`<p class="small muted">${esc(r)}</p>`).join('')}</div>`;}).join('')||`<p>${t('No document fields to compare yet.','尚无可比对凭证。')}</p>`}<p>${t('Field matching is not official fapiao verification.','字段匹配不代表发票官方查验。')}</p></section>`;}
const preReadinessImport=importPage;
importPage=function(){return preReadinessImport()+`<section class="card"><h2>${t('Persistent reconciliation','持续对账核查')}</h2><p>${t('After import, refunds, possible cross-source duplicates and own-account transfers stay in Review until resolved.','导入后，退款、跨来源疑似重复与内部转账将保留在核查队列。')}</p>${btn(t('Open review queue','打开核查队列'),'nav','','data-page="reconcile"')}${btn(t('Download reconciliation demo CSV','下载对账演示CSV'),'reconciledemo')}</section>`;};
const preReadinessDashboard=dashboard;
dashboard=function(){return preReadinessDashboard()+`<section class="card"><h2>${t('From records to decisions','从记录到决策')}</h2><div class="quickactions">${btn(t('Find a cash rescue plan','寻找现金纾困方案'),'nav','primary','data-page="rescue"')}${btn(t('Cash action plan','现金行动计划'),'nav','','data-page="actionplan"')}${btn(t('Forecast evidence','预测依据'),'nav','','data-page="quality"')}${btn(t('Reconciliation review','对账核查'),'nav','','data-page="reconcile"')}</div><p class="small muted">${t('No autonomous payments, borrowing or message sending.','不自动付款、借款或发送消息。')}</p></section>`;};
async function loadCloudIdentity(){if(!aiStatus.accounts||globalThis.FINORA_OFFLINE)return;try{cloudIdentity=await accountAPI('/api/session');if(page==='account')render();}catch{cloudIdentity=null;}}
function accountPage(){if(aiStatus.identityMode==='password'||aiStatus.identityMode==='supabase'&&!cloudIdentity?.user)return legacyAccountPage();if(!aiStatus.accounts)return `${pageHead('account',t('Browser-local demo','浏览器本地演示'))}<section class="card"><p>${t('Cloud storage is unavailable. Export your backup; local records remain on this device.','云存储不可用，请导出备份；本地记录保留在此设备。')}</p>${btn(t('Export backup','导出备份'),'backup')}</section>`;
 if(!cloudIdentity?.user)return `${pageHead('account',t('Protect and sync your workspace','保护并同步工作区'))}<section class="card"><p>${t('Sign in with ChatGPT. Guest records stay local until you explicitly save them to your cloud workspace.','使用ChatGPT登录。访客数据在您明确保存到云端前保留在本地。')}</p><a class="btn primary" target="_top" href="/signin-with-chatgpt?return_to=%2F%23account">${t('Sign in with ChatGPT','使用ChatGPT登录')}</a>${btn(t('Export backup','导出备份'),'backup')}</section>`;
 if(!accountState.user)return `${pageHead('account',t('Choose where to work','选择工作位置'))}<section class="card"><h2>${esc(cloudIdentity.user.email)}</h2><p>${t('Your browser records are still active. Export a backup before switching. Creating workspaces seeds isolated synthetic businesses; it never overwrites existing cloud records.','当前仍使用浏览器记录，切换前请导出备份。创建工作区将添加独立模拟企业，不会覆盖现有云记录。')}</p>${btn(t('Export browser backup','导出浏览器备份'),'backup')}${btn(t('Open my cloud workspaces','打开我的云工作区'),'cloudinitialize','primary')}${aiStatus.identityMode==='supabase'?btn(t('Sign out','退出登录'),'signout'):''}${cloudIdentity.businesses?.filter(b=>b.owner!==cloudIdentity.user.id).map(b=>btn(t('Open shared workspace','打开共享工作区')+' · '+b.key,'cloudshared','',`data-owner="${esc(b.owner)}" data-key="${esc(b.key)}"`)).join('')}</section>`;
 return legacyAccountPage()+`<section class="card"><h2>${t('Backup and recovery','备份与恢复')}</h2>${btn(t('Export backup','导出备份'),'backup')}<label class="field">${t('Restore reviewed JSON backup (owner/accountant only)','恢复已核查JSON备份（企业主或会计）')}<input type="file" id="restorebackup" accept=".json,application/json" ${accountState.role==='viewer'?'disabled':''}></label>${btn(t('Server audit history','服务器审计记录'),'cloudaudit')}</section>`;}
async function openCloud(owner,key){accountState={...accountState,user:cloudIdentity.user,csrf:cloudIdentity.csrf,businesses:cloudIdentity.businesses,activeOwner:owner,sync:'offline'};await switchBusiness(key,owner,true);}
document.addEventListener('click',async e=>{const el=e.target.closest?.('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='cloudinitialize'){confirm(t('Open cloud records?','打开云端记录？'),`<p>${t('Export your browser backup first. Existing cloud data will be loaded; browser data is not automatically uploaded.','请先导出浏览器备份。将加载云数据，浏览器记录不会自动上传。')}</p>`,async()=>{try{cloudIdentity=await accountAPI('/api/initialize','POST',{});await openCloud(cloudIdentity.user.id,org);}catch{toast(t('Cloud storage could not initialize.','云存储初始化失败。'));}});}
 if(a==='cloudshared')await openCloud(el.dataset.owner,el.dataset.key);
 if(a==='cloudaudit'){try{const x=await accountAPI(apiPath('/api/cloud-audit'));modal(t('Server audit history','服务器审计记录'),x.events.map(x=>`<p>${esc(x.created_at)} · ${esc(x.event)} · ${esc(x.actor)}</p>`).join('')||t('No server changes yet.','尚无服务器变更。'));}catch{toast(t('Audit unavailable','审计记录不可用'));}}
 if(a==='saveplan'){try{const task=suggestPlan(data).find(x=>x.source===el.dataset.id&&x.kind===el.dataset.kind);confirm(t('Save this action plan?','保存此行动？'),`<p>${esc(task.source)} · ${money(task.amount,2)}</p><p>${t('No cash or invoice changes.','不会改变现金或发票。')}</p>`,()=>{try{commitQuick(addPlanTask(data,task));}catch{toast(t('This action is already saved.','此行动已保存。'));}});}catch{toast(t('Record unavailable','记录不可用'));}}
 if(a==='planstatus'){const x=data.actionPlan.find(x=>x.id===el.dataset.id);modal(t('Update planned action','更新计划行动'),`<form id="plantask" data-id="${esc(x.id)}"><label class="field">${t('Status','状态')}<select name="status">${[['planned','Planned','计划中'],['contacted','Contacted','已联系'],['agreed','Agreed','已约定'],['cancelled','Cancelled','已取消']].map(([v,en,zh])=>`<option value="${v}" ${x.status===v?'selected':''}>${t(en,zh)}</option>`).join('')}</select></label><label class="field">${t('Responsible person','负责人')}<input name="owner" maxlength="100" required value="${esc(x.owner)}"></label><label class="field">${t('Due date','截止日')}<input type="date" name="due" required value="${x.due}"></label><label class="field">${t('Note','备注')}<textarea name="note" maxlength="300">${esc(x.note)}</textarea></label><p>${t('Agreement is not a receipt. Record settlements separately.','达成约定不代表到账，结算需单独记录。')}</p><button class="btn primary" type="submit">${t('Review change','核查变更')}</button></form>`,' ');}
 if(a==='exportplan')download('Finora-action-plan-'+org+'.json',JSON.stringify({track:'E',snapshot:AS_OF,synthetic:true,actionPlan:data.actionPlan||[],evidence:suggestPlan(data)},null,2),'application/json');
 if(a==='reviewrow'){const b=data.importBatches.find(b=>b.id===el.dataset.batch),r=b.review.find(r=>r.id===el.dataset.id);modal(t('Review source row','核查来源行'),`<form id="reviewrowform" data-batch="${esc(b.id)}" data-id="${esc(r.id)}"><p>${esc(r.party)} · ${money(r.amount,2)} · ${esc(r.date)}</p><p>${esc(readinessReason(r.reason))}</p><label class="field">${t('Decision','处理方式')}<select name="decision"><option value="exclude">${t('Exclude: own transfer / duplicate / not a cash movement','排除：内部转账 / 重复 / 非现金流')}</option><option value="refund_out">${t('Refund paid out','已付退款')}</option><option value="refund_in">${t('Refund received','收到退款')}</option><option value="income">${t('Other cash received (not sales)','其他现金收入（非销售）')}</option><option value="expense">${t('Other cash spent','其他现金支出')}</option></select></label><p>${t('Check the original statement. Posting a row changes the ledger; exclusion does not.','请核对原始账单。入账会改变账本，排除不会。')}</p><button class="btn primary" type="submit">${t('Review decision','核查处理')}</button></form>`,' ');}
 if(a==='reconciledemo')download('Finora-reconciliation-demo.csv','id,date,type,category,party,amount,description\ndemo-sale,2026-10-12,income,sales,Demo customer,5000.00,Customer sale\ndemo-transfer,2026-10-12,income,other,Own bank account,5000.00,withdrawal to own bank\ndemo-refund,2026-10-12,expense,other,Demo customer,200.00,refund\n','text/csv');
});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='plantask'){e.preventDefault();const patch=Object.fromEntries(new FormData(f)),id=f.dataset.id;confirm(t('Confirm plan change','确认计划变更'),`<p>${esc(patch.status)} · ${esc(patch.due)}</p>`,()=>{try{commitQuick(updatePlanTask(data,id,patch));}catch{toast(t('Invalid task details','任务信息无效'));}});}
 if(f.id==='reviewrowform'){e.preventDefault();const decision=new FormData(f).get('decision'),batch=f.dataset.batch,id=f.dataset.id;confirm(t('Confirm reconciliation decision','确认对账处理'),`<p>${esc(decision)}</p>`,()=>{try{commitQuick(resolveImportReview(data,batch,id,decision));}catch{toast(t('Already resolved or invalid. No cash changed.','已处理或无效，现金未变更。'));}});}});
document.addEventListener('change',async e=>{if(e.target.id!=='restorebackup')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>1200000)throw Error();const n=JSON.parse(await file.text());validateData(n);if(n.org!==org)throw Error();confirm(t('Replace current records with this backup?','用此备份替换当前记录？'),`<p>${t('Export your current backup first. Cloud conflicts remain protected.','请先导出当前备份。云冲突保护仍生效。')}</p>`,()=>{commitQuick(n);});}catch{toast(t('Invalid backup or wrong business. Nothing changed.','备份无效或企业不匹配，未更改记录。'));}});
render();

function rescueDefaults(){return {invoiceId:data.invoices.filter(i=>i.kind==='receivable'&&outstanding(i)>0).sort((a,b)=>outstanding(b)-outstanding(a))[0]?.id||'',collectionDays:1,maxCollectionPercent:100,collectionCost:0,billId:data.invoices.filter(i=>i.kind==='payable'&&outstanding(i)>0).sort((a,b)=>outstanding(b)-outstanding(a))[0]?.id||'',maxDeferralDays:14,supplierFee:0,loanCap:10000000,loanStep:500000,apr:8,months:12,fee:1,reserve:data.settings.reserve};}
function rescueAmounts(r){return `<div class="numbers"><div><span>${t('Borrowing principal','借款本金')}</span><strong>${money(r.actions.principal,2)}</strong></div><div><span>${t('Lowest cash','最低现金')}</span><strong>${money(r.lowest,2)}</strong></div><div><span>${t('Remaining buffer gap','剩余备用金缺口')}</span><strong>${money(r.gap,2)}</strong></div><div><span>${t('Known full-term financing + action costs','已知全期融资与行动成本')}</span><strong>${money(r.knownCost,2)}</strong></div></div>`;}
function rescueActions(r,input){return `<ul class="list"><li>${t('Collect','催收')} ${r.actions.percent}% · ${esc(input.invoiceId||'—')} · ${r.actions.percent?date(addDays(AS_OF,input.collectionDays)):'—'}</li><li>${t('Supplier deferral','供应商延期')}: ${r.actions.deferralDays} ${t('days','天')} · ${esc(input.billId||'—')}</li><li>${t('Borrowing','借款')}: ${money(r.actions.principal,2)} · ${t('hypothetical terms','假设条款')}</li></ul>`;}
function rescuePage(){const input=rescueResult?.org===org?rescueResult.input:rescueDefaults(),receiptLike=rescueResult?{snapshot:JSON.parse(rescueResult.sourceStamp)}:null,current=rescueResult&&rescueResult.org===org&&receiptIsCurrent(data,receiptLike),sensitive=missingInformation(data)[0];
 const field=(name,en,zh,min,max,step=1,fen=false)=>`<label class="field">${t(en,zh)}<input name="${name}" type="number" required min="${min}" max="${max}" step="${step}" value="${fen?input[name]/100:input[name]}"></label>`;
 return `${pageHead('rescue',t('Cash Rescue Planner','现金纾困规划'))}<section class="card"><h2>${t('Your constraints. A plan you can inspect.','您的约束，可核查的方案。')}</h2><p>${t('Keep payroll unchanged, protect a cash buffer, and find the lowest borrowing among a visible set of plans. Every collection and deferral remains an unconfirmed external agreement.','保持工资安排、保护现金备用金，并在明确方案集合中寻找最低借款。回款与延期均需外部确认。')}</p><p class="small muted">${t('Topic E · ninety-day synthetic snapshot. No lender offers, payments or messages are executed.','赛题E · 九十天模拟快照。不执行贷款申请、付款或消息。')}</p></section><form id="rescueform"><section class="card"><h2>1 · ${t('Collections and supplier timing','回款与供应商时间')}</h2><div class="controls"><label class="field">${t('Customer invoice to test','测试客户发票')}<select name="invoiceId"><option value="">${t('Do not accelerate collections','不提前催收')}</option>${data.invoices.filter(i=>i.kind==='receivable'&&outstanding(i)>0).map(i=>`<option value="${esc(i.id)}" ${i.id===input.invoiceId?'selected':''}>${esc(i.id)} · ${money(outstanding(i),2)}</option>`).join('')}</select></label>${field('collectionDays','Collect after snapshot (days)','快照后回款天数',1,60)}${field('maxCollectionPercent','Maximum portion to request (%)','最多请求回款比例（%）',0,100)}${field('collectionCost','Cost if collection accelerated (CNY)','提前回款成本（人民币）',0,1000000,.01,true)}<label class="field">${t('Supplier bill to test','测试供应商账单')}<select name="billId"><option value="">${t('Do not defer a supplier bill','不延期供应商账单')}</option>${data.invoices.filter(i=>i.kind==='payable'&&outstanding(i)>0).map(i=>`<option value="${esc(i.id)}" ${i.id===input.billId?'selected':''}>${esc(i.id)} · ${money(outstanding(i),2)}</option>`).join('')}</select></label>${field('maxDeferralDays','Maximum supplier delay (days)','供应商最多延期天数',0,30)}${field('supplierFee','Assumed supplier deferral fee (CNY)','假设供应商延期费用（人民币）',0,1000000,.01,true)}</div><div class="info">${t('Fees default to zero as an editable assumption, not a verified quote. Confirm any penalties with the supplier. Only one receivable and one supplier bill are varied.','零费用仅为可修改假设，不是核实报价。请与供应商确认罚金。仅调整一笔应收与一笔供应商账单。')}</div></section><section class="card"><h2>2 · ${t('Buffer and borrowing limits','备用金与借款限制')}</h2><div class="controls">${field('reserve','Minimum cash buffer (CNY)','最低现金备用金（人民币）',0,1000000,.01,true)}${field('loanCap','Maximum borrowing (CNY)','最高借款（人民币）',0,1000000,100,true)}${field('loanStep','Borrowing search increment (CNY)','借款搜索步长（人民币）',1,1000000,1,true)}${field('apr','Annual nominal interest (%)','年名义利率（%）',0,100,.01)}${field('months','Loan term (months)','贷款期限（月）',1,60)}${field('fee','Upfront loan fee (%)','贷款前期费用（%）',0,20,.01)}</div><p class="small muted">${t('At most one hundred borrowing increments. Loan proceeds and installments affect cash. Full-term cost is shown, while cash is checked for ninety days. Payroll and recurring bills are never delayed.','最多一百个借款步长。借款到账与还款影响现金。显示全期成本，现金检查为九十天。工资与定期账单不延期。')}</p><button type="submit" class="btn primary" ${rescueBusy?'disabled':''}>${rescueBusy?t('Evaluating…','评估中…'):t('Find a possible rescue plan','寻找可行纾困方案')}</button><div id="rescueerror" role="status"></div></section></form>${rescueResult?`<section class="card"><h2>${rescueResult.selected.feasible?t('Best among the evaluated plans','已评估方案中的优选'):t('No evaluated plan meets every constraint','已评估方案均未满足全部约束')}</h2>${!current?`<div class="error">${t('Records or settings changed. Run the planner again before saving.','记录或设置已改变，保存前请重新运行。')}</div>`:''}<p>${rescueResult.evaluated} ${t('plans tested','项方案已测试')} · ${rescueResult.feasibleCount} ${t('meet the buffer','项满足备用金要求')}</p>${rescueAmounts(rescueResult.selected)}${rescueActions(rescueResult.selected,rescueResult.input)}<p>${t('Lowest balance date','最低余额日')}: ${date(rescueResult.selected.lowestDate)}</p><p class="small muted">${t('Ranked by lower borrowing first, then known cost, then less supplier delay. This is not a global optimum or a recommendation to borrow.','按借款较少、已知成本较低、供应商延期较短排序。不是全局最优或借款建议。')}</p>${rescueResult.selected.loan?`<p>${t('Typical monthly installment','通常月还款')}: ${money(rescueResult.selected.loan.monthlyPayment,2)} · ${rescueResult.selected.loan.termMonths} ${t('months','个月')}</p>`:''}<h3 style="margin-top:18px">${t('What if customers pay seven days later?','如果客户晚七天付款？')}</h3>${rescueAmounts(rescueResult.stress)}<p class="small muted">${t('The same selected plan is stressed, not re-optimized. This tests timing, not a probability.','对相同已选方案进行压力测试，不重新优化。这是时间测试，不是概率。')}</p><details><summary>${t('Other evaluated options','其他已评估方案')}</summary>${rescueResult.alternatives.map(a=>`<div class="documentrow">${badge(a.feasible?t('Meets buffer','满足备用金'):t('Gap remains','仍有缺口'),a.feasible?'green':'amber')}${rescueAmounts(a)}${rescueActions(a,rescueResult.input)}</div>`).join('')}</details><div class="evidence">${rescueResult.selected.evidence.map(id=>btn(esc(id),'evidence','',`data-id="${esc(id)}"`)).join('')}</div>${btn(t('Review and save Decision Receipt','核查并保存决策凭据'),'saverescue','primary',!current||accountState.role==='viewer'?'disabled':'')} ${btn(t('Saved receipts','已保存凭据'),'nav','','data-page="receipts"')}</section>`:''}${sensitive?`<section class="card"><h2>${t('Which missing fact matters most?','哪项待确认信息影响最大？')}</h2><p>${t('Confirm the payment date for','请确认回款日期')} <strong>${esc(sensitive.id)}</strong>.</p><p>${t('If this payment alone is seven days late, the baseline lowest cash worsens by','如果仅此款项晚七天到账，基准最低现金恶化')} ${money(sensitive.worsening,2)}.</p><p class="small muted">${t('Calculated one-invoice sensitivity; other records unchanged. A zero effect does not guarantee timely payment.','单笔发票敏感性计算，其他记录不变。零影响不保证及时回款。')}</p>${btn(t('Update promised date','更新承诺日期'),'nav','','data-page="collections"')}</section>`:''}`;
}
function receiptsPage(){const receipts=data.decisionReceipts||[];return `${pageHead('receipts',t('Saved assumptions, evidence and decisions.','已保存的假设、证据与决策。'))}<section class="card"><p>${t('These are planning records, not audited or tamper-proof certificates. Saving does not approve a loan or confirm customer/supplier agreement. Exports may contain your financial records.','这些是规划记录，不是审计或防篡改证明。保存不代表贷款批准或客户与供应商同意。导出可能包含财务记录。')}</p>${btn(t('Open planner','打开规划器'),'nav','primary','data-page="rescue"')}</section>${receipts.map(r=>`<section class="card"><h2>${esc(r.id.slice(0,8))} · ${esc(r.createdAt.slice(0,10))}</h2>${badge(receiptIsCurrent(data,r)?t('Matches current records','与当前记录一致'):t('Historical snapshot · records changed','历史快照 · 记录已改变'),'gray')}${rescueAmounts(r.selected)}${rescueActions(r.selected,r.input)}<p class="small muted">${t('Saved result never changes. Replay recalculates with current records and requires a new receipt to save.','已保存结果不会改变。重放使用当前记录重新计算，保存需要新建凭据。')}</p><div class="quickactions">${btn(t('Download readable receipt','下载可读凭据'),'receipttxt','',`data-id="${esc(r.id)}"`)}${btn(t('Download reproducible JSON','下载可重现JSON'),'receiptjson','',`data-id="${esc(r.id)}"`)}${btn(t('Replay with current records','用当前记录重放'),'replayreceipt','',`data-id="${esc(r.id)}"`)}</div></section>`).join('')||`<section class="card">${t('No saved decisions yet. Run the planner and review its assumptions first.','尚无已保存决策。请先运行规划器并核查假设。')}</section>`}`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='rescueform')return;e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{const raw={...values};for(const k of ['collectionDays','maxCollectionPercent','maxDeferralDays','apr','months','fee'])raw[k]=Number(raw[k]);for(const k of ['collectionCost','supplierFee','loanCap','loanStep','reserve'])raw[k]=Number(raw[k])===0?0:moneyInput(String(raw[k]));rescueBusy=true;const snapshot=structuredClone(data),owner=accountState.activeOwner,originOrg=org;render();await new Promise(resolve=>setTimeout(resolve,0));const result=planCashRescue(snapshot,raw);if(org!==originOrg||owner!==accountState.activeOwner)return;rescueResult=result;}catch{toast(t('Check amounts, dates and search limits. Borrowing cap must use at most one hundred increments.','请核查金额、日期与搜索限制。借款上限最多一百个步长。'));}finally{rescueBusy=false;render();}});
document.addEventListener('click',e=>{const el=e.target.closest?.('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='saverescue'&&rescueResult){const result=rescueResult,workspace=accountState.activeOwner,workspaceOrg=org;confirm(t('Save a planning Decision Receipt?','保存规划决策凭据？'),`<p>${t('You reviewed the assumptions. Collection and supplier agreements remain unconfirmed. This saves a snapshot only; no financial action is executed. Up to five recent receipts are retained; older ones may be removed to fit storage. Export receipts you need to keep.','您已核查假设。回款与供应商协议仍未确认。仅保存快照，不执行财务操作。最多保留最近五份凭据，容量不足时移除较早凭据。请导出需要保留的凭据。')}</p>`,()=>{try{if(workspace!==accountState.activeOwner||workspaceOrg!==org)throw Error('workspace');const receipt=createDecisionReceipt(data,result),next=retainDecisionReceipt(data,receipt);if(commitQuick(next))go('receipts');}catch(error){toast(error.message.includes('storage budget')?t('This snapshot is too large to save. Export records and reduce the workspace size first.','快照过大无法保存。请先导出记录并减少工作区大小。'):t('Records changed. Run the planner again.','记录已改变，请重新运行规划器。'));}});}
 if(['receipttxt','receiptjson','replayreceipt'].includes(action)){const r=data.decisionReceipts?.find(r=>r.id===el.dataset.id);if(!r)return;if(action==='receipttxt')download('Finora-decision-'+r.id+'.txt',decisionReceiptText(r));if(action==='receiptjson')download('Finora-decision-'+r.id+'.json',JSON.stringify(r,null,2),'application/json');if(action==='replayreceipt'){try{rescueResult=planCashRescue(data,r.input);go('rescue');toast(t('Replayed with current records. Historical receipt unchanged.','已用当前记录重放，历史凭据未改变。'));}catch{toast(t('A source invoice may be settled or missing. Choose current records in the planner.','来源发票可能已结清或缺失，请在规划器选择当前记录。'));rescueResult=null;go('rescue');}}}
});
render();

// Structured PDF receipts: document text is data, never executable instructions.
function pdfError(error){const key=String(error.message).split(':')[0];const messages={business:['Wrong business. Switch to the Business ID shown in the PDF, then upload and preview again.','企业不匹配。请切换到PDF标识的企业，然后重新上传预览。'],duplicate:['Possible duplicate: this receipt ID or the same date, direction, counterparty and total already exists. No transaction added.','疑似重复：收据编号或日期、收支方向、交易方、总额与已有记录相同，未新增交易。'],total:['Subtotal + tax must equal total within one fen (CN¥0.01).','税前金额加税额必须与总额一致，容差为1分。'],date:[`Use a real date after ${data.openingDate} and on/before ${AS_OF}.`,`日期必须真实，晚于${data.openingDate}且不晚于${AS_OF}。`],invoiceId:['Invoice not found, wrong direction/counterparty, or payment exceeds its outstanding amount. Check the existing invoice.','发票不存在、方向/交易方不匹配或付款超过未付金额，请核查发票。'],currency:['Only CNY receipts are supported.','仅支持人民币CNY收据。'],'image-only':['This PDF has no selectable text. Use manual entry; scanned receipt OCR is not supported.','此PDF没有可选择文本。请手动录入；不支持扫描收据OCR。'],unsupported:['Use a text PDF with FINORA RECEIPT V1 labels, up to 2 MB and 3 pages. Manual entry is available.','请使用含FINORA RECEIPT V1字段的文本PDF，最大2MB、3页；可手动录入。']};return messages[key]?t(...messages[key]):t('Check required fields, two-decimal positive CNY amounts, and payment confirmation. Nothing was saved.','请核查必填字段、两位小数的正数人民币金额及付款确认，尚未保存。');}
function pdfReceiptPage(){const current=pdfDraft?.context===pdfContext(),saved=!current&&lastReceiptPosted?.context===pdfContext()?data.transactions.find(x=>x.id===lastReceiptPosted.id&&x.org===org&&!x.voidedAt):null;if(saved)return receiptSuccessPage(saved);return `${workflowHead('pdfreceipts',current?t('Check the extracted details before saving.','保存前请核对提取信息。'):t('Choose a supported text PDF. Details open for review after extraction.','请选择支持的文本PDF，提取后会打开核对信息。'),current?2:1,current?t('Review receipt','核对收据'):t('Upload PDF receipt','上传PDF收据'))}<section class="card pdf-upload ${current?'compact':''}"><h2>${current?t('Selected receipt','已选择收据'):t('Select file','选择文件')}</h2>${current?`<div class="file-summary"><span class="workspace-symbol">${workspaceIcon('upload')}</span><div><strong>${esc(pdfDraft.fileName||t('Receipt PDF','收据PDF'))}</strong><p class="small muted">${pdfDraft.fileSize?Math.ceil(pdfDraft.fileSize/1024)+' KB · ':''}${t('Extracted locally · unverified','本地提取 · 未经验证')}</p></div></div>`:''}<p>${t('Selectable text · FINORA RECEIPT V1 · up to 2 MB / 3 pages. No OCR or official fapiao verification. Original PDF stays on this device; confirmed transaction fields sync normally.','可选择文本 · FINORA RECEIPT V1 · 最大2MB/3页。不支持OCR，也不代表官方发票查验。PDF原件保留在设备上，确认后的交易字段按正常方式同步。')}</p><p class="small muted">${t('Workspace','当前企业')}: <strong>${esc(org)}</strong> · ${t('Reporting snapshot','报告快照')}: ${AS_OF}</p><div class="pdf-picker"><label class="pdf-dropzone" for="pdfreceiptfile"><span class="workspace-symbol">${workspaceIcon('upload')}</span><strong>${current?t('Replace file','更换文件'):t('Choose PDF','选择PDF')}</strong><span>${t('Selectable text · up to 2 MB','需可选择文本 · 最大2MB')}</span></label><input id="pdfreceiptfile" aria-label="${t('Choose PDF receipt','选择PDF收据')}" type="file" accept=".pdf,application/pdf" ${pdfBusy?'disabled':''}></div><p role="status">${pdfBusy?t('Extracting…','正在提取…'):''}</p><div class="quickactions">${btn(t('Manual money entry','手动收支录入'),'quickincome')}</div><details><summary>${t('Supported layout and rules','支持的格式与规则')}</summary><p>${t('Use one labeled field per line, in this order. Direction: INCOME / EXPENSE; Currency: CNY; amounts: 123.45; optional Invoice Reference: NONE. Payment Status is document evidence only, not proof of payment.','每行一个字段，按以下顺序排列。Direction使用INCOME/EXPENSE，Currency使用CNY，金额如123.45，可选Invoice Reference使用NONE。Payment Status仅为文件信息，不是付款证明。')}</p><pre class="receipt-source">FINORA RECEIPT V1\n${receiptFields.map(([,en])=>en+': …').join('\n')}</pre></details></section>${pdfDraft&&!current?`<div class="error" role="alert">${t('Workspace changed. Upload and preview this receipt again.','企业工作区已变更，请重新上传并预览。')}</div>`:''}${current?`<section class="card receipt-review"><h2>${t('Review extracted fields','核对提取字段')}</h2><p>${t('No cash changed. Edit missing or incorrect values. Uploading does not mean payment occurred.','现金尚未改变。请修正缺失或错误字段。上传不代表已付款。')}</p><form id="pdfreviewform"><div class="receipt-fields">${receiptFields.map(([key,en,zh])=>`<div class="field"><label for="pdf-${key}">${t(en,zh)} ${key==='invoiceId'?t('(optional)','（可选）'):''}</label>${key==='type'?`<select id="pdf-${key}" name="${key}" required><option value="">${t('Select','请选择')}</option><option value="income" ${pdfDraft.fields[key]==='income'?'selected':''}>${t('Money received','收款')}</option><option value="expense" ${pdfDraft.fields[key]==='expense'?'selected':''}>${t('Money spent','支出')}</option></select>`:`<input id="pdf-${key}" name="${key}" ${key==='date'?'type="date"':(['subtotal','tax','total'].includes(key)?'inputmode="decimal" pattern="[0-9]+\\.[0-9]{2}"':'')} ${key==='businessId'?'readonly':''} ${key==='invoiceId'?'':'required'} maxlength="${key==='description'?300:100}" value="${esc(pdfDraft.fields[key])}">`}</div>`).join('')}</div><div class="info">${t('Rounding tolerance: CN¥0.01. Printed total is posted in integer fen. Linking requires the existing invoice counterparty and remaining balance to match.','舍入容差为人民币0.01元，按收据总额以整数分入账。关联时，交易方及未付余额必须与已有发票匹配。')}</div><label class="receipt-paid"><input type="checkbox" name="paid" required> ${t('I confirm this money was actually received / paid. This is not an unpaid invoice.','我确认此款项已实际收到/付出，并非未付款发票。')}</label><button class="btn primary" type="submit">${t('Validate and review posting','验证并核对入账')}</button></form><details><summary>${t('Source text / evidence (unverified)','原始文本/证据（未经验证）')}</summary><pre class="receipt-source">${esc(pdfDraft.text)}</pre></details></section>`:''}`;}
function pdfContext(){return JSON.stringify([org,accountState.activeOwner,accountState.user?.id||'guest',pdfEpoch]);}
document.addEventListener('change',async e=>{if(e.target.id!=='pdfreceiptfile')return;const file=e.target.files?.[0];if(!file)return;const context=pdfContext();pdfBusy=true;pdfDraft=null;lastReceiptPosted=null;render();try{const result=await extractReceiptPDF(await file.arrayBuffer());if(context!==pdfContext())throw Error('business');pdfDraft={...result,context,fileName:file.name,fileSize:file.size};}catch(error){if(context===pdfContext()){if(page==='pdfreceipts')showPdfFallback(error);else toast(pdfError(error));}}finally{pdfBusy=false;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='pdfreviewform'){e.preventDefault();try{if(!pdfDraft||pdfDraft.context!==pdfContext())throw Error('business');const fields=Object.fromEntries(new FormData(e.target));pdfDraft.fields={...fields};const amounts=validateReceipt(fields,data),paid=fields.paid==='on',context=pdfContext();if(!paid)throw Error('payment');const snapshot=financialStamp();confirm(t('Confirm paid transaction','确认已付款交易'),`<p>${esc(fields.receiptId)} · ${esc(fields.party)} · <strong>${money(amounts.total,2)}</strong></p><p>${fields.type==='income'?t('Recorded cash will increase.','已记录现金将增加。'):t('Recorded cash will decrease.','已记录现金将减少。')}</p><p>${fields.invoiceId?`${t('Settle invoice once','一次结算发票')}: ${esc(fields.invoiceId)}`:t('No invoice linked.','未关联发票。')}</p><p>${t('Extraction does not verify authenticity or make a real bank payment.','字段提取不验证真实性，也不会执行真实银行付款。')}</p>`,()=>{try{if(context!==pdfContext()||snapshot!==financialStamp())throw Error('business');const next=postReceipt(data,fields,{confirmed:true,paid,role:accountState.user?accountState.role:'owner'});if(commitQuick(next)){pdfDraft=null;lastReceiptPosted={id:'PDF-'+fields.receiptId,context:pdfContext()};go('pdfreceipts');toast(t('Receipt posted once. Cash and forecast refreshed.','收据已入账一次，现金及预测已更新。'));}}catch(error){toast(pdfError(error));}});}catch(error){toast(pdfError(error));}}
 if(e.target.id==='bufferform'){e.preventDefault();try{const value=new FormData(e.target).get('reserve'),reserve=/^0(?:\.0{1,2})?$/.test(value)?0:moneyInput(value);const next=structuredClone(data);next.settings.reserve=reserve;next.audit.unshift({date:new Date().toISOString(),action:'settings',record:org});if(commitQuick(next))showSafeDetails();}catch{toast(t('Enter a valid non-negative CNY amount, up to 1,000,000.','请输入有效的非负人民币金额，上限100万元。'));}}
});
function showSafeDetails(){const s=safeToSpend(data),f=forecast(data),point=f.points.find(p=>p.date===s.date),opening=s.lowest===s.current,obligations=f.events.filter(e=>e.kind==='payable'&&e.date<=s.date).sort((a,b)=>b.amount-a.amount).slice(0,5);modal(t('Your safe-to-spend estimate','您的可支出规划估计'),`<p><strong>${t('Planning estimate, not permission or a guarantee to spend.','规划估计，并非支出许可或保证。')}</strong></p><p class="small muted">${esc(businessName())} · ${t('Synthetic reporting snapshot','模拟报告快照')}: ${AS_OF} · ${t('Base forecast, no stress assumptions','基准预测，未应用压力假设')}</p><ol class="safe-breakdown"><li>${t('Money available now','现在可用的钱')}: <strong>${money(s.current,2)}</strong></li><li>${t('Lowest expected balance over 30 days','未来30天最低预计余额')}: <strong>${money(s.lowest,2)}</strong></li><li>${t('Emergency cash buffer to preserve','希望保留的应急备用金')}: <strong>${money(s.buffer,2)}</strong></li><li>${t('Estimated amount for additional spending','可用于额外支出的估计金额')}: <strong>${money(s.available,2)}</strong></li><li>${t('Lowest-balance date','最低余额日期')}: ${esc(s.date)}<br>${opening?t('Current cash is the lowest projected point. Future balances are not lower in this base forecast.','当前现金就是预测最低点。基准预测的未来余额没有更低。'):t('Pressure on this date','当天压力')+': '+esc(point?.evidence.join(', ')||t('Daily sales and operating costs','日常销售及运营成本'))}</li></ol>${obligations.length?`<p class="small">${t('Scheduled outflows up to this low point','截至最低点的计划支出')}: ${obligations.map(e=>esc(e.id)+' · '+esc(e.date)+' · '+money(e.amount,2)).join('; ')}</p>`:''}${!s.available?`<div class="error">⚠ ${s.current<=0?t('Recorded cash is zero or negative.','已记录现金为零或负数。'):s.lowest<=s.buffer?t('The lowest expected balance does not exceed your emergency buffer.','最低预计余额不足以超过应急备用金。'):t('No additional cash is available under these assumptions.','在这些假设下没有可用于额外支出的现金。')}</div>`:''}<p>${t('The buffer is money you want to keep. It is not a new expense and does not deduct money from a bank account.','备用金是您希望保留的钱，不是新支出，也不会从银行账户扣款。')}</p><p class="small muted">${t('Forecast includes the opening day, recent daily sales/operating averages, remaining expected invoice collections, unpaid bills and recurring payroll/rent. Settled amounts are excluded from future invoice balances.','预测包含期初日、近期日均销售/运营成本、剩余预计回款、未付账单及经常性工资/租金。已结算金额不再计入未来发票余额。')}</p><div class="quickactions">${btn(t('Edit emergency buffer','编辑应急备用金'),'editbuffer')} ${btn(t('View forecast details','查看预测详情'),'safeforecast')} ${btn(t('Test customer payment delay','测试客户延迟付款'),'safestress')}</div><details><summary>${t('Full formula','完整公式')}</summary><p>max(0, min(${money(s.current,2)}, ${money(s.lowest,2)} − ${money(s.buffer,2)})) = ${money(s.available,2)}</p></details>`);}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='editbuffer')modal(t('Edit emergency buffer','编辑应急备用金'),`<form id="bufferform"><label for="edit-reserve">${t('Cash to preserve (CNY)','希望保留的现金（人民币）')}</label><input id="edit-reserve" name="reserve" type="number" min="0" max="1000000" step=".01" value="${data.settings.reserve/100}" required><p>${t('Saving updates the planning estimate immediately; it does not create an expense.','保存后立即更新规划估计，不会新增支出。')}</p><button class="btn primary" type="submit">${t('Save buffer','保存备用金')}</button></form>`,'');if(a==='safeforecast'||a==='safestress'){$('#modalroot').innerHTML='';scenario={days:30,growth:0,expense:0,hiring:0,supplierDelay:0,oneOff:0,delay:a==='safestress'?14:0};go('cash');}});

// One read-only guide, with detached live DOM to preserve unsaved forms and file inputs.
const tourRuntime={instance:null,opening:false};
const guideContext=()=>accountState.user?.id||cloudIdentity?.user?.id||'guest';
const guideUIStamp=()=>JSON.stringify([data,aiStatus,aiHealth,providerMode,pending,pdfBusy,pdfDraft,statementPreview,invoiceDraft,rescueBusy,rescueResult,accountState.sync,accountState.revision,accountState.role]);
function buildFinoraGuide(){
 let snapshot=null;
 return createTour({language:()=>lang,context:guideContext,storage:localStorage,environment:()=>({role:accountState.user?accountState.role:'owner',signedIn:!!accountState.user}),
  onBegin:()=>{snapshot={page,hash:location.hash,filter,org,context:guideContext(),stamp:guideUIStamp(),focus:document.activeElement,scrollX:window.scrollX,scrollY:window.scrollY,surface:preserveTourSurface($('#app'),$('#modalroot'))};},
  navigate:route=>{page=route;render();},
  onClose:()=>{if(!snapshot)return;page=snapshot.page;filter=snapshot.filter;if(guideContext()===snapshot.context&&org===snapshot.org){if(guideUIStamp()===snapshot.stamp)snapshot.surface.restore();else{snapshot.surface.refresh(render);confirmCallback=null;toast(t('The latest results are shown; your form drafts are preserved. Review any action again before confirming.','已显示最新结果，并保留表单草稿。确认操作前请重新核查。'));}}else{snapshot.surface.discard();confirmCallback=null;render();toast(t('The active account or business changed. The latest workspace is shown.','当前账号或企业已变更，现显示最新工作区。'));}window.scrollTo({left:snapshot.scrollX,top:snapshot.scrollY,behavior:'instant'});snapshot=null;}
 });
}
function openFinoraGuide(mode='menu'){
 if(!document.body?.append||tourRuntime.opening)return;if(pending||pdfBusy||rescueBusy){toast(t('Wait for the current calculation or extraction to finish, then open the demo. Your draft is preserved.','请等待当前计算或提取完成后再打开演示，草稿会保留。'));return;}tourRuntime.opening=true;
 try{if(!tourRuntime.instance)tourRuntime.instance=buildFinoraGuide();if(tourRuntime.instance.active)return;if(mode==='welcome')tourRuntime.instance.welcome();else tourRuntime.instance.menu();}finally{tourRuntime.opening=false;}
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action]')?.dataset.action==='starttour')openFinoraGuide();});
// Wait for initial identity discovery, without delaying app access or overriding an active form.
if(document.body?.append)Promise.resolve(initialAccountReady).finally(()=>{if(!welcomeSeen(localStorage,guideContext())&&!$('#modalroot').childNodes.length&&!document.activeElement?.matches?.('input,textarea,select'))openFinoraGuide('welcome');});

// Present the original deterministic estimate without turning a zero into an alarm.
function safeGaugePanel(s){const g=cashGauge(s);return `<section class="card safe-planning"><div class="cardhead"><h2>${t('Room for additional spending','额外支出空间')}</h2>${btn(t('How it works','计算说明'),'safedetail')}</div><p class="small muted">${t('Safe-to-spend planning estimate · 30 days · base forecast','30天可支出规划估计 · 基准预测')}</p><strong class="spending-estimate">${s.available>0?money(s.available,2):t('No extra room right now','目前没有额外支出空间')}</strong><div class="cash-gauge" role="img" aria-label="${esc(t(`Recorded cash ${money(s.current,2)}. Lowest projected cash ${money(s.lowest,2)}. Emergency buffer ${money(s.buffer,2)}. Additional spending estimate ${money(s.available,2)}.`,`已记录现金${money(s.current,2)}，最低预计现金${money(s.lowest,2)}，应急备用金${money(s.buffer,2)}，额外支出估计${money(s.available,2)}。`))}"><div class="gauge-label"><span>${t('Recorded cash','已记录现金')}</span><strong>${money(s.current,2)}</strong></div><div class="gauge-track"><i class="gauge-current" style="width:${g.currentPercent}%"></i></div><div class="gauge-label"><span>${t('Lowest projected cash','最低预计现金')}</span><strong>${money(s.lowest,2)}</strong></div><div class="gauge-track"><i class="gauge-projected" style="width:${g.forecastPercent}%"></i><i class="gauge-buffer" style="width:${g.bufferPercent}%"></i></div><div class="gauge-legend"><span><i></i>${t('Emergency buffer zone','应急备用金区域')} · ${money(s.buffer,2)}</span><span>${date(s.date)} · ${t('lowest point','最低点')}</span></div></div>${g.shortfall?`<p class="cash-shortfall" role="status">⚠ ${t('Projected shortfall','预计现金缺口')}: <strong>${money(g.shortfall,2)}</strong> · ${date(s.date)}</p>`:''}<p class="cash-story">${s.available>0?t(`Your recorded cash is ${money(s.current,2)}. After expected bills and preserving your ${money(s.buffer,2)} buffer, the base forecast leaves an estimated ${money(s.available,2)} for additional spending.`,`已记录现金为${money(s.current,2)}。考虑预计账单并保留${money(s.buffer,2)}备用金后，基准预测估计有${money(s.available,2)}可用于额外支出。`):s.current<=0?t('Recorded cash is zero or negative, so there is no additional spending room. Review your entries and forecast.','已记录现金为零或负数，因此没有额外支出空间。请核查收支记录及预测。'):t(`Your recorded cash is ${money(s.current,2)}, but upcoming bills and your safety buffer mean you have no extra room right now. See your forecast for details.`,`已记录现金为${money(s.current,2)}，但考虑即将到期的账单与应急备用金后，目前没有额外支出空间。请查看预测详情。`)}</p>${s.lowest===s.current?`<p class="small muted">${t('Current cash is the lowest projected point; future projected balances do not fall below it.','当前现金就是预测最低点，未来预计余额不会低于当前现金。')}</p>`:''}<p class="small muted">${t('The buffer is money you want to preserve, not an expense or bank deduction. Planning estimate, not permission or a guarantee to spend.','备用金是希望保留的钱，不是支出或银行扣款。此为规划估计，并非支出许可或保证。')}</p><div class="quickactions">${btn(t('View forecast details','查看预测详情'),'nav','','data-page="cash"')}${btn(t('Edit emergency buffer','编辑应急备用金'),'editbuffer','',accountState.user&&accountState.role==='viewer'?'disabled':'')}</div></section>`;}
function showPdfFallback(error){const writable=!accountState.user||accountState.role!=='viewer';modal(t('Enter this receipt manually?','手动录入此收据？'),`<p>${t("We can't read this PDF automatically. Would you like to enter this receipt manually?","无法自动读取此PDF，是否手动录入此收据？")}</p><p class="small muted">${esc(['unsupported','image-only'].includes(String(error?.message).split(':')[0])?pdfError(error):t('The PDF could not be processed. It may be damaged, protected, or unavailable. Try another supported PDF or enter the values manually.','此PDF无法处理，可能已损坏、受保护或暂不可用。请尝试其他支持的PDF，或手动填写。'))}</p><div class="info">${t('No record was saved. Scans require OCR, which is not available here. For manual entry, choose whether money was actually received or spent, then review before confirming.','尚未保存记录。扫描件需要OCR识别，此处不提供该功能。手动录入时，请选择实际收款或支出，核对后再确认。')}</div>${!writable?`<p>${t('Your access is read-only. Ask an owner or accountant to enter a paid receipt.','您的权限为只读，请企业主或会计录入已付款收据。')}</p>`:''}<div class="quickactions">${btn(t('Enter money received','手动记录收款'),'quickincome','primary',writable?'':'disabled')}${btn(t('Enter money spent','手动记录支出'),'quickexpense','',writable?'':'disabled')}${btn(t('Choose another PDF','选择其他PDF'),'closemodal')}</div>`);}
document.addEventListener('click',e=>{if(e.target.closest('[data-action]')?.dataset.action!=='privacy')return;modal(t('Security & Privacy','安全与隐私'),`<p>${t('PDF extraction runs locally; the original receipt stays on your device. Only confirmed transaction fields are saved.','PDF在本地提取，原始收据保留在您的设备上，只有确认后的交易字段才会保存。')}</p><p>${t('Guest demo records are browser-local. Signed-in business records synchronize with this Site and follow owner, accountant and viewer permissions. Export a backup from Settings & data.','访客演示记录保存在浏览器本地。登录后的企业记录同步至本站，并遵循企业主、会计及只读权限。可在“设置与数据”导出备份。')}</p><p>${t('Live AI requires your consent and receives your question and calculated context. No bank passwords are collected, no payments are executed, and extraction is not official fapiao verification.','实时AI需要您的同意，并接收问题与计算上下文。不收集银行密码，不执行付款，字段提取也不是官方发票查验。')}</p>`,btn(t('Close','关闭'),'closemodal'));});

// Native constraints remain authoritative; show the same localized message inline and to AT.
document.addEventListener('invalid',e=>{const field=e.target;if(!field.matches?.('input,select,textarea'))return;const message=t('Check this field: enter a valid value within the displayed limits.','请核查此项：填写符合所示范围与格式的有效值。');field.setAttribute('aria-invalid','true');field.setCustomValidity?.(message);if(!field.id)return;const id='validation-'+field.id;let error=$('#'+id);if(!error){error=document.createElement('p');error.setAttribute('id',id);error.className='field-error';error.setAttribute('role','alert');field.parentElement?.append(error);}error.textContent=message;const ids=new Set((field.getAttribute('aria-describedby')||'').split(' ').filter(Boolean));ids.add(id);field.setAttribute('aria-describedby',[...ids].join(' '));},true);
document.addEventListener('input',e=>{const field=e.target;if(field.getAttribute?.('aria-invalid')!=='true')return;field.removeAttribute('aria-invalid');field.setCustomValidity?.('');const id='validation-'+field.id;$('#'+id)?.remove();const ids=(field.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!==id);if(ids.length)field.setAttribute('aria-describedby',ids.join(' '));else field.removeAttribute('aria-describedby');});

// Configuration, consent and last-response mode are different states; never conflate them.
function assistantConnectionText(){
 if(aiStatus.mode!=='configured')return t('Calculated assistant · Gemini not configured','计算助手 · 尚未配置Gemini');
 if(!aiStatus.authenticated)return t('Gemini configured · sign in to enable','Gemini已配置 · 请登录后启用');
 if(!liveRequested)return t('Gemini configured · enable live AI below','Gemini已配置 · 请在下方启用实时AI');
 if(pending)return t('Contacting Gemini…','正在连接Gemini…');
 if(data.chats.at(-1)?.aiFailure)return t('Gemini enabled · last reply used fallback','Gemini已启用 · 上次回答使用计算回退');
 const latest=data.chats.at(-1),verified=latest?.live&&latest.aiVersion===2&&latest.aiLang===lang&&latest.aiStamp===financialStamp()&&!!latest.aiExplanation;
 return verified?t('Live Gemini reply verified · engine-calculated figures','Gemini实时回答已验证 · 数字由引擎计算'):t('Gemini enabled · ready for your question','Gemini已启用 · 可以提问');
}
function assistantLiveControls(){
 const settings=btn(t('AI settings','AI设置'),'nav','','data-page="ai"');
 if(aiStatus.mode!=='configured')return `<p class="small muted">${t('Using calculated answers. Check the server connection in AI settings.','当前使用计算型回答，请在AI设置检查服务器连接。')}</p>${btn(t('Check connection','检查连接'),'checkai')} ${settings}`;
 if(!aiStatus.authenticated)return `<p class="small muted">${t('Gemini is configured. Sign in, then explicitly enable it to send questions and calculated context.','Gemini已配置。请登录后明确启用，才会发送问题及计算上下文。')}</p><a class="btn primary" href="${aiStatus.identityMode==='supabase'?'/#account':'/signin-with-chatgpt?return_to=%2F%23copilot'}" ${aiStatus.identityMode==='supabase'?'data-action="nav" data-page="account"':''} target="_top">${t('Sign in to use Gemini','登录以使用Gemini')}</a> ${settings}`;
 if(!liveRequested)return `<p class="small muted">${t('You are signed in. Enable Gemini here to use live explanations. Existing replies remain labeled as calculated or live.','您已登录，可在此启用Gemini实时解释。已有回答仍保留计算型或实时标记。')}</p>${btn(t('Enable live Gemini','启用实时Gemini'),'requestliveai','primary')} ${settings}`;
 return `<p class="small muted">${t('Live Gemini is enabled for this tab. Ask a new question below. Calculations and evidence still come from Finora.','此标签页已启用实时Gemini。请在下方重新提问，计算及证据仍由Finora提供。')}</p>${btn(t('Turn off live AI','关闭实时AI'),'disableliveai')} ${settings}`;
}
// Update only activation UI, retaining the chat input, open panel and all financial drafts.
function refreshAIControls(){
 for(const n of document.querySelectorAll?.('[data-ai-connection]')||[])n.textContent=assistantConnectionText();
 for(const n of document.querySelectorAll?.('.ai-activation')||[])n.innerHTML=assistantLiveControls();
 const checkbox=$('#liveconsent');if(checkbox){checkbox.checked=liveRequested;checkbox.disabled=aiStatus.mode!=='configured'||!aiStatus.authenticated;}
 for(const n of document.querySelectorAll?.('[data-action="testai"]')||[])n.disabled=!liveRequested||!aiStatus.authenticated||aiStatus.mode!=='configured';
}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='requestliveai'){
  if(aiStatus.mode!=='configured'||!aiStatus.authenticated)return;
  modal(t('Enable live Gemini?','启用实时Gemini？'),`<p>${t('By enabling, you agree to send your question, up to four previous questions, reviewed assumptions and calculated results to Gemini for live explanations.','启用即表示您同意将当前问题、最多四条历史问题、已核对假设及计算结果发送给Gemini以获得实时解释。')}</p><p>${t('Raw ledgers and receipt documents are not sent to the model. Avoid private names in questions. Enabling does not send a question, change records or execute financial actions. You can turn it off anytime.','不向模型发送原始账本或收据文件。提问时请勿包含隐私姓名。启用不会自动发送问题、修改记录或执行财务操作，可随时关闭。')}</p><div class="quickactions">${btn(t('Cancel','取消'),'closemodal')}${btn(t('Agree and enable Gemini','同意并启用Gemini'),'enableliveai','primary')}</div>`);
 }
 if(action==='enableliveai'){
  if(aiStatus.mode!=='configured'||!aiStatus.authenticated)return;
  liveRequested=true;closeModal();refreshAIControls();$('#chatinput')?.focus();
 }
 if(action==='disableliveai'){liveRequested=false;refreshAIControls();$('#chatinput')?.focus();}
});

